 score REAL NOT NULL, PRIMARY KEY(artist_id,origin_id)
) WITHOUT ROWID;

CREATE INDEX ix_discovery_artist_origin ON discovery_artist_sources(origin_id,artist_id);

CREATE TABLE discovery_impressions (
