 album_id INTEGER REFERENCES albums(id), shown_at REAL NOT NULL,
 CHECK((recording_id IS NOT NULL)+(artist_id IS NOT NULL)+(album_id IS NOT NULL)=1)
,CONSTRAINT ck_discovery_impressions_shown_at CHECK(typeof(shown_at) IN ('integer','real') AND abs(shown_at)<=1.7976931348623157e308));

CREATE UNIQUE INDEX ix_discovery_view_recording ON discovery_impressions(view_id,recording_id) WHERE recording_id IS NOT NULL;

CREATE UNIQUE INDEX ix_discovery_view_artist ON discovery_impressions(view_id,artist_id) WHERE artist_id IS NOT NULL;

CREATE UNIQUE INDEX ix_discovery_view_album ON discovery_impressions(view_id,album_id) WHERE album_id IS NOT NULL;

CREATE INDEX ix_discovery_impression_recording ON discovery_impressions(recording_id,shown_at) WHERE recording_id IS NOT NULL;

CREATE INDEX ix_discovery_impression_artist ON discovery_impressions(artist_id,shown_at) WHERE artist_id IS NOT NULL;

CREATE INDEX ix_discovery_impression_album ON discovery_impressions(album_id,shown_at) WHERE album_id IS NOT NULL;

CREATE TABLE unresolved_discovery_impressions (
 view_id TEXT NOT NULL, original_kind TEXT NOT NULL, original_key TEXT NOT NULL, shown_at REAL NOT NULL,
 reason TEXT NOT NULL CHECK(reason IN ('missing_owner','ambiguous_owner','unsupported_kind')),
 PRIMARY KEY(view_id,original_kind,original_key)
,CONSTRAINT ck_unresolved_discovery_impressions_shown_at CHECK(typeof(shown_at) IN ('integer','real') AND abs(shown_at)<=1.7976931348623157e308)) WITHOUT ROWID;

CREATE TABLE discovery_legacy_offers (
 id INTEGER PRIMARY KEY, recording_id INTEGER REFERENCES recordings(id),
 artist_id INTEGER REFERENCES artists(id), album_id INTEGER REFERENCES albums(id),
 offered_count INTEGER NOT NULL CHECK(offered_count>=0), first_shown REAL, last_shown REAL,
 CHECK((recording_id IS NOT NULL)+(artist_id IS NOT NULL)+(album_id IS NOT NULL)=1)
,CONSTRAINT ck_discovery_legacy_offers_offered_count CHECK(typeof(offered_count)='integer' AND offered_count>=0),CONSTRAINT ck_discovery_legacy_offers_first_shown CHECK(first_shown IS NULL OR (typeof(first_shown) IN ('integer','real') AND abs(first_shown)<=1.7976931348623157e308)),CONSTRAINT ck_discovery_legacy_offers_last_shown CHECK(last_shown IS NULL OR (typeof(last_shown) IN ('integer','real') AND abs(last_shown)<=1.7976931348623157e308)));

CREATE UNIQUE INDEX ix_discovery_legacy_recording ON discovery_legacy_offers(recording_id) WHERE recording_id IS NOT NULL;

CREATE UNIQUE INDEX ix_discovery_legacy_artist ON discovery_legacy_offers(artist_id) WHERE artist_id IS NOT NULL;

CREATE UNIQUE INDEX ix_discovery_legacy_album ON discovery_legacy_offers(album_id) WHERE album_id IS NOT NULL;

CREATE VIEW discovery_origin_tokens AS
 SELECT o.id,o.kind,o.account_id,
 CASE o.kind
   WHEN 'album' THEN (SELECT provider_id FROM album_primary_provider_ids WHERE album_id=o.album_id AND provider='youtube')
   WHEN 'radio' THEN 'radio:'||o.seed_video_id
   WHEN 'genre' THEN 'genre:'||o.genre_key
   WHEN 'artist' THEN 'artist:'||(SELECT min(provider_id) FROM artist_provider_ids WHERE artist_id=o.artist_id AND provider='youtube')
   WHEN 'artist_start' THEN 'artist_start:'||(SELECT min(provider_id) FROM artist_provider_ids WHERE artist_id=o.artist_id AND provider='youtube')
   WHEN 'spotify_export' THEN 'spotify_export:'||o.account_id
   WHEN 'legacy_unknown' THEN o.legacy_source_key
   ELSE o.kind END source_token
 FROM discovery_origins o;

CREATE TABLE play_events (
 id INTEGER PRIMARY KEY,
 account_id INTEGER NOT NULL REFERENCES accounts(id),
 raw_identity_key TEXT,
 recording_id INTEGER REFERENCES recordings(id),
 unresolved_subject_key TEXT,
 video_id TEXT, played_at REAL NOT NULL, playlist_ytm_id TEXT,
 membership_ref_id INTEGER REFERENCES playlist_membership_refs(id), like_status TEXT,
 is_generated INTEGER CHECK(is_generated IN (0,1)),
 CHECK((recording_id IS NOT NULL AND unresolved_subject_key IS NULL)
    OR (recording_id IS NULL AND unresolved_subject_key IS NOT NULL))
);

CREATE TABLE listening_observations (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 account_id INTEGER NOT NULL REFERENCES accounts(id),
 raw_identity_key TEXT,
 recording_id INTEGER REFERENCES recordings(id),
 unresolved_subject_key TEXT,
 source_day TEXT CHECK(source_day IS NULL OR (date(source_day) IS NOT NULL AND date(source_day)=source_day)),
 day TEXT CHECK(day IS NULL OR (date(day) IS NOT NULL AND date(day)=day)),
 source TEXT NOT NULL, timezone TEXT, precision TEXT NOT NULL,
 first_observed_at REAL NOT NULL, last_observed_at REAL NOT NULL,
 capture_id INTEGER REFERENCES listening_capture_receipts(id), capture_item_id INTEGER UNIQUE,
 CHECK((recording_id IS NOT NULL AND unresolved_subject_key IS NULL)
    OR (recording_id IS NULL AND unresolved_subject_key IS NOT NULL)),
 CHECK((precision='calendar_day' AND timezone IS NOT NULL AND raw_identity_key IS NOT NULL
        AND source_day IS NOT NULL AND capture_id IS NULL AND capture_item_id IS NULL)
    OR (precision='legacy_unknown' AND timezone IS NULL AND capture_id IS NOT NULL AND capture_item_id IS NOT NULL)),
 UNIQUE(account_id,raw_identity_key,source_day,source,timezone)
);

CREATE VIEW play_event_subjects AS
 SELECT p.*,coalesce(r.identity_key,p.unresolved_subject_key) identity_key
 FROM play_events p LEFT JOIN recordings r ON r.id=p.recording_id;

CREATE VIEW listening_observation_subjects AS
 SELECT o.*,coalesce(r.identity_key,o.unresolved_subject_key) identity_key
 FROM listening_observations o LEFT JOIN recordings r ON r.id=o.recording_id;

CREATE INDEX ix_play_event_account_subject_time ON play_events(account_id,recording_id,played_at);

CREATE INDEX ix_play_event_unresolved_time ON play_events(unresolved_subject_key,played_at) WHERE recording_id IS NULL;

CREATE INDEX ix_play_event_unresolved_raw ON play_events(raw_identity_key) WHERE recording_id IS NULL;

CREATE INDEX ix_listening_observation_unresolved_day ON listening_observations(unresolved_subject_key,day,account_id) WHERE recording_id IS NULL;

CREATE INDEX ix_listening_observation_unresolved_raw ON listening_observations(raw_identity_key) WHERE recording_id IS NULL;

CREATE INDEX ix_listening_observation_canonical_scope ON listening_observations(account_id,recording_id,source_day,timezone) WHERE precision='calendar_day';

CREATE TABLE recording_listening_summary (
 account_id INTEGER NOT NULL REFERENCES accounts(id), recording_id INTEGER NOT NULL REFERENCES recordings(id),
 first_exact_play_at REAL, first_exact_day TEXT, first_observed_day TEXT, first_legacy_unknown_day TEXT,
 build_revision INTEGER NOT NULL,
 CHECK((first_exact_play_at IS NULL)=(first_exact_day IS NULL)),
 PRIMARY KEY(account_id,recording_id)
) WITHOUT ROWID;

CREATE TABLE artist_listening_summary (
 account_id INTEGER NOT NULL REFERENCES accounts(id), artist_id INTEGER NOT NULL REFERENCES artists(id),
 first_exact_play_at REAL, first_exact_day TEXT, first_observed_day TEXT, first_legacy_unknown_day TEXT,
 build_revision INTEGER NOT NULL,
 CHECK((first_exact_play_at IS NULL)=(first_exact_day IS NULL)),
 PRIMARY KEY(account_id,artist_id)
) WITHOUT ROWID;

CREATE TABLE listening_summary_state (
 id INTEGER PRIMARY KEY CHECK(id=1), input_revision INTEGER NOT NULL DEFAULT 0,
 built_revision INTEGER, built_at REAL
);

CREATE VIEW recording_listening_artists AS
 SELECT DISTINCT e.recording_id,coalesce(r.artist_id,c.artist_id) artist_id
 FROM catalog_entries e JOIN entry_artists c ON c.entry_id=e.id
 LEFT JOIN artist_redirects r ON r.retired_id=c.artist_id;

CREATE VIEW trend_first_play AS
 SELECT 'track' kind,r.identity_key id_key,
 CAST(julianday(min(s.day))-julianday('1970-01-01') AS INTEGER) first_day,
 min(s.exact_at) first_ts,'canonical_listening' source
 FROM (SELECT recording_id,first_exact_day day,first_exact_play_at exact_at FROM recording_listening_summary
       UNION ALL SELECT recording_id,first_observed_day,NULL FROM recording_listening_summary
       UNION ALL SELECT recording_id,first_legacy_unknown_day,NULL FROM recording_listening_summary) s
 JOIN recordings r ON r.id=s.recording_id WHERE s.day IS NOT NULL GROUP BY s.recording_id
 UNION ALL
 SELECT 'artist','@artist:'||s.artist_id,CAST(julianday(min(s.day))-julianday('1970-01-01') AS INTEGER),
 min(s.exact_at),'canonical_listening'
 FROM (SELECT artist_id,first_exact_day day,first_exact_play_at exact_at FROM artist_listening_summary
       UNION ALL SELECT artist_id,first_observed_day,NULL FROM artist_listening_summary
       UNION ALL SELECT artist_id,first_legacy_unknown_day,NULL FROM artist_listening_summary) s
 WHERE s.day IS NOT NULL GROUP BY s.artist_id
 UNION ALL
 SELECT 'track',identity_key,CAST(julianday(min(day))-julianday('1970-01-01') AS INTEGER),
 min(CASE WHEN precision='exact_timestamp' THEN at END),'unresolved_listening'
 FROM listening_activity WHERE recording_id IS NULL AND day IS NOT NULL GROUP BY identity_key;

-- Core current definition. Domain definitions are listed explicitly in current.py.

CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at REAL NOT NULL);

CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  label TEXT NOT NULL,
  credential_ref TEXT NOT NULL,
  brand_account_id TEXT,
  is_master INTEGER NOT NULL DEFAULT 0 CHECK(typeof(is_master)='integer' AND is_master IN (0,1)),
  last_auth_ok REAL,
  active INTEGER NOT NULL DEFAULT 1 CHECK(typeof(active)='integer' AND active IN (0,1)),
  UNIQUE(label)
);

CREATE TABLE playlists (
  id INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(id),
  provider_playlist_id TEXT NOT NULL,
  title TEXT, track_count INTEGER,
  content_hash TEXT,
  first_seen REAL, last_seen REAL, last_changed REAL,
  created_at REAL,                        -- actual creation time; NULL when unknown, never a sync date
  created_at_source TEXT,                 -- local creation or authoritative youtube metadata
  thumbnail TEXT, playlist_scope_id TEXT REFERENCES playlist_scopes(id),
  UNIQUE(account_id, provider_playlist_id)
,CONSTRAINT ck_playlists_track_count CHECK(track_count IS NULL OR (typeof(track_count)='integer' AND track_count>=0)));

CREATE TABLE player_events (
  id INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(id),
  kind TEXT NOT NULL,                      -- #91 raw sensor stream: track_exit | ended | state |
  video_id TEXT,                           -- tick | volume | bye | rate | playlist_edit |
  position REAL,                           -- feedback | subscription | share_intent
  duration REAL,
  playlist_ytm_id TEXT,
  payload TEXT,                            -- JSON extras per kind (state/volume/shuffle/repeat or url/body/href/action)
  at REAL NOT NULL
);

CREATE TABLE settings (
  key TEXT PRIMARY KEY NOT NULL, value TEXT   -- small app settings, e.g. lastfm_api_key
);

CREATE TABLE genre_family (
  key TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL
);

CREATE TABLE genre_catalog (
  key TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL,
  family_key TEXT REFERENCES genre_family(key),
  source TEXT NOT NULL, family_source TEXT, description TEXT NOT NULL DEFAULT ''
);

CREATE TABLE genre_alias (
  label_key TEXT PRIMARY KEY NOT NULL, label TEXT NOT NULL,
  genre_key TEXT NOT NULL REFERENCES genre_catalog(key), source TEXT NOT NULL
);

CREATE TABLE genre_external_id (
  provider TEXT NOT NULL, external_id TEXT NOT NULL,
  genre_key TEXT NOT NULL REFERENCES genre_catalog(key),
  PRIMARY KEY (provider, external_id)
);

CREATE TABLE rec_model_selection_runs (
  id INTEGER PRIMARY KEY,
  started_at REAL NOT NULL,
  result_json TEXT NOT NULL
, identity_version INTEGER NOT NULL DEFAULT 1);

CREATE TABLE rec_model_previous_vectors (
  run_id INTEGER NOT NULL REFERENCES rec_model_selection_runs(id),
  identity_key TEXT NOT NULL,
  vec BLOB NOT NULL,
  PRIMARY KEY (run_id, identity_key)
);

CREATE TABLE rec_model_forecasts (
  run_id INTEGER NOT NULL REFERENCES rec_model_selection_runs(id),
  made_at REAL NOT NULL,
  forecast_json TEXT NOT NULL,
  PRIMARY KEY (run_id, made_at)
);

CREATE TABLE rec_feedback (
  surface TEXT NOT NULL,                  -- where it happened: 'for_you', 'suggest', 'discover'
  item_key TEXT NOT NULL,                 -- track identity_key (or 'artist:<name>' for a mute)
  kind TEXT NOT NULL,                     -- 'dismiss' | 'less' | 'more' | 'mute' | 'not_now'
  reason TEXT,                            -- optional axis/reason ('era','artist','vibe','own_it')
  scope TEXT NOT NULL DEFAULT '',         -- '' = global; else a playlist id for playlist-local
  until REAL,                             -- suppressed until ts (NULL = until explicitly cleared)
  created_at REAL, target_type TEXT NOT NULL DEFAULT 'legacy_unresolved', recording_id INTEGER REFERENCES recordings(id), artist_id INTEGER REFERENCES artists(id),
  PRIMARY KEY (surface, item_key, scope)
);

CREATE TABLE rec_weights (
  axis_id INTEGER REFERENCES taste_axes(id) PRIMARY KEY NOT NULL,                  -- e.g. 'lane:deep_cut', 'family:techno'
  weight REAL NOT NULL DEFAULT 1.0,       -- learned blend weight; 1.0 = prior
  updated_at REAL                         -- #85 last nudge time; drives time-proportional reversion at read
);

CREATE TABLE rec_lean (
  axis_id INTEGER REFERENCES taste_axes(id) PRIMARY KEY NOT NULL,                  -- 'genre:<fam>' | 'genre:<sub>' | 'era:<decade>' | 'artist:<name>'
  value REAL NOT NULL DEFAULT 1.0,        -- standing transient multiplier; 1.0 = neutral (non-decaying)
  updated_at REAL,                        -- when the slider was last moved (drives held-day exposure)
  last_graduated_day TEXT                 -- UTC date (YYYY-MM-DD) of last exposure-graduation, or NULL
);

CREATE TABLE home_hidden_facet (
  axis_id INTEGER REFERENCES taste_axes(id) PRIMARY KEY NOT NULL                   -- 'genre:<name>' | 'era:<decade>' hidden from the Home panel
);

CREATE TABLE wiki_cards (
  subject    TEXT PRIMARY KEY NOT NULL,
  kind       TEXT NOT NULL,
  display    TEXT NOT NULL,
  title      TEXT,
  extract    TEXT,
  thumbnail  TEXT,
  url        TEXT,
  found      INTEGER NOT NULL,
  fetched_at REAL NOT NULL
);

CREATE TABLE taste_modes (
  mode_id     INTEGER PRIMARY KEY,
  label       TEXT NOT NULL,
  families    TEXT NOT NULL,
  centroid    BLOB NOT NULL,
  size        INTEGER NOT NULL,
  rep_keys    TEXT NOT NULL,
  active      INTEGER NOT NULL,
  first_seen  REAL NOT NULL,
  last_seen   REAL NOT NULL,
  -- Fingerprint of the content space `centroid` lives in (embed.content_model_fingerprint). A
  -- centroid is only comparable to one from the same space; '' means "built before we tracked
  -- this", which never matches and so retires cleanly on the next recompute.
  space       TEXT NOT NULL DEFAULT ''
,CONSTRAINT ck_taste_modes_active CHECK(typeof(active)='integer' AND active IN (0,1)),CONSTRAINT ck_taste_modes_size CHECK(typeof(size)='integer' AND size>=0),CONSTRAINT ck_taste_modes_first_seen CHECK(typeof(first_seen) IN ('integer','real') AND abs(first_seen)<=1.7976931348623157e308),CONSTRAINT ck_taste_modes_last_seen CHECK(typeof(last_seen) IN ('integer','real') AND abs(last_seen)<=1.7976931348623157e308));

CREATE TABLE rec_lane_impressions (
  id INTEGER PRIMARY KEY,
  lane TEXT NOT NULL,                      -- #87 which home lane served the item
  identity_key TEXT NOT NULL,              -- what was shown (future lane-bandit success join)
  at REAL NOT NULL
, recording_id INTEGER REFERENCES recordings(id), raw_identity_key TEXT);

CREATE TABLE rec_impressions (
  surface TEXT NOT NULL,                  -- 'for_you' | 'explore' | 'suggest'
  item_key TEXT NOT NULL,
  views INTEGER NOT NULL DEFAULT 0,       -- times shown (debounced), for anti-staleness erosion
  last_shown REAL,                        -- drives the recycle cooldown
  PRIMARY KEY (surface, item_key)
);

CREATE TABLE rec_proposals (
  surface TEXT PRIMARY KEY NOT NULL,               -- 'fresh_songs' | 'discover'
  payload TEXT NOT NULL,                  -- JSON, materialized by the rec worker (last-good serving)
  built_at REAL
);

CREATE TABLE rec_artist_similar (
  artist TEXT PRIMARY KEY NOT NULL,                -- anchor artist (display name)
  payload TEXT NOT NULL,                  -- JSON [[name, match], ...] from Last.fm
  fetched_at REAL
, artist_id INTEGER REFERENCES artists(id));

CREATE TABLE rec_theme (
  axis_id INTEGER REFERENCES taste_axes(id) PRIMARY KEY NOT NULL,             -- 'genre:<fam>' | 'era:<decade>' | 'artist:<name>'
  score      REAL NOT NULL,                -- persistent signed running total (interaction-driven, no time decay)
  updated_at REAL NOT NULL                 -- bookkeeping only
);

CREATE TABLE play_gradient_checkpoints (
  axis_id INTEGER REFERENCES taste_axes(id) PRIMARY KEY NOT NULL,      -- facet token, e.g. 'genre:techno'
  last_graduated_day TEXT                   -- UTC YYYY-MM-DD the play-exposure funnel last graduated this axis
);

CREATE TABLE recommendation_gradient_events (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  axis_id INTEGER REFERENCES taste_axes(id) NOT NULL,                 -- the facet that graduated, e.g. 'genre:techno'
  source     TEXT NOT NULL,                 -- the signal that drove it: 'play' | 'slider' | 'vibe' | 'like' | ...
  score      REAL NOT NULL,                 -- the ledger value at the crossing (what tripped THEME_THRESHOLD)
  factor     REAL NOT NULL,                 -- the nudge multiplier applied (graduate_up / graduate_down)
  new_weight REAL NOT NULL,                 -- the resulting permanent weight after the nudge
  created_at REAL NOT NULL
);

CREATE TABLE rec_served_impressions (
  id                INTEGER PRIMARY KEY,
  request_id        TEXT NOT NULL,
  surface           TEXT NOT NULL,
  lane              TEXT NOT NULL,
  mode_id           INTEGER,
  identity_key      TEXT NOT NULL,
  rank               INTEGER NOT NULL,
  score              REAL,
  model_version      TEXT NOT NULL,
  provenance         TEXT NOT NULL,
  served_at          REAL NOT NULL, recording_id INTEGER REFERENCES recordings(id), raw_identity_key TEXT,
  UNIQUE(request_id, surface, rank)
,CONSTRAINT ck_rec_served_impressions_rank CHECK(typeof(rank)='integer' AND rank>=0),CONSTRAINT ck_rec_served_impressions_score CHECK(score IS NULL OR (typeof(score) IN ('integer','real') AND abs(score)<=1.7976931348623157e308)),CONSTRAINT ck_rec_served_impressions_served_at CHECK(typeof(served_at) IN ('integer','real') AND abs(served_at)<=1.7976931348623157e308));

CREATE TABLE road_trip_recipes (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  name             TEXT NOT NULL,
  own_pct          INTEGER NOT NULL CHECK(typeof(own_pct)='integer' AND own_pct BETWEEN 0 AND 100),
  
  
  
  target_minutes   INTEGER NOT NULL CHECK(typeof(target_minutes)='integer' AND target_minutes BETWEEN 15 AND 720),
  last_playlist_id TEXT,
  created_at       REAL NOT NULL CHECK(typeof(created_at) IN ('integer','real') AND created_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308),
  updated_at       REAL NOT NULL CHECK(typeof(updated_at) IN ('integer','real') AND updated_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)
, familiarity_pct INTEGER NOT NULL DEFAULT 50 CHECK(typeof(familiarity_pct)='integer' AND familiarity_pct BETWEEN 0 AND 100));

CREATE INDEX ix_play_events_time ON play_events(played_at);

CREATE INDEX ix_player_events_at ON player_events(at);

CREATE INDEX ix_player_events_kind_at ON player_events(kind, at);

CREATE INDEX idx_genre_alias_genre ON genre_alias(genre_key);

CREATE INDEX ix_lane_impressions_at ON rec_lane_impressions(at);

CREATE INDEX ix_rec_served_at ON rec_served_impressions(served_at);

CREATE INDEX ix_rec_served_key_at ON rec_served_impressions(identity_key, served_at);

CREATE TABLE recordings (id INTEGER PRIMARY KEY AUTOINCREMENT,identity_key TEXT NOT NULL UNIQUE,title TEXT,artist TEXT,provisional INTEGER NOT NULL DEFAULT 1,unresolved_genre TEXT,bpm REAL,energy REAL,danceability REAL,mb_recording_id TEXT,music_key TEXT,music_scale TEXT,mood_happy REAL,mood_sad REAL,mood_relaxed REAL,mood_acoustic REAL,instrumental REAL,created_at REAL,first_enriched_at REAL,last_enriched_at REAL,genre_key TEXT REFERENCES genre_catalog(key) CHECK(genre_key IS NULL OR unresolved_genre IS NULL),CONSTRAINT ck_recordings_provisional CHECK(typeof(provisional)='integer' AND provisional IN (0,1)));

CREATE TABLE youtube_items (video_id TEXT PRIMARY KEY NOT NULL CHECK(length(trim(video_id))>0),recording_id INTEGER NOT NULL REFERENCES recordings(id),title TEXT,artist TEXT,orig_title TEXT,orig_artist TEXT,album TEXT,duration_s INTEGER,available INTEGER,video_type TEXT,artist_browse_id TEXT,album_browse_id TEXT,thumbnail TEXT,mb_year TEXT,loudness REAL,dynamic_complexity REAL,popularity INTEGER,gain REAL,label TEXT,UNIQUE(video_id,recording_id),CONSTRAINT ck_youtube_items_available CHECK(available IS NULL OR (typeof(available)='integer' AND available IN (0,1))));

CREATE INDEX ix_youtube_recording ON youtube_items(recording_id);

CREATE TABLE catalog_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT UNIQUE REFERENCES youtube_items(video_id),source_ref TEXT UNIQUE,CHECK((video_id IS NOT NULL)<>(source_ref IS NOT NULL)),FOREIGN KEY(video_id,recording_id) REFERENCES youtube_items(video_id,recording_id) DEFERRABLE INITIALLY DEFERRED);

CREATE INDEX ix_entries_recording ON catalog_entries(recording_id);

CREATE TABLE unresolved_items (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),title TEXT,artist TEXT,orig_title TEXT,orig_artist TEXT,album TEXT,duration_s INTEGER,available INTEGER,video_type TEXT,artist_browse_id TEXT,album_browse_id TEXT,thumbnail TEXT,mb_year TEXT,loudness REAL,dynamic_complexity REAL,popularity INTEGER,gain REAL,label TEXT,CONSTRAINT ck_unresolved_items_available CHECK(available IS NULL OR (typeof(available)='integer' AND available IN (0,1))));

CREATE TABLE library_memberships (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),origin TEXT NOT NULL,added_at REAL);

CREATE TABLE recording_aliases (alias TEXT NOT NULL,recording_id INTEGER NOT NULL REFERENCES recordings(id),source TEXT NOT NULL,PRIMARY KEY(alias,recording_id));

CREATE TABLE legacy_track_refs (legacy_id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT REFERENCES youtube_items(video_id));

CREATE TABLE recording_redirects (retired_id INTEGER PRIMARY KEY REFERENCES recordings(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),source TEXT NOT NULL,evidence TEXT NOT NULL);

CREATE TABLE recording_identifiers (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),scheme TEXT NOT NULL,entity_type TEXT NOT NULL,value TEXT NOT NULL,source TEXT NOT NULL,input_video_id TEXT REFERENCES youtube_items(video_id),status TEXT NOT NULL CHECK(status IN ('candidate','accepted','conflicting')),observed_at REAL);

CREATE INDEX ix_recording_identifier ON recording_identifiers(scheme,entity_type,value);

CREATE TABLE item_recording_associations (id INTEGER PRIMARY KEY,video_id TEXT NOT NULL REFERENCES youtube_items(video_id),recording_id INTEGER NOT NULL REFERENCES recordings(id),previous_recording_id INTEGER REFERENCES recordings(id),source TEXT NOT NULL,evidence TEXT NOT NULL,at REAL);

CREATE TABLE discovery_memberships (recording_id INTEGER PRIMARY KEY REFERENCES recordings(id),entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),found_at REAL,first_shown REAL,last_shown REAL,offered_count INTEGER NOT NULL DEFAULT 0,CONSTRAINT ck_discovery_memberships_offered_count CHECK(typeof(offered_count)='integer' AND offered_count>=0),CONSTRAINT ck_discovery_memberships_found_at CHECK(found_at IS NULL OR (typeof(found_at) IN ('integer','real') AND abs(found_at)<=1.7976931348623157e308)),CONSTRAINT ck_discovery_memberships_first_shown CHECK(first_shown IS NULL OR (typeof(first_shown) IN ('integer','real') AND abs(first_shown)<=1.7976931348623157e308)),CONSTRAINT ck_discovery_memberships_last_shown CHECK(last_shown IS NULL OR (typeof(last_shown) IN ('integer','real') AND abs(last_shown)<=1.7976931348623157e308)));

CREATE TABLE playlist_items (playlist_id INTEGER NOT NULL REFERENCES playlists(id),video_id TEXT NOT NULL REFERENCES youtube_items(video_id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,video_id));

CREATE INDEX ix_playlist_item_video ON playlist_items(video_id);

CREATE TABLE unresolved_playlist_items (playlist_id INTEGER NOT NULL REFERENCES playlists(id),entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,entry_id));

CREATE TABLE provider_attempts (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),input_video_id TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL,at REAL,status TEXT NOT NULL);

CREATE INDEX ix_provider_attempt_subject ON provider_attempts(recording_id,input_video_id,provider,at);

CREATE TABLE item_ratings (account_id INTEGER NOT NULL REFERENCES accounts(id),video_id TEXT NOT NULL,status TEXT NOT NULL,source TEXT NOT NULL,observed_at REAL NOT NULL,PRIMARY KEY(account_id,video_id));

CREATE VIEW catalog_tracks AS SELECT e.id,e.recording_id,e.video_id,r.identity_key,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='title') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='title') ELSE COALESCE(y.title,u.title) END AS title,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist') ELSE COALESCE(y.artist,u.artist) END AS artist,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_title') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_title') ELSE COALESCE(y.orig_title,u.orig_title) END AS orig_title,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_artist') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_artist') ELSE COALESCE(y.orig_artist,u.orig_artist) END AS orig_artist,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album') ELSE COALESCE(y.album,u.album) END AS album,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='duration_s') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='duration_s') ELSE COALESCE(y.duration_s,u.duration_s) END AS duration_s,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='available') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='available') ELSE CASE WHEN e.video_id IS NULL THEN 0 ELSE COALESCE(y.available,u.available) END END AS available,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='video_type') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='video_type') ELSE COALESCE(y.video_type,u.video_type) END AS video_type,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist_browse_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist_browse_id') ELSE COALESCE(y.artist_browse_id,u.artist_browse_id) END AS artist_browse_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album_browse_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album_browse_id') ELSE COALESCE(y.album_browse_id,u.album_browse_id) END AS album_browse_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='thumbnail') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='thumbnail') ELSE COALESCE(y.thumbnail,u.thumbnail) END AS thumbnail,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_year') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_year') ELSE COALESCE(y.mb_year,u.mb_year) END AS mb_year,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='loudness') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='loudness') ELSE COALESCE(y.loudness,u.loudness) END AS loudness,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='dynamic_complexity') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='dynamic_complexity') ELSE COALESCE(y.dynamic_complexity,u.dynamic_complexity) END AS dynamic_complexity,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='popularity') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='popularity') ELSE COALESCE(y.popularity,u.popularity) END AS popularity,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='gain') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='gain') ELSE COALESCE(y.gain,u.gain) END AS gain,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='label') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='label') ELSE COALESCE(y.label,u.label) END AS label,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='genre') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='genre') ELSE COALESCE((SELECT g.name FROM genre_catalog g WHERE g.key=r.genre_key),r.unresolved_genre) END AS genre,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='bpm') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='bpm') ELSE r.bpm END AS bpm,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='energy') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='energy') ELSE r.energy END AS energy,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='danceability') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='danceability') ELSE r.danceability END AS danceability,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_recording_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_recording_id') ELSE r.mb_recording_id END AS mb_recording_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_key') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_key') ELSE r.music_key END AS music_key,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_scale') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_scale') ELSE r.music_scale END AS music_scale,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_happy') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_happy') ELSE r.mood_happy END AS mood_happy,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_sad') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_sad') ELSE r.mood_sad END AS mood_sad,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_relaxed') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_relaxed') ELSE r.mood_relaxed END AS mood_relaxed,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_acoustic') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_acoustic') ELSE r.mood_acoustic END AS mood_acoustic,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='instrumental') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='instrumental') ELSE r.instrumental END AS instrumental,r.created_at,r.first_enriched_at,r.last_enriched_at FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id LEFT JOIN youtube_items y ON y.video_id=e.video_id LEFT JOIN unresolved_items u ON u.entry_id=e.id;

CREATE VIEW tracks AS SELECT c.* FROM catalog_tracks c JOIN library_memberships m ON m.entry_id=c.id;

CREATE VIEW playable_library_tracks AS SELECT t.* FROM tracks t JOIN (SELECT e.recording_id,MIN(e.id) entry_id FROM catalog_entries e JOIN library_memberships m ON m.entry_id=e.id JOIN youtube_items y ON y.video_id=e.video_id WHERE COALESCE(y.available,1)<>0 GROUP BY e.recording_id) playable ON playable.entry_id=t.id;

CREATE VIEW playlist_tracks AS SELECT p.playlist_id,e.id track_id,p.position FROM playlist_items p JOIN catalog_entries e ON e.video_id=p.video_id UNION ALL SELECT playlist_id,entry_id,position FROM unresolved_playlist_items;

CREATE VIEW discovered_tracks AS SELECT c.*,c.mb_year year,d.found_at,d.first_shown,d.last_shown,d.offered_count,c.last_enriched_at last_enriched,(SELECT o.source_token FROM discovery_sources s JOIN discovery_origin_tokens o ON o.id=s.origin_id WHERE s.recording_id=d.recording_id ORDER BY s.first_found_at,o.source_token,s.id LIMIT 1) source_browse_id FROM discovery_memberships d JOIN catalog_tracks c ON c.id=d.entry_id;

CREATE VIEW catalog_enrichment_tracks AS SELECT c.*,r.id queue_order,CASE WHEN EXISTS(SELECT 1 FROM library_memberships lm JOIN catalog_entries e ON e.id=lm.entry_id WHERE e.recording_id=r.id) THEN 'library' ELSE 'discovery' END source FROM recordings r JOIN catalog_tracks c ON c.id=COALESCE((SELECT MIN(e.id) FROM catalog_entries e JOIN library_memberships lm ON lm.entry_id=e.id WHERE e.recording_id=r.id),(SELECT entry_id FROM discovery_memberships WHERE recording_id=r.id));

CREATE TRIGGER rec_served_impressions_subject AFTER INSERT ON rec_served_impressions BEGIN UPDATE rec_served_impressions SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE rec_served_impressions SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=rec_served_impressions.recording_id),identity_key) WHERE rowid=NEW.rowid; END;

CREATE TRIGGER rec_lane_impressions_subject AFTER INSERT ON rec_lane_impressions BEGIN UPDATE rec_lane_impressions SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE rec_lane_impressions SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=rec_lane_impressions.recording_id),identity_key) WHERE rowid=NEW.rowid; END;

CREATE TRIGGER feedback_subject AFTER INSERT ON rec_feedback BEGIN UPDATE rec_feedback SET recording_id=(SELECT id FROM recordings WHERE identity_key=NEW.item_key),target_type=CASE WHEN EXISTS(SELECT 1 FROM recordings WHERE identity_key=NEW.item_key) THEN 'recording' ELSE target_type END WHERE rowid=NEW.rowid; END;

CREATE TABLE rec_response_events (
        id INTEGER PRIMARY KEY, event_id TEXT NOT NULL, kind TEXT NOT NULL,
        identity_key TEXT NOT NULL, at REAL NOT NULL, is_generated INTEGER NOT NULL DEFAULT 0,
        UNIQUE(event_id, kind, identity_key)
    ,CONSTRAINT ck_rec_response_events_is_generated CHECK(typeof(is_generated)='integer' AND is_generated IN (0,1)));

CREATE INDEX ix_rec_response_at ON rec_response_events(at);

CREATE TABLE takeout_imports (
    id INTEGER PRIMARY KEY,
    account_id INTEGER NOT NULL REFERENCES accounts(id),
    fingerprint TEXT NOT NULL,
    imported_at REAL NOT NULL,
    observed_start REAL,
    observed_end REAL,
    unparsed_dates INTEGER NOT NULL CHECK(unparsed_dates >= 0),
    account_verified INTEGER NOT NULL DEFAULT 0 CHECK(account_verified IN (0,1)),
    complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN (0,1)),
    coverage_start REAL,
    coverage_end REAL,
    CHECK(coverage_start IS NULL OR coverage_end > coverage_start)
);

CREATE TABLE enrichment_provider_state (
    recording_id INTEGER NOT NULL REFERENCES recordings(id),
    provider TEXT NOT NULL,
    cycle REAL NOT NULL,
    at REAL NOT NULL,
    status TEXT NOT NULL,
    failures INTEGER NOT NULL,
    retry_at REAL NOT NULL,
    error TEXT NOT NULL,
    PRIMARY KEY(recording_id,provider)
);

CREATE TABLE enrichment_provider_cooldowns (
    provider TEXT PRIMARY KEY NOT NULL,
    failures INTEGER NOT NULL,
    retry_at REAL NOT NULL,
    error TEXT NOT NULL
);

CREATE TABLE enrichment_provider_config (
    provider TEXT PRIMARY KEY NOT NULL,
    fingerprint TEXT NOT NULL,
    status TEXT NOT NULL
);

CREATE TABLE enrichment_provider_jobs (
    recording_id INTEGER NOT NULL REFERENCES recordings(id),
    provider TEXT NOT NULL,
    PRIMARY KEY(recording_id,provider)
);

CREATE TABLE enrichment_artwork (
    entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),
    release_ids_json TEXT NOT NULL,
    status TEXT NOT NULL,
    failures INTEGER NOT NULL,
    retry_at REAL NOT NULL,
    error TEXT NOT NULL
);

CREATE TABLE artists (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,provisional INTEGER NOT NULL CHECK(provisional IN (0,1)));

CREATE TABLE artist_provider_ids (provider TEXT NOT NULL,provider_id TEXT NOT NULL,artist_id INTEGER NOT NULL REFERENCES artists(id),PRIMARY KEY(provider,provider_id));

CREATE INDEX ix_artist_provider_subject ON artist_provider_ids(artist_id);

CREATE TABLE artist_aliases (artist_id INTEGER NOT NULL REFERENCES artists(id),alias TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(artist_id,alias,source));

CREATE INDEX ix_artist_alias ON artist_aliases(alias,artist_id);

CREATE TABLE entry_artists (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),position INTEGER NOT NULL CHECK(position>=0),artist_id INTEGER NOT NULL REFERENCES artists(id),credit TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(entry_id,position),CONSTRAINT ck_entry_artists_position CHECK(typeof(position)='integer' AND position>=0));

CREATE INDEX ix_entry_artist_subject ON entry_artists(artist_id,entry_id);

CREATE TABLE artist_credits (id INTEGER PRIMARY KEY AUTOINCREMENT,display_credit TEXT NOT NULL,content_digest TEXT NOT NULL UNIQUE CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),member_count INTEGER NOT NULL CHECK(typeof(member_count)='integer' AND member_count BETWEEN 1 AND 128),complete INTEGER NOT NULL DEFAULT 0 CHECK(typeof(complete)='integer' AND complete IN (0,1)));

CREATE TABLE artist_credit_members (credit_id INTEGER NOT NULL REFERENCES artist_credits(id),position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 127),artist_id INTEGER REFERENCES artists(id),credit_text TEXT NOT NULL CHECK(length(credit_text)>0),provider TEXT,raw_id TEXT,raw_browse_id TEXT,role TEXT,presence INTEGER NOT NULL CHECK(typeof(presence)='integer' AND presence BETWEEN 0 AND 7),CHECK((provider IS NULL)=(COALESCE(NULLIF(raw_id,''),NULLIF(raw_browse_id,'')) IS NULL)),CHECK((presence&1)<>0 OR raw_id IS NULL),CHECK((presence&2)<>0 OR raw_browse_id IS NULL),CHECK((presence&4)<>0 OR role IS NULL),PRIMARY KEY(credit_id,position)) WITHOUT ROWID;

CREATE INDEX ix_credit_member_artist ON artist_credit_members(artist_id,credit_id) WHERE artist_id IS NOT NULL;

CREATE TABLE artist_credit_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),credit_id INTEGER NOT NULL REFERENCES artist_credits(id),source TEXT NOT NULL CHECK(length(source)>0),delivery_key TEXT CHECK(delivery_key IS NULL OR length(delivery_key)>0),first_seen REAL CHECK(first_seen IS NULL OR (typeof(first_seen) IN ('integer','real') AND first_seen BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),last_seen REAL CHECK(last_seen IS NULL OR (typeof(last_seen) IN ('integer','real') AND last_seen BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),processing_count INTEGER NOT NULL CHECK(typeof(processing_count)='integer' AND processing_count>0),capture_kind TEXT NOT NULL CHECK(capture_kind IN ('legacy_capture','selection_snapshot','capture','provider_delivery','identity_reconciliation')),CHECK((first_seen IS NULL AND last_seen IS NULL) OR (first_seen IS NOT NULL AND last_seen IS NOT NULL AND first_seen<=last_seen)),CHECK((capture_kind IN ('provider_delivery','identity_reconciliation'))=(delivery_key IS NOT NULL)));

CREATE UNIQUE INDEX ix_credit_delivery ON artist_credit_observations(entry_id,source,delivery_key) WHERE delivery_key IS NOT NULL;

CREATE INDEX ix_credit_entry_source ON artist_credit_observations(entry_id,source,id);

CREATE INDEX ix_credit_observation_content ON artist_credit_observations(credit_id,id);

CREATE TABLE artist_credit_capture_heads (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),source TEXT NOT NULL,observation_id INTEGER NOT NULL REFERENCES artist_credit_observations(id),PRIMARY KEY(entry_id,source)) WITHOUT ROWID;

CREATE INDEX ix_credit_capture_observation ON artist_credit_capture_heads(observation_id);

CREATE TABLE entry_artist_selections (entry_id INTEGER PRIMARY KEY NOT NULL REFERENCES catalog_entries(id),observation_id INTEGER NOT NULL REFERENCES artist_credit_observations(id)) WITHOUT ROWID;

CREATE INDEX ix_entry_artist_selection_observation ON entry_artist_selections(observation_id);

CREATE TRIGGER immutable_artist_credit BEFORE UPDATE OF id,display_credit,content_digest,member_count ON artist_credits BEGIN SELECT RAISE(ABORT,'Artist credit content is immutable'); END;

CREATE TRIGGER private_artist_credit BEFORE INSERT ON artist_credits WHEN NEW.complete<>0 BEGIN SELECT RAISE(ABORT,'Artist credit must be assembled privately'); END;

CREATE TRIGGER complete_artist_credit BEFORE UPDATE OF complete ON artist_credits WHEN OLD.complete<>0 OR NEW.complete<>1 OR OLD.member_count<>(SELECT count(*) FROM artist_credit_members WHERE credit_id=OLD.id) OR (SELECT min(position) FROM artist_credit_members WHERE credit_id=OLD.id)<>0 OR (SELECT max(position) FROM artist_credit_members WHERE credit_id=OLD.id)<>OLD.member_count-1 BEGIN SELECT RAISE(ABORT,'Artist credit membership is incomplete or sealed'); END;

CREATE TRIGGER immutable_artist_credit_member_insert BEFORE INSERT ON artist_credit_members WHEN EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=NEW.credit_id AND c.complete=1) BEGIN SELECT RAISE(ABORT,'Artist credit members are immutable'); END;

CREATE TRIGGER immutable_artist_credit_member_update BEFORE UPDATE ON artist_credit_members WHEN EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=OLD.credit_id AND c.complete=1) OR EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=NEW.credit_id AND c.complete=1) BEGIN SELECT RAISE(ABORT,'Artist credit members are immutable'); END;

CREATE TRIGGER immutable_artist_credit_member_delete BEFORE DELETE ON artist_credit_members WHEN EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=OLD.credit_id AND c.complete=1 AND EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.credit_id=c.id)) BEGIN SELECT RAISE(ABORT,'Artist credit members are immutable'); END;

CREATE TRIGGER complete_credit_observation BEFORE INSERT ON artist_credit_observations WHEN NOT EXISTS(SELECT 1 FROM artist_credits WHERE id=NEW.credit_id AND complete=1) BEGIN SELECT RAISE(ABORT,'Artist evidence requires complete credit content'); END;

CREATE TRIGGER immutable_credit_observation BEFORE UPDATE OF id,entry_id,credit_id,source,delivery_key,capture_kind ON artist_credit_observations BEGIN SELECT RAISE(ABORT,'Artist credit evidence identity is immutable'); END;

CREATE TRIGGER monotonic_credit_processing BEFORE UPDATE OF first_seen,last_seen,processing_count ON artist_credit_observations WHEN OLD.capture_kind IN ('legacy_capture','selection_snapshot') OR NEW.processing_count<>OLD.processing_count+1 OR (OLD.first_seen IS NOT NULL AND (NEW.first_seen IS NULL OR NEW.first_seen>OLD.first_seen)) OR (OLD.last_seen IS NOT NULL AND (NEW.last_seen IS NULL OR NEW.last_seen<OLD.last_seen)) BEGIN SELECT RAISE(ABORT,'Artist processing history must advance without rewriting captures'); END;

CREATE TRIGGER owned_artist_credit_capture_heads_insert BEFORE INSERT ON artist_credit_capture_heads WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.source=NEW.source) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;

CREATE TRIGGER owned_artist_credit_capture_heads_update BEFORE UPDATE ON artist_credit_capture_heads WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.source=NEW.source) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;

CREATE TRIGGER owned_entry_artist_selections_insert BEFORE INSERT ON entry_artist_selections WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;

CREATE TRIGGER owned_entry_artist_selections_update BEFORE UPDATE ON entry_artist_selections WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;

CREATE TABLE artist_similarity_targets (source_artist_id INTEGER NOT NULL REFERENCES artists(id),target_artist_id INTEGER NOT NULL REFERENCES artists(id),weight REAL NOT NULL,PRIMARY KEY(source_artist_id,target_artist_id));

CREATE UNIQUE INDEX ix_rec_artist_similar_artist ON rec_artist_similar(artist_id);

CREATE INDEX ix_rec_feedback_artist ON rec_feedback(artist_id,kind);

CREATE TABLE albums (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,artist TEXT,year TEXT,type TEXT,thumbnail TEXT,unresolved_genre TEXT,metadata_rank INTEGER NOT NULL,legacy_key TEXT UNIQUE,genre_key TEXT REFERENCES genre_catalog(key) CHECK(genre_key IS NULL OR unresolved_genre IS NULL),current_tracklist_id INTEGER,FOREIGN KEY(current_tracklist_id,id) REFERENCES album_tracklists(id,album_id) DEFERRABLE INITIALLY DEFERRED);

CREATE TABLE album_artists (album_id INTEGER NOT NULL REFERENCES albums(id),position INTEGER NOT NULL CHECK(position>=0),artist_id INTEGER NOT NULL REFERENCES artists(id),credit TEXT NOT NULL,PRIMARY KEY(album_id,position),CONSTRAINT ck_album_artists_position CHECK(typeof(position)='integer' AND position>=0));

CREATE INDEX ix_album_artist ON album_artists(artist_id,album_id);

CREATE TABLE album_discovery_memberships (album_id INTEGER PRIMARY KEY REFERENCES albums(id),found_at REAL,last_shown REAL,first_shown REAL,offered_count INTEGER NOT NULL DEFAULT 0,legacy_offered_count INTEGER NOT NULL DEFAULT 0,legacy_first_shown REAL,legacy_last_shown REAL,CONSTRAINT ck_album_discovery_memberships_offered_count CHECK(typeof(offered_count)='integer' AND offered_count>=0),CONSTRAINT ck_album_discovery_memberships_legacy_offered_count CHECK(typeof(legacy_offered_count)='integer' AND legacy_offered_count>=0),CONSTRAINT ck_album_discovery_memberships_found_at CHECK(found_at IS NULL OR (typeof(found_at) IN ('integer','real') AND abs(found_at)<=1.7976931348623157e308)),CONSTRAINT ck_album_discovery_memberships_first_shown CHECK(first_shown IS NULL OR (typeof(first_shown) IN ('integer','real') AND abs(first_shown)<=1.7976931348623157e308)),CONSTRAINT ck_album_discovery_memberships_last_shown CHECK(last_shown IS NULL OR (typeof(last_shown) IN ('integer','real') AND abs(last_shown)<=1.7976931348623157e308)),CONSTRAINT ck_album_discovery_memberships_legacy_first_shown CHECK(legacy_first_shown IS NULL OR (typeof(legacy_first_shown) IN ('integer','real') AND abs(legacy_first_shown)<=1.7976931348623157e308)),CONSTRAINT ck_album_discovery_memberships_legacy_last_shown CHECK(legacy_last_shown IS NULL OR (typeof(legacy_last_shown) IN ('integer','real') AND abs(legacy_last_shown)<=1.7976931348623157e308)));

CREATE TABLE playlist_scopes (id TEXT PRIMARY KEY NOT NULL,provider_playlist_id TEXT NOT NULL,account_id INTEGER REFERENCES accounts(id),kind TEXT NOT NULL CHECK(kind IN ('shared','account','legacy')),group_name TEXT,hidden INTEGER NOT NULL DEFAULT 0 CHECK(typeof(hidden)='integer' AND hidden IN (0,1)),overlap_ignored INTEGER NOT NULL DEFAULT 0 CHECK(typeof(overlap_ignored)='integer' AND overlap_ignored IN (0,1)),overlap_ignored_at REAL CHECK((overlap_ignored=1 OR overlap_ignored_at IS NULL) AND (overlap_ignored_at IS NULL OR (typeof(overlap_ignored_at) IN ('integer','real') AND overlap_ignored_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308))),origin TEXT CHECK(origin IS NULL OR origin IN ('ordinary','tuneconsole')),adopted INTEGER CHECK((origin IS NULL AND adopted IS NULL) OR (origin IS NOT NULL AND typeof(adopted)='integer' AND adopted IN (0,1))),provenance_description TEXT CHECK(origin IS NOT NULL OR provenance_description IS NULL),CHECK((kind='account' AND account_id IS NOT NULL) OR (kind<>'account' AND account_id IS NULL)),UNIQUE(provider_playlist_id,account_id));

CREATE UNIQUE INDEX ix_playlist_shared ON playlist_scopes(provider_playlist_id,kind) WHERE account_id IS NULL;

CREATE INDEX ix_playlist_scope_account ON playlists(playlist_scope_id,account_id);

CREATE TABLE suppressed_overlaps (first_playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),second_playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),created_at REAL,PRIMARY KEY(first_playlist_scope_id,second_playlist_scope_id));

CREATE TABLE overlap_kept (first_playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),second_playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),created_at REAL,PRIMARY KEY(first_playlist_scope_id,second_playlist_scope_id));

CREATE TABLE cleanup_ignored (playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),category TEXT NOT NULL,created_at REAL,PRIMARY KEY(playlist_scope_id,category));

CREATE TABLE ignored_merges (signature TEXT PRIMARY KEY NOT NULL,members TEXT NOT NULL,created_at REAL);

CREATE TABLE ignored_merge_members (signature TEXT NOT NULL REFERENCES ignored_merges(signature) ON DELETE CASCADE,playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),PRIMARY KEY(signature,playlist_scope_id));

CREATE TABLE playlist_membership_refs (id INTEGER PRIMARY KEY AUTOINCREMENT,playlist_scope_id TEXT REFERENCES playlist_scopes(id),account_id INTEGER REFERENCES accounts(id),CHECK((playlist_scope_id IS NULL)=(account_id IS NULL)));

CREATE TABLE rec_mode_impressions (epoch INTEGER NOT NULL,lane TEXT NOT NULL,mode_id INTEGER REFERENCES taste_modes(mode_id),ranker TEXT,created_at REAL NOT NULL,legacy_mode_id INTEGER,CHECK((mode_id IS NOT NULL)<>(legacy_mode_id IS NOT NULL)),PRIMARY KEY(epoch,lane));

CREATE TABLE rec_mode_picks (membership_ref_id INTEGER PRIMARY KEY NOT NULL REFERENCES playlist_membership_refs(id),mode_id INTEGER REFERENCES taste_modes(mode_id),ranker TEXT,created_at REAL NOT NULL,legacy_mode_id INTEGER,CHECK((mode_id IS NOT NULL)<>(legacy_mode_id IS NOT NULL)));

CREATE UNIQUE INDEX ix_playlist_item_position ON playlist_items(playlist_id,position);

CREATE UNIQUE INDEX ix_unresolved_playlist_position ON unresolved_playlist_items(playlist_id,position);

CREATE INDEX ix_unresolved_playlist_entry ON unresolved_playlist_items(entry_id,playlist_id);

CREATE INDEX ix_play_event_recording_time ON play_events(recording_id,played_at);

CREATE INDEX ix_play_event_account_time ON play_events(account_id,played_at DESC,id DESC);

CREATE INDEX ix_play_event_account_playlist_time ON play_events(account_id,playlist_ytm_id,played_at);

CREATE INDEX ix_player_event_account_playlist_time ON player_events(account_id,playlist_ytm_id,at);

CREATE INDEX ix_mode_pick_mode_time ON rec_mode_picks(mode_id,created_at);

CREATE TRIGGER playlist_items_position_insert BEFORE INSERT ON playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM unresolved_playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;

CREATE TRIGGER playlist_items_position_update BEFORE UPDATE ON playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM unresolved_playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;

CREATE TRIGGER unresolved_playlist_items_position_insert BEFORE INSERT ON unresolved_playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;

CREATE TRIGGER unresolved_playlist_items_position_update BEFORE UPDATE ON unresolved_playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;

CREATE TRIGGER playlists_scope_insert BEFORE INSERT ON playlists WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id AND ((s.kind='account' AND s.account_id=NEW.account_id AND s.provider_playlist_id IN ('LM','SE')) OR (s.kind='shared' AND s.account_id IS NULL AND s.provider_playlist_id NOT IN ('LM','SE')))) BEGIN SELECT RAISE(ABORT,'Playlist scope does not match its account and provider'); END;

CREATE TRIGGER playlists_scope_update BEFORE UPDATE ON playlists WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id AND ((s.kind='account' AND s.account_id=NEW.account_id AND s.provider_playlist_id IN ('LM','SE')) OR (s.kind='shared' AND s.account_id IS NULL AND s.provider_playlist_id NOT IN ('LM','SE')))) BEGIN SELECT RAISE(ABORT,'Playlist scope does not match its account and provider'); END;

CREATE TRIGGER playlists_membership_insert BEFORE INSERT ON playlists WHEN EXISTS(SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.id AND (m.playlist_scope_id IS NOT NEW.playlist_scope_id OR m.account_id IS NOT NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Playlist membership ID already belongs to retained history'); END;

CREATE TRIGGER playlists_membership_update BEFORE UPDATE ON playlists WHEN NEW.id IS NOT OLD.id OR NEW.playlist_scope_id IS NOT OLD.playlist_scope_id OR NEW.account_id IS NOT OLD.account_id BEGIN SELECT RAISE(ABORT,'Playlist membership identity is immutable'); END;

CREATE TRIGGER playlists_membership_record AFTER INSERT ON playlists BEGIN INSERT OR IGNORE INTO playlist_membership_refs(id,playlist_scope_id,account_id) VALUES (NEW.id,NEW.playlist_scope_id,NEW.account_id); SELECT CASE WHEN EXISTS(SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.id AND (m.playlist_scope_id IS NOT NEW.playlist_scope_id OR m.account_id IS NOT NEW.account_id)) THEN RAISE(ABORT,'Playlist membership ID already belongs to retained history') END; END;

CREATE TRIGGER playlist_membership_refs_update BEFORE UPDATE ON playlist_membership_refs WHEN NEW.id IS NOT OLD.id OR NEW.playlist_scope_id IS NOT OLD.playlist_scope_id OR NEW.account_id IS NOT OLD.account_id BEGIN SELECT RAISE(ABORT,'Retained playlist membership identity is immutable'); END;

CREATE TRIGGER playlist_membership_refs_delete BEFORE DELETE ON playlist_membership_refs WHEN EXISTS(SELECT 1 FROM playlists WHERE id=OLD.id) BEGIN SELECT RAISE(ABORT,'Playlist still references this membership'); END;

CREATE TABLE listening_calendars (account_id INTEGER PRIMARY KEY REFERENCES accounts(id),timezone TEXT NOT NULL,confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1)));

CREATE TABLE play_event_sources (event_id INTEGER NOT NULL REFERENCES play_events(id) ON DELETE CASCADE,source TEXT NOT NULL,PRIMARY KEY(event_id,source));

CREATE TABLE play_event_calendar (event_id INTEGER PRIMARY KEY REFERENCES play_events(id) ON DELETE CASCADE,day TEXT NOT NULL CHECK(date(day) IS NOT NULL AND date(day)=day),timezone TEXT NOT NULL);

CREATE INDEX ix_play_event_source ON play_event_sources(source,event_id);

CREATE INDEX ix_play_event_calendar_day ON play_event_calendar(day,event_id);

CREATE TABLE artist_redirects (retired_id INTEGER PRIMARY KEY REFERENCES artists(id),artist_id INTEGER NOT NULL REFERENCES artists(id),source TEXT NOT NULL,created_at REAL NOT NULL,CHECK(retired_id<>artist_id));

CREATE INDEX ix_artist_redirect_target ON artist_redirects(artist_id);

CREATE TRIGGER artist_redirect_insert BEFORE INSERT ON artist_redirects WHEN EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) OR NOT EXISTS(SELECT 1 FROM artists WHERE id=NEW.retired_id AND provisional=1) OR EXISTS(SELECT 1 FROM artist_provider_ids WHERE artist_id=NEW.retired_id) OR NOT EXISTS(SELECT 1 FROM artists a JOIN artist_provider_ids p ON p.artist_id=a.id WHERE a.id=NEW.artist_id AND a.provisional=0) BEGIN SELECT RAISE(ABORT,'Artist redirect requires a provisional source and canonical target'); END;

CREATE TRIGGER artist_redirect_update BEFORE UPDATE ON artist_redirects WHEN NEW.retired_id<>OLD.retired_id OR EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) OR NOT EXISTS(SELECT 1 FROM artists WHERE id=NEW.retired_id AND provisional=1) OR EXISTS(SELECT 1 FROM artist_provider_ids WHERE artist_id=NEW.retired_id) OR NOT EXISTS(SELECT 1 FROM artists a JOIN artist_provider_ids p ON p.artist_id=a.id WHERE a.id=NEW.artist_id AND a.provisional=0) BEGIN SELECT RAISE(ABORT,'Artist redirect requires a provisional source and canonical target'); END;

CREATE TRIGGER discovery_membership_insert BEFORE INSERT ON discovery_memberships WHEN NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Discovery representative belongs to another recording'); END;

CREATE TRIGGER discovery_membership_update BEFORE UPDATE ON discovery_memberships WHEN NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Discovery representative belongs to another recording'); END;

CREATE TRIGGER discovery_entry_reassociation BEFORE UPDATE OF recording_id ON catalog_entries WHEN EXISTS(SELECT 1 FROM discovery_memberships d WHERE d.entry_id=OLD.id AND d.recording_id<>NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Replace discovery representative before reassociation'); END;

CREATE INDEX ix_artist_provisional_name ON artists(name) WHERE provisional=1;

CREATE TABLE spotify_history_listens (account_id INTEGER NOT NULL REFERENCES accounts(id),track_uri TEXT NOT NULL,ended_at REAL NOT NULL,event_id INTEGER REFERENCES play_events(id) ON DELETE SET NULL,artist_id INTEGER REFERENCES artists(id),PRIMARY KEY(account_id,track_uri,ended_at));

CREATE TABLE listening_capture_receipts (id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id),captured_at REAL NOT NULL);

CREATE INDEX ix_listening_capture_account_time ON listening_capture_receipts(account_id,captured_at);

CREATE INDEX ix_listening_observation_account_day ON listening_observations(account_id,day);

CREATE INDEX ix_listening_observation_recording_day ON listening_observations(recording_id,day,account_id);

CREATE INDEX ix_listening_observation_capture ON listening_observations(capture_id);

CREATE VIEW listening_evidence AS
SELECT CASE WHEN capture_item_id IS NOT NULL THEN 'capture:'||capture_item_id ELSE 'day:'||id END evidence_id,
       account_id,identity_key,recording_id,day,source,timezone,
       precision,last_observed_at observed_at,NULL event_id,0 is_generated
FROM listening_observation_subjects WHERE day IS NOT NULL
UNION ALL
SELECT 'event:'||pe.id||':'||s.source,pe.account_id,pe.identity_key,pe.recording_id,c.day,
       s.source,c.timezone,'exact_timestamp',pe.played_at,pe.id,COALESCE(pe.is_generated,0)
FROM play_event_subjects pe JOIN play_event_calendar c ON c.event_id=pe.id
JOIN play_event_sources s ON s.event_id=pe.id;

CREATE VIEW listening_days AS
SELECT account_id,identity_key,MIN(recording_id) recording_id,day,
       CAST(strftime('%s',day||' 12:00:00') AS REAL) day_ts,
       MAX(CASE WHEN event_id IS NOT NULL THEN observed_at END) last_event_at,
       MAX(observed_at) last_observed_at,
       CASE WHEN MIN(source)=MAX(source) THEN MIN(source) ELSE 'multiple' END source
FROM eligible_listening_evidence GROUP BY account_id,identity_key,day;

CREATE VIEW listening_daily_items AS
SELECT account_id||':'||day||':'||identity_key rowid,account_id||':'||day snapshot_id,
       identity_key,recording_id,source,day,account_id,last_event_at,last_observed_at
FROM listening_days;

CREATE VIEW listening_daily_snapshots AS
SELECT account_id||':'||day id,account_id,day_ts taken_at,day
FROM listening_days GROUP BY account_id,day;

CREATE VIEW listening_activity AS
SELECT pe.account_id,pe.identity_key,pe.recording_id,c.day,pe.played_at at,
       'exact_timestamp' precision,pe.id event_id
FROM play_event_subjects pe JOIN play_event_calendar c ON c.event_id=pe.id
WHERE COALESCE(pe.is_generated,0)=0
UNION ALL
SELECT d.account_id,d.identity_key,d.recording_id,d.day,d.day_ts,
       CASE WHEN EXISTS (SELECT 1 FROM eligible_listening_evidence e
           WHERE e.account_id=d.account_id AND e.identity_key=d.identity_key AND e.day=d.day
           AND e.precision='calendar_day') THEN 'calendar_day' ELSE 'legacy_unknown' END,
       NULL FROM listening_days d
WHERE NOT EXISTS (SELECT 1 FROM play_event_subjects pe JOIN play_event_calendar c ON c.event_id=pe.id
    WHERE pe.account_id=d.account_id AND pe.identity_key=d.identity_key AND c.day=d.day
    AND COALESCE(pe.is_generated,0)=0);

CREATE TABLE rec_change_queue (kind TEXT NOT NULL,item TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(kind,item));

CREATE INDEX ix_rec_playlist_scope_cursor ON playlists(playlist_scope_id,id);

CREATE INDEX ix_rec_feedback_key ON rec_feedback(item_key,kind);

CREATE INDEX ix_rec_feedback_recent ON rec_feedback(kind,created_at DESC);

CREATE INDEX ix_player_event_recent ON player_events(at DESC,id DESC);

CREATE INDEX ix_rec_served_model ON rec_served_impressions(model_version);

CREATE INDEX ix_rec_served_pool ON rec_served_impressions(CAST(json_extract(provenance,'$.pool_policy') AS TEXT));

CREATE VIEW eligible_listening_evidence AS
        SELECT CASE WHEN o.capture_item_id IS NOT NULL THEN 'capture:'||o.capture_item_id
                    ELSE 'day:'||o.id END evidence_id,
               o.account_id,o.identity_key,o.recording_id,o.day,o.source,o.timezone,
               o.precision,o.last_observed_at observed_at,NULL event_id,0 is_generated
        FROM listening_observation_subjects o WHERE o.day IS NOT NULL AND (
            o.source<>'ytm_history' OR NOT EXISTS (
                SELECT 1 FROM play_event_subjects pe JOIN play_event_calendar c ON c.event_id=pe.id
                JOIN play_event_sources s ON s.event_id=pe.id
                WHERE pe.account_id=o.account_id AND pe.identity_key=o.identity_key
                  AND c.day=o.day AND pe.is_generated=1)
            OR EXISTS (
                SELECT 1 FROM play_event_subjects pe JOIN play_event_calendar c ON c.event_id=pe.id
                JOIN play_event_sources s ON s.event_id=pe.id
                WHERE pe.account_id=o.account_id AND pe.identity_key=o.identity_key
                  AND c.day=o.day AND COALESCE(pe.is_generated,0)=0)
            OR EXISTS (
                SELECT 1 FROM listening_observation_subjects independent
                WHERE independent.account_id=o.account_id AND independent.identity_key=o.identity_key
                  AND independent.day=o.day AND independent.source<>'ytm_history'))
        UNION ALL
        SELECT 'event:'||pe.id||':'||s.source,pe.account_id,pe.identity_key,pe.recording_id,c.day,
               s.source,c.timezone,'exact_timestamp',pe.played_at,pe.id,COALESCE(pe.is_generated,0)
        FROM play_event_subjects pe JOIN play_event_calendar c ON c.event_id=pe.id
        JOIN play_event_sources s ON s.event_id=pe.id WHERE COALESCE(pe.is_generated,0)=0;

CREATE VIEW listening_day_counts AS
        SELECT identity_key,COUNT(*) plays FROM (
            SELECT DISTINCT account_id,identity_key,day FROM eligible_listening_evidence
        ) GROUP BY identity_key;

CREATE TRIGGER rec_capture_recordings_insert AFTER INSERT ON recordings BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_recordings_delete AFTER DELETE ON recordings BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_recordings_update AFTER UPDATE ON recordings WHEN OLD.identity_key IS NOT NEW.identity_key OR OLD.genre_key IS NOT NEW.genre_key OR OLD.unresolved_genre IS NOT NEW.unresolved_genre OR OLD.bpm IS NOT NEW.bpm OR OLD.energy IS NOT NEW.energy OR OLD.danceability IS NOT NEW.danceability OR OLD.music_key IS NOT NEW.music_key OR OLD.music_scale IS NOT NEW.music_scale OR OLD.mood_happy IS NOT NEW.mood_happy OR OLD.mood_sad IS NOT NEW.mood_sad OR OLD.mood_relaxed IS NOT NEW.mood_relaxed OR OLD.mood_acoustic IS NOT NEW.mood_acoustic OR OLD.instrumental IS NOT NEW.instrumental BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_youtube_items_insert AFTER INSERT ON youtube_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_youtube_items_delete AFTER DELETE ON youtube_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_youtube_items_update AFTER UPDATE ON youtube_items WHEN OLD.recording_id IS NOT NEW.recording_id OR OLD.available IS NOT NEW.available OR OLD.title IS NOT NEW.title OR OLD.artist IS NOT NEW.artist OR OLD.album IS NOT NEW.album OR OLD.mb_year IS NOT NEW.mb_year OR OLD.duration_s IS NOT NEW.duration_s OR OLD.video_type IS NOT NEW.video_type OR OLD.loudness IS NOT NEW.loudness OR OLD.dynamic_complexity IS NOT NEW.dynamic_complexity BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_catalog_entries_insert AFTER INSERT ON catalog_entries BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_catalog_entries_delete AFTER DELETE ON catalog_entries BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_catalog_entries_update AFTER UPDATE ON catalog_entries WHEN OLD.recording_id IS NOT NEW.recording_id OR OLD.video_id IS NOT NEW.video_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_library_memberships_insert AFTER INSERT ON library_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_library_memberships_delete AFTER DELETE ON library_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_library_memberships_update AFTER UPDATE ON library_memberships WHEN OLD.entry_id IS NOT NEW.entry_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_playlist_items_insert AFTER INSERT ON playlist_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_playlist_items_delete AFTER DELETE ON playlist_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

