        requested_video_id TEXT NOT NULL REFERENCES youtube_items(video_id),
        video_id TEXT NOT NULL REFERENCES youtube_items(video_id),
        same_recording INTEGER NOT NULL CHECK(same_recording IN (0,1)),
        evidence_json TEXT NOT NULL,
        observed_at REAL NOT NULL,
        PRIMARY KEY(account_id,requested_video_id),
        CHECK(requested_video_id<>video_id)
    );

CREATE TABLE rec_musical_sources (source_key TEXT PRIMARY KEY NOT NULL,provider TEXT NOT NULL,scope TEXT NOT NULL,entity_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);

CREATE TABLE rec_musical_links (source_key TEXT NOT NULL REFERENCES rec_musical_sources(source_key),recording_id INTEGER NOT NULL REFERENCES recordings(id),delivery_id TEXT NOT NULL,PRIMARY KEY(source_key,recording_id));

CREATE INDEX ix_musical_links_recording ON rec_musical_links(recording_id,source_key);

CREATE TABLE rec_musical_pending (position INTEGER PRIMARY KEY AUTOINCREMENT,source_key TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,CONSTRAINT ck_rec_musical_pending_position CHECK(typeof(position)='integer' AND position>=0),CONSTRAINT ck_rec_musical_pending_revision CHECK(typeof(revision)='integer' AND revision>=1),CONSTRAINT ck_rec_musical_pending_cursor CHECK(typeof(cursor)='integer' AND cursor>=0));

CREATE TABLE rec_musical_source_profiles (source_key TEXT PRIMARY KEY NOT NULL,payload TEXT NOT NULL,version TEXT NOT NULL,digest TEXT NOT NULL,prepared_at REAL NOT NULL);

CREATE INDEX ix_rec_musical_source_profiles_version ON rec_musical_source_profiles(version,source_key);

CREATE TABLE rec_musical_profiles (identity_key TEXT PRIMARY KEY NOT NULL,payload TEXT NOT NULL,version TEXT NOT NULL,digest TEXT NOT NULL,prepared_at REAL NOT NULL);

CREATE INDEX ix_rec_musical_profiles_version ON rec_musical_profiles(version,identity_key);

CREATE TRIGGER musical_source_insert AFTER INSERT ON rec_musical_sources BEGIN INSERT INTO rec_musical_pending(source_key,revision) VALUES (NEW.source_key,NEW.revision) ON CONFLICT(source_key) DO UPDATE SET revision=excluded.revision,cursor=0; END;

CREATE TRIGGER musical_source_update AFTER UPDATE ON rec_musical_sources BEGIN INSERT INTO rec_musical_pending(source_key,revision) VALUES (NEW.source_key,NEW.revision) ON CONFLICT(source_key) DO UPDATE SET revision=excluded.revision,cursor=0; END;

CREATE TRIGGER musical_link_insert AFTER INSERT ON rec_musical_links BEGIN INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id=NEW.recording_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TABLE listening_rating_actions (id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL REFERENCES accounts(id),video_id TEXT NOT NULL,previous_status TEXT,status TEXT NOT NULL,source TEXT NOT NULL,at REAL NOT NULL);

CREATE INDEX ix_listening_rating_time ON listening_rating_actions(at,id);

CREATE TABLE rec_group_clock (id INTEGER PRIMARY KEY CHECK(id=1),serial INTEGER NOT NULL);

CREATE TRIGGER group_clock_rec_musical_profiles_insert AFTER INSERT ON rec_musical_profiles BEGIN UPDATE rec_group_clock SET serial=serial+1 WHERE id=1; END;

CREATE TRIGGER group_clock_rec_musical_profiles_update AFTER UPDATE ON rec_musical_profiles BEGIN UPDATE rec_group_clock SET serial=serial+1 WHERE id=1; END;

CREATE TRIGGER group_clock_rec_musical_profiles_delete AFTER DELETE ON rec_musical_profiles BEGIN UPDATE rec_group_clock SET serial=serial+1 WHERE id=1; END;

CREATE TRIGGER group_clock_taste_modes_insert AFTER INSERT ON taste_modes BEGIN UPDATE rec_group_clock SET serial=serial+1 WHERE id=1; END;

CREATE TRIGGER group_clock_taste_modes_update AFTER UPDATE ON taste_modes BEGIN UPDATE rec_group_clock SET serial=serial+1 WHERE id=1; END;

CREATE TRIGGER group_clock_taste_modes_delete AFTER DELETE ON taste_modes BEGIN UPDATE rec_group_clock SET serial=serial+1 WHERE id=1; END;

CREATE TABLE audio_vibe_runs (run_id TEXT PRIMARY KEY NOT NULL,video_id TEXT NOT NULL,title TEXT NOT NULL,artist TEXT NOT NULL,created_at REAL NOT NULL);

CREATE TABLE rec_vibe_pending (position INTEGER PRIMARY KEY AUTOINCREMENT,group_key TEXT UNIQUE NOT NULL,revision INTEGER NOT NULL DEFAULT 1,cursor TEXT NOT NULL DEFAULT '',CONSTRAINT ck_rec_vibe_pending_position CHECK(typeof(position)='integer' AND position>=0),CONSTRAINT ck_rec_vibe_pending_revision CHECK(typeof(revision)='integer' AND revision>=1));

CREATE TRIGGER vibe_artists_insert AFTER INSERT ON entry_artists BEGIN INSERT INTO rec_content_pending(identity_key) SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=NEW.entry_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER vibe_artists_update AFTER UPDATE ON entry_artists BEGIN INSERT INTO rec_content_pending(identity_key) SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=OLD.entry_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1;INSERT INTO rec_content_pending(identity_key) SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=NEW.entry_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER vibe_artists_delete AFTER DELETE ON entry_artists BEGIN INSERT INTO rec_content_pending(identity_key) SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=OLD.entry_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TABLE sample_attributes (id TEXT PRIMARY KEY NOT NULL,recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT NOT NULL REFERENCES youtube_items(video_id),run_id TEXT NOT NULL,point TEXT NOT NULL CHECK(point IN ('thirty','middle','two_thirds')),filename TEXT NOT NULL,captured_at REAL NOT NULL,UNIQUE(run_id,point),FOREIGN KEY(video_id,recording_id) REFERENCES youtube_items(video_id,recording_id) DEFERRABLE INITIALLY DEFERRED);

CREATE INDEX idx_sample_recording ON sample_attributes(recording_id,captured_at DESC,id);

CREATE INDEX idx_sample_video ON sample_attributes(video_id,captured_at DESC,id);

CREATE TABLE measurements (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),vibe TEXT NOT NULL,score REAL NOT NULL CHECK(score BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),source TEXT NOT NULL CHECK(source IN ('audio_measurement','provider_measurement')),model_version TEXT NOT NULL,input_digest TEXT NOT NULL,measured_at REAL,UNIQUE(recording_id,vibe,model_version,input_digest),UNIQUE(id,recording_id,vibe));

CREATE TABLE measurement_samples (measurement_id INTEGER NOT NULL REFERENCES measurements(id),sample_id TEXT NOT NULL REFERENCES sample_attributes(id) ON DELETE CASCADE,PRIMARY KEY(measurement_id,sample_id)) WITHOUT ROWID;

CREATE INDEX idx_measurement_sample ON measurement_samples(sample_id,measurement_id);

CREATE TABLE predictions (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),vibe TEXT NOT NULL,score REAL NOT NULL CHECK(score BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),subgenre_key TEXT REFERENCES genre_catalog(key),kind TEXT NOT NULL CHECK(kind IN ('artist_genre','artist','genre')),lineage_complete INTEGER NOT NULL DEFAULT 1 CHECK(lineage_complete IN (0,1)),policy_version TEXT NOT NULL,predicted_at REAL,UNIQUE(id,recording_id,vibe),CHECK(lineage_complete=0 OR (kind IN ('artist_genre','genre') AND subgenre_key IS NOT NULL) OR (kind='artist' AND subgenre_key IS NULL)));

CREATE INDEX idx_prediction_recording ON predictions(recording_id,vibe,id);

CREATE TABLE prediction_artists (prediction_id INTEGER NOT NULL REFERENCES predictions(id) ON DELETE CASCADE,artist_id INTEGER NOT NULL REFERENCES artists(id),PRIMARY KEY(prediction_id,artist_id)) WITHOUT ROWID;

CREATE INDEX idx_prediction_artist ON prediction_artists(artist_id,prediction_id);

CREATE TABLE prediction_inputs (prediction_id INTEGER NOT NULL REFERENCES predictions(id) ON DELETE CASCADE,measurement_id INTEGER NOT NULL REFERENCES measurements(id),PRIMARY KEY(prediction_id,measurement_id)) WITHOUT ROWID;

CREATE INDEX idx_prediction_measurement ON prediction_inputs(measurement_id,prediction_id);

CREATE TABLE recording_vibes (recording_id INTEGER NOT NULL REFERENCES recordings(id),vibe TEXT NOT NULL,score REAL NOT NULL CHECK(score BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),source TEXT NOT NULL CHECK(source IN ('audio_measurement','provider_measurement','artist_genre','artist','genre','heuristic')),measurement_id INTEGER,prediction_id INTEGER,inputs_version TEXT NOT NULL,artist_key TEXT,subgenre_key TEXT REFERENCES genre_catalog(key),recordings INTEGER,variance REAL,PRIMARY KEY(recording_id,vibe),FOREIGN KEY(measurement_id,recording_id,vibe) REFERENCES measurements(id,recording_id,vibe),FOREIGN KEY(prediction_id,recording_id,vibe) REFERENCES predictions(id,recording_id,vibe),CHECK((source IN ('audio_measurement','provider_measurement') AND measurement_id IS NOT NULL AND prediction_id IS NULL) OR (source IN ('artist_genre','artist','genre') AND prediction_id IS NOT NULL AND measurement_id IS NULL) OR (source='heuristic' AND measurement_id IS NULL AND prediction_id IS NULL))) WITHOUT ROWID;

CREATE INDEX idx_recording_vibe_rank ON recording_vibes(vibe,score DESC,recording_id);

CREATE INDEX idx_vibe_artist_genre ON recording_vibes(artist_key,subgenre_key,recording_id,vibe);

CREATE INDEX idx_vibe_genre ON recording_vibes(subgenre_key,recording_id,vibe);

CREATE TRIGGER measurement_samples_insert BEFORE INSERT ON measurement_samples WHEN NOT EXISTS (SELECT 1 FROM measurements m JOIN sample_attributes s ON s.recording_id=m.recording_id WHERE m.id=NEW.measurement_id AND s.id=NEW.sample_id) BEGIN SELECT RAISE(ABORT,'Measurement sample belongs to another recording'); END;

CREATE TRIGGER prediction_inputs_insert BEFORE INSERT ON prediction_inputs WHEN NOT EXISTS (SELECT 1 FROM predictions p JOIN measurements m ON m.vibe=p.vibe WHERE p.id=NEW.prediction_id AND m.id=NEW.measurement_id AND m.recording_id<>p.recording_id) OR EXISTS (SELECT 1 FROM measurements b CROSS JOIN measurements a CROSS JOIN prediction_inputs i WHERE b.id=NEW.measurement_id AND a.recording_id=b.recording_id AND a.vibe=b.vibe AND i.prediction_id=NEW.prediction_id AND i.measurement_id=a.id AND a.id<>b.id) BEGIN SELECT RAISE(ABORT,'Prediction inputs require distinct original recordings of the same vibe'); END;

CREATE TRIGGER recording_vibes_insert BEFORE INSERT ON recording_vibes WHEN NEW.measurement_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM measurements m WHERE m.id=NEW.measurement_id AND m.source=NEW.source AND m.score=NEW.score AND m.support=NEW.support) OR NEW.prediction_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM predictions p WHERE p.id=NEW.prediction_id AND p.score=NEW.score AND p.support=NEW.support AND p.kind=NEW.source AND (p.lineage_complete=0 OR (EXISTS (SELECT 1 FROM prediction_inputs i WHERE i.prediction_id=p.id) AND (p.kind='genre' OR EXISTS (SELECT 1 FROM prediction_artists a WHERE a.prediction_id=p.id))))) BEGIN SELECT RAISE(ABORT,'Current vibe does not match its original score'); END;

CREATE TRIGGER measurement_samples_update BEFORE UPDATE ON measurement_samples WHEN NOT EXISTS (SELECT 1 FROM measurements m JOIN sample_attributes s ON s.recording_id=m.recording_id WHERE m.id=NEW.measurement_id AND s.id=NEW.sample_id) BEGIN SELECT RAISE(ABORT,'Measurement sample belongs to another recording'); END;

CREATE TRIGGER prediction_inputs_update BEFORE UPDATE ON prediction_inputs WHEN NOT EXISTS (SELECT 1 FROM predictions p JOIN measurements m ON m.vibe=p.vibe WHERE p.id=NEW.prediction_id AND m.id=NEW.measurement_id AND m.recording_id<>p.recording_id) OR EXISTS (SELECT 1 FROM measurements b CROSS JOIN measurements a CROSS JOIN prediction_inputs i WHERE b.id=NEW.measurement_id AND a.recording_id=b.recording_id AND a.vibe=b.vibe AND i.prediction_id=NEW.prediction_id AND i.measurement_id=a.id AND a.id<>b.id) BEGIN SELECT RAISE(ABORT,'Prediction inputs require distinct original recordings of the same vibe'); END;

CREATE TRIGGER recording_vibes_update BEFORE UPDATE ON recording_vibes WHEN NEW.measurement_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM measurements m WHERE m.id=NEW.measurement_id AND m.source=NEW.source AND m.score=NEW.score AND m.support=NEW.support) OR NEW.prediction_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM predictions p WHERE p.id=NEW.prediction_id AND p.score=NEW.score AND p.support=NEW.support AND p.kind=NEW.source AND (p.lineage_complete=0 OR (EXISTS (SELECT 1 FROM prediction_inputs i WHERE i.prediction_id=p.id) AND (p.kind='genre' OR EXISTS (SELECT 1 FROM prediction_artists a WHERE a.prediction_id=p.id))))) BEGIN SELECT RAISE(ABORT,'Current vibe does not match its original score'); END;

CREATE TRIGGER sample_attributes_insert AFTER INSERT ON sample_attributes BEGIN INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id=NEW.recording_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER sample_attributes_update AFTER UPDATE ON sample_attributes BEGIN INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id=OLD.recording_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1;INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id=NEW.recording_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER sample_attributes_delete AFTER DELETE ON sample_attributes BEGIN INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id=OLD.recording_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER sample_attributes_identity BEFORE UPDATE OF recording_id ON sample_attributes WHEN NEW.recording_id<>OLD.recording_id AND EXISTS (SELECT 1 FROM measurement_samples WHERE sample_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Retire measurement sample links before reassociation'); END;

CREATE TRIGGER measurements_immutable BEFORE UPDATE ON measurements BEGIN SELECT RAISE(ABORT,'Vibe calculations are immutable'); END;

CREATE TRIGGER predictions_immutable BEFORE UPDATE ON predictions BEGIN SELECT RAISE(ABORT,'Vibe calculations are immutable'); END;

CREATE TRIGGER vibe_sample_reassociation AFTER UPDATE OF recording_id ON youtube_items WHEN NEW.recording_id<>OLD.recording_id BEGIN INSERT INTO rec_vibe_pending(group_key) SELECT DISTINCT json_array('artist_genre',artist_key,subgenre_key) FROM recording_vibes WHERE recording_id=OLD.recording_id AND artist_key IS NOT NULL AND subgenre_key IS NOT NULL ON CONFLICT(group_key) DO UPDATE SET revision=revision+1,cursor='';INSERT INTO rec_vibe_pending(group_key) SELECT DISTINCT json_array('artist',artist_key,NULL) FROM recording_vibes WHERE recording_id=OLD.recording_id AND artist_key IS NOT NULL ON CONFLICT(group_key) DO UPDATE SET revision=revision+1,cursor='';INSERT INTO rec_vibe_pending(group_key) SELECT DISTINCT json_array('genre',NULL,subgenre_key) FROM recording_vibes WHERE recording_id=OLD.recording_id AND subgenre_key IS NOT NULL ON CONFLICT(group_key) DO UPDATE SET revision=revision+1,cursor='';DELETE FROM recording_vibes WHERE recording_id=OLD.recording_id;DELETE FROM measurement_samples WHERE sample_id IN (SELECT id FROM sample_attributes WHERE video_id=NEW.video_id);UPDATE sample_attributes SET recording_id=NEW.recording_id WHERE video_id=NEW.video_id;INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id IN (OLD.recording_id,NEW.recording_id) ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TABLE album_provider_ids (provider TEXT NOT NULL,provider_id TEXT NOT NULL,album_id INTEGER NOT NULL REFERENCES albums(id),is_primary INTEGER NOT NULL DEFAULT 1 CHECK(is_primary IN (0,1)),equivalence_digest TEXT,verified_at REAL,PRIMARY KEY(provider,provider_id),CHECK(is_primary=1 OR (equivalence_digest IS NOT NULL AND verified_at IS NOT NULL)));

CREATE UNIQUE INDEX ix_album_primary_provider ON album_provider_ids(album_id,provider) WHERE is_primary=1;

CREATE INDEX ix_album_provider_release ON album_provider_ids(album_id,provider,provider_id);

CREATE TABLE album_provider_fingerprints (provider TEXT NOT NULL,provider_id TEXT NOT NULL,digest TEXT NOT NULL,observed_at REAL NOT NULL,PRIMARY KEY(provider,provider_id),FOREIGN KEY(provider,provider_id) REFERENCES album_provider_ids(provider,provider_id));

CREATE INDEX ix_album_fingerprint ON album_provider_fingerprints(provider,digest);

CREATE TABLE album_alias_reconciliations (retired_id INTEGER PRIMARY KEY REFERENCES albums(id),album_id INTEGER NOT NULL REFERENCES albums(id),comparison_digest TEXT NOT NULL,verified_at REAL NOT NULL,CHECK(retired_id<>album_id));

CREATE TABLE album_alias_checks (first_id TEXT NOT NULL,second_id TEXT NOT NULL,checked_at REAL NOT NULL,PRIMARY KEY(first_id,second_id),CHECK(first_id<second_id));

CREATE INDEX ix_album_alias_check_time ON album_alias_checks(checked_at);

CREATE VIEW album_primary_provider_ids AS SELECT provider,provider_id,album_id FROM album_provider_ids WHERE is_primary=1;

CREATE VIEW discovered_albums AS SELECT p.provider_id browse_id,a.artist,a.title,a.year,a.thumbnail,m.found_at,m.last_shown,COALESCE((SELECT g.name FROM genre_catalog g WHERE g.key=a.genre_key),a.unresolved_genre) AS genre,m.first_shown,m.offered_count,m.legacy_offered_count,m.legacy_first_shown,m.legacy_last_shown,(SELECT artist_id FROM album_artists aa WHERE aa.album_id=a.id ORDER BY position LIMIT 1) artist_id FROM album_discovery_memberships m JOIN albums a ON a.id=m.album_id JOIN album_primary_provider_ids p ON p.album_id=a.id AND p.provider='youtube';

CREATE TRIGGER discovered_albums_update INSTEAD OF UPDATE ON discovered_albums BEGIN UPDATE album_discovery_memberships SET found_at=NEW.found_at,last_shown=NEW.last_shown,first_shown=NEW.first_shown,offered_count=NEW.offered_count,legacy_offered_count=NEW.legacy_offered_count,legacy_first_shown=NEW.legacy_first_shown,legacy_last_shown=NEW.legacy_last_shown WHERE album_id=(SELECT album_id FROM album_provider_ids WHERE provider='youtube' AND provider_id=OLD.browse_id); END;

CREATE TRIGGER discovered_albums_delete INSTEAD OF DELETE ON discovered_albums BEGIN DELETE FROM album_discovery_memberships WHERE album_id=(SELECT album_id FROM album_provider_ids WHERE provider='youtube' AND provider_id=OLD.browse_id); END;

CREATE TRIGGER musical_link_delete AFTER DELETE ON rec_musical_links BEGIN INSERT INTO rec_content_pending(identity_key) SELECT identity_key FROM recordings WHERE id=OLD.recording_id ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TABLE mood_events (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at REAL NOT NULL,direction INTEGER NOT NULL);

CREATE INDEX ix_mood_event_order ON mood_events(created_at,id);

CREATE TABLE mood_event_recordings (mood_event_id INTEGER NOT NULL REFERENCES mood_events(id) ON DELETE CASCADE,recording_id INTEGER NOT NULL REFERENCES recordings(id),position INTEGER NOT NULL CHECK(position>=0),PRIMARY KEY(mood_event_id,recording_id),UNIQUE(mood_event_id,position)) WITHOUT ROWID;

CREATE INDEX ix_mood_seed_recording ON mood_event_recordings(recording_id,mood_event_id);

CREATE TABLE mood_event_unresolved_seeds (mood_event_id INTEGER NOT NULL REFERENCES mood_events(id) ON DELETE CASCADE,legacy_key TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),reason TEXT NOT NULL CHECK(reason IN ('unknown_recording','ambiguous_alias')),PRIMARY KEY(mood_event_id,legacy_key),UNIQUE(mood_event_id,position)) WITHOUT ROWID;

CREATE INDEX ix_mood_unresolved_key ON mood_event_unresolved_seeds(legacy_key,mood_event_id);

CREATE TRIGGER mood_event_recordings_position_insert BEFORE INSERT ON mood_event_recordings WHEN EXISTS(SELECT 1 FROM mood_event_unresolved_seeds WHERE mood_event_id=NEW.mood_event_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Mood seed position is already occupied'); END;

CREATE TRIGGER mood_event_recordings_position_update BEFORE UPDATE ON mood_event_recordings WHEN EXISTS(SELECT 1 FROM mood_event_unresolved_seeds WHERE mood_event_id=NEW.mood_event_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Mood seed position is already occupied'); END;

CREATE TRIGGER mood_event_unresolved_seeds_position_insert BEFORE INSERT ON mood_event_unresolved_seeds WHEN EXISTS(SELECT 1 FROM mood_event_recordings WHERE mood_event_id=NEW.mood_event_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Mood seed position is already occupied'); END;

CREATE TRIGGER mood_event_unresolved_seeds_position_update BEFORE UPDATE ON mood_event_unresolved_seeds WHEN EXISTS(SELECT 1 FROM mood_event_recordings WHERE mood_event_id=NEW.mood_event_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Mood seed position is already occupied'); END;

CREATE TABLE audio_taxonomies (taxonomy_version TEXT PRIMARY KEY NOT NULL,status TEXT NOT NULL CHECK(status IN ('supported','legacy_observed')));

CREATE TABLE audio_taxonomy_labels (taxonomy_version TEXT NOT NULL REFERENCES audio_taxonomies(taxonomy_version),vibe TEXT NOT NULL CHECK(length(vibe)>0),PRIMARY KEY(taxonomy_version,vibe)) WITHOUT ROWID;

CREATE TABLE audio_annotations (id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT REFERENCES audio_vibe_runs(run_id),kind TEXT NOT NULL CHECK(kind IN ('feedback','development','session')),taxonomy_version TEXT NOT NULL REFERENCES audio_taxonomies(taxonomy_version),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),state TEXT NOT NULL CHECK(state IN ('labeled','empty','withdrawn')),created_at REAL NOT NULL,supersedes_id INTEGER UNIQUE REFERENCES audio_annotations(id),legacy_run_key TEXT,sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN (0,1)),resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','legacy_missing_run')),unresolved_sample_count INTEGER NOT NULL DEFAULT 0 CHECK(typeof(unresolved_sample_count)='integer' AND unresolved_sample_count>=0),model_output_filename TEXT NOT NULL,model_output_digest TEXT NOT NULL CHECK(length(model_output_digest)=64 AND model_output_digest NOT GLOB '*[^0-9a-f]*'),file_format TEXT NOT NULL CHECK(file_format='audio-annotation-1'),CHECK(substr(model_output_filename,-69)=model_output_digest||'.json'),UNIQUE(id,taxonomy_version),CHECK((run_id IS NOT NULL AND legacy_run_key IS NULL AND resolution_status='resolved') OR (run_id IS NULL AND legacy_run_key IS NOT NULL AND resolution_status='legacy_missing_run')));

CREATE UNIQUE INDEX ix_annotation_revision ON audio_annotations(COALESCE(run_id,legacy_run_key),kind,taxonomy_version,revision);

CREATE INDEX ix_annotation_latest ON audio_annotations(COALESCE(run_id,legacy_run_key),kind,taxonomy_version,revision DESC);

CREATE TABLE audio_annotation_samples (annotation_id INTEGER NOT NULL REFERENCES audio_annotations(id),sample_id TEXT NOT NULL REFERENCES sample_attributes(id),position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),PRIMARY KEY(annotation_id,sample_id),UNIQUE(annotation_id,position)) WITHOUT ROWID;

CREATE INDEX ix_annotation_sample ON audio_annotation_samples(sample_id,annotation_id);

CREATE TABLE audio_annotation_vibes (annotation_id INTEGER NOT NULL,taxonomy_version TEXT NOT NULL,vibe TEXT NOT NULL,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),PRIMARY KEY(annotation_id,vibe),UNIQUE(annotation_id,position),FOREIGN KEY(annotation_id,taxonomy_version) REFERENCES audio_annotations(id,taxonomy_version),FOREIGN KEY(taxonomy_version,vibe) REFERENCES audio_taxonomy_labels(taxonomy_version,vibe)) WITHOUT ROWID;

CREATE INDEX ix_annotation_vibe ON audio_annotation_vibes(taxonomy_version,vibe,annotation_id);

CREATE TABLE audio_annotation_evaluations (annotation_id INTEGER PRIMARY KEY REFERENCES audio_annotations(id),taxonomy_version TEXT NOT NULL REFERENCES audio_taxonomies(taxonomy_version),prediction_version TEXT,model_present INTEGER NOT NULL CHECK(model_present IN (0,1)),model_labels_present INTEGER NOT NULL CHECK(model_labels_present IN (0,1)),model_sha256 TEXT,model_feature_version TEXT,model_training_songs INTEGER CHECK(model_training_songs IS NULL OR (typeof(model_training_songs)='integer' AND model_training_songs>=0)),UNIQUE(annotation_id,taxonomy_version));

CREATE TABLE audio_annotation_scores (annotation_id INTEGER NOT NULL,taxonomy_version TEXT NOT NULL,vibe TEXT NOT NULL,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),score REAL NOT NULL CHECK(score BETWEEN 0 AND 1),PRIMARY KEY(annotation_id,vibe),UNIQUE(annotation_id,position),FOREIGN KEY(annotation_id,taxonomy_version) REFERENCES audio_annotation_evaluations(annotation_id,taxonomy_version),FOREIGN KEY(taxonomy_version,vibe) REFERENCES audio_taxonomy_labels(taxonomy_version,vibe)) WITHOUT ROWID;

CREATE TABLE audio_annotation_predictions (annotation_id INTEGER NOT NULL,vibe TEXT NOT NULL,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),PRIMARY KEY(annotation_id,vibe),UNIQUE(annotation_id,position),FOREIGN KEY(annotation_id,vibe) REFERENCES audio_annotation_scores(annotation_id,vibe)) WITHOUT ROWID;

CREATE TABLE audio_annotation_model_labels (annotation_id INTEGER NOT NULL,taxonomy_version TEXT NOT NULL,vibe TEXT NOT NULL,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),PRIMARY KEY(annotation_id,vibe),UNIQUE(annotation_id,position),FOREIGN KEY(annotation_id,taxonomy_version) REFERENCES audio_annotation_evaluations(annotation_id,taxonomy_version),FOREIGN KEY(taxonomy_version,vibe) REFERENCES audio_taxonomy_labels(taxonomy_version,vibe)) WITHOUT ROWID;

CREATE TRIGGER audio_annotation_revision BEFORE INSERT ON audio_annotations WHEN NEW.sealed<>0 OR (NEW.supersedes_id IS NULL AND NEW.revision<>1) OR (NEW.supersedes_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM audio_annotations a WHERE a.id=NEW.supersedes_id AND COALESCE(a.run_id,a.legacy_run_key)=COALESCE(NEW.run_id,NEW.legacy_run_key) AND a.kind=NEW.kind AND a.taxonomy_version=NEW.taxonomy_version AND a.sealed=1 AND NEW.revision=a.revision+1)) BEGIN SELECT RAISE(ABORT,'Annotation revision does not follow its own judgment'); END;

CREATE TRIGGER audio_annotation_immutable BEFORE UPDATE ON audio_annotations WHEN NEW.id IS NOT OLD.id OR NEW.kind IS NOT OLD.kind OR NEW.taxonomy_version IS NOT OLD.taxonomy_version OR NEW.revision IS NOT OLD.revision OR NEW.state IS NOT OLD.state OR NEW.created_at IS NOT OLD.created_at OR NEW.supersedes_id IS NOT OLD.supersedes_id OR NEW.unresolved_sample_count IS NOT OLD.unresolved_sample_count OR (NEW.sealed IS NOT OLD.sealed AND NOT (OLD.sealed=0 AND NEW.sealed=1)) OR NEW.model_output_digest IS NOT OLD.model_output_digest OR NEW.file_format IS NOT OLD.file_format OR ((NEW.run_id IS NOT OLD.run_id OR NEW.legacy_run_key IS NOT OLD.legacy_run_key OR NEW.resolution_status IS NOT OLD.resolution_status) AND NOT (OLD.run_id IS NULL AND NEW.run_id=OLD.legacy_run_key AND NEW.legacy_run_key IS NULL AND NEW.resolution_status='resolved')) BEGIN SELECT RAISE(ABORT,'Supersede an annotation instead of rewriting its judgment'); END;

CREATE TRIGGER audio_annotation_seal BEFORE UPDATE OF sealed ON audio_annotations WHEN OLD.sealed=0 AND NEW.sealed=1 AND ((NEW.state='labeled' AND NOT EXISTS(SELECT 1 FROM audio_annotation_vibes WHERE annotation_id=NEW.id)) OR (NEW.state<>'labeled' AND EXISTS(SELECT 1 FROM audio_annotation_vibes WHERE annotation_id=NEW.id))) BEGIN SELECT RAISE(ABORT,'Annotation labels do not match its final judgment state'); END;

CREATE TRIGGER audio_annotation_retained BEFORE DELETE ON audio_annotations BEGIN SELECT RAISE(ABORT,'Annotation history must be retained'); END;

CREATE TRIGGER audio_annotation_samples_insert BEFORE INSERT ON audio_annotation_samples WHEN NOT EXISTS(SELECT 1 FROM audio_annotations a JOIN sample_attributes s ON s.run_id=COALESCE(a.run_id,a.legacy_run_key) WHERE a.id=NEW.annotation_id AND s.id=NEW.sample_id) BEGIN SELECT RAISE(ABORT,'Annotation sample belongs to another run'); END;

CREATE TRIGGER audio_annotation_vibes_insert BEFORE INSERT ON audio_annotation_vibes WHEN NOT EXISTS(SELECT 1 FROM audio_annotations a WHERE a.id=NEW.annotation_id AND a.state='labeled' AND (a.kind<>'feedback' OR NOT EXISTS(SELECT 1 FROM audio_annotation_vibes v WHERE v.annotation_id=a.id AND v.vibe<>NEW.vibe))) BEGIN SELECT RAISE(ABORT,'Invalid annotation label state'); END;

CREATE TRIGGER audio_annotation_samples_update BEFORE UPDATE ON audio_annotation_samples WHEN NOT EXISTS(SELECT 1 FROM audio_annotations a JOIN sample_attributes s ON s.run_id=COALESCE(a.run_id,a.legacy_run_key) WHERE a.id=NEW.annotation_id AND s.id=NEW.sample_id) BEGIN SELECT RAISE(ABORT,'Annotation sample belongs to another run'); END;

CREATE TRIGGER audio_annotation_vibes_update BEFORE UPDATE ON audio_annotation_vibes WHEN NOT EXISTS(SELECT 1 FROM audio_annotations a WHERE a.id=NEW.annotation_id AND a.state='labeled' AND (a.kind<>'feedback' OR NOT EXISTS(SELECT 1 FROM audio_annotation_vibes v WHERE v.annotation_id=a.id AND v.vibe<>NEW.vibe))) BEGIN SELECT RAISE(ABORT,'Invalid annotation label state'); END;

CREATE TRIGGER annotation_sample_run BEFORE UPDATE OF run_id,video_id ON sample_attributes WHEN (NEW.run_id IS NOT OLD.run_id OR NEW.video_id IS NOT OLD.video_id) AND EXISTS(SELECT 1 FROM audio_annotation_samples WHERE sample_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Retained annotation protects its sample run'); END;

CREATE TRIGGER annotation_run_identity BEFORE UPDATE OF run_id,video_id ON audio_vibe_runs WHEN (NEW.run_id IS NOT OLD.run_id OR NEW.video_id IS NOT OLD.video_id) AND EXISTS(SELECT 1 FROM audio_annotations WHERE run_id=OLD.run_id) BEGIN SELECT RAISE(ABORT,'Retained annotation protects its playback run'); END;

CREATE TRIGGER audio_annotation_samples_sealed_insert BEFORE INSERT ON audio_annotation_samples WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=NEW.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_samples_sealed_update BEFORE UPDATE ON audio_annotation_samples WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=OLD.annotation_id AND sealed=1) OR EXISTS(SELECT 1 FROM audio_annotations WHERE id=NEW.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_samples_sealed_delete BEFORE DELETE ON audio_annotation_samples WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=OLD.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_vibes_sealed_insert BEFORE INSERT ON audio_annotation_vibes WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=NEW.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_vibes_sealed_update BEFORE UPDATE ON audio_annotation_vibes WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=OLD.annotation_id AND sealed=1) OR EXISTS(SELECT 1 FROM audio_annotations WHERE id=NEW.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_vibes_sealed_delete BEFORE DELETE ON audio_annotation_vibes WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=OLD.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_evaluations_sealed_insert BEFORE INSERT ON audio_annotation_evaluations WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=NEW.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

CREATE TRIGGER audio_annotation_evaluations_sealed_update BEFORE UPDATE ON audio_annotation_evaluations WHEN EXISTS(SELECT 1 FROM audio_annotations WHERE id=OLD.annotation_id AND sealed=1) OR EXISTS(SELECT 1 FROM audio_annotations WHERE id=NEW.annotation_id AND sealed=1) BEGIN SELECT RAISE(ABORT,'Supersede a sealed annotation'); END;

