CREATE TABLE legacy_playlist_dismissals (source_ref TEXT PRIMARY KEY NOT NULL,playlist_scope_id TEXT REFERENCES playlist_scopes(id),until REAL,resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','ambiguous_account','missing_scope')),CHECK((resolution_status='resolved')=(playlist_scope_id IS NOT NULL))) WITHOUT ROWID;

CREATE INDEX ix_legacy_playlist_dismissal_scope ON legacy_playlist_dismissals(playlist_scope_id) WHERE playlist_scope_id IS NOT NULL;

-- Current scope attributes, account album checkpoints and account invariants.
CREATE TABLE account_album_state (account_id INTEGER PRIMARY KEY NOT NULL REFERENCES accounts(id),revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(revision)='integer' AND revision>=0),snapshot_observed_at REAL CHECK(snapshot_observed_at IS NULL OR (typeof(snapshot_observed_at) IN ('integer','real') AND snapshot_observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),legacy_cohort_present INTEGER NOT NULL DEFAULT 0 CHECK(typeof(legacy_cohort_present)='integer' AND legacy_cohort_present IN (0,1)),legacy_cohort_observed_at REAL CHECK(legacy_cohort_observed_at IS NULL OR (typeof(legacy_cohort_observed_at) IN ('integer','real') AND legacy_cohort_observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),CHECK(legacy_cohort_present=1 OR legacy_cohort_observed_at IS NULL)) WITHOUT ROWID;

CREATE TABLE account_albums (account_id INTEGER NOT NULL REFERENCES accounts(id),album_id INTEGER NOT NULL REFERENCES albums(id),source TEXT NOT NULL,saved_at REAL CHECK(saved_at IS NULL OR (typeof(saved_at) IN ('integer','real') AND saved_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),PRIMARY KEY(account_id,album_id)) WITHOUT ROWID;

CREATE INDEX ix_account_album_release ON account_albums(album_id,account_id);

CREATE TABLE unattributed_album_memberships (album_id INTEGER PRIMARY KEY NOT NULL REFERENCES albums(id),source TEXT NOT NULL,saved_at REAL CHECK(saved_at IS NULL OR (typeof(saved_at) IN ('integer','real') AND saved_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308))) WITHOUT ROWID;

CREATE VIEW saved_album_memberships AS SELECT account_id,album_id,source,saved_at FROM account_albums UNION ALL SELECT NULL,album_id,source,saved_at FROM unattributed_album_memberships;

CREATE INDEX ix_playlist_scope_group ON playlist_scopes(group_name) WHERE group_name IS NOT NULL;

CREATE INDEX ix_playlist_scope_hidden ON playlist_scopes(id) WHERE hidden=1;

CREATE INDEX ix_playlist_scope_overlap_ignored ON playlist_scopes(id) WHERE overlap_ignored=1;

CREATE VIEW quarantined_playlists AS SELECT id playlist_scope_id,'Generated' name FROM playlist_scopes WHERE origin='tuneconsole' AND adopted=0;

CREATE VIEW saved_albums AS SELECT p.provider_id browse_id,a.title,a.artist,a.year,a.type,a.thumbnail FROM albums a JOIN album_primary_provider_ids p ON p.album_id=a.id AND p.provider='youtube' WHERE EXISTS(SELECT 1 FROM saved_album_memberships m WHERE m.album_id=a.id);

CREATE TRIGGER rec_capture_account_albums_insert AFTER INSERT ON account_albums BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_account_albums_update AFTER UPDATE ON account_albums WHEN OLD.album_id IS NOT NEW.album_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_account_albums_delete AFTER DELETE ON account_albums BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_evidence_account_albums_insert AFTER INSERT ON account_albums BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_evidence_account_albums_update AFTER UPDATE ON account_albums WHEN OLD.album_id IS NOT NEW.album_id BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_evidence_account_albums_delete AFTER DELETE ON account_albums BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_unattributed_album_memberships_insert AFTER INSERT ON unattributed_album_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_unattributed_album_memberships_update AFTER UPDATE ON unattributed_album_memberships WHEN OLD.album_id IS NOT NEW.album_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_unattributed_album_memberships_delete AFTER DELETE ON unattributed_album_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_evidence_unattributed_album_memberships_insert AFTER INSERT ON unattributed_album_memberships BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_evidence_unattributed_album_memberships_update AFTER UPDATE ON unattributed_album_memberships WHEN OLD.album_id IS NOT NEW.album_id BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_evidence_unattributed_album_memberships_delete AFTER DELETE ON unattributed_album_memberships BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_playlist_scope_preferences_insert AFTER INSERT ON playlist_scopes WHEN NEW.group_name IS NOT NULL OR NEW.origin IS NOT NULL BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_playlist_scope_preferences_update AFTER UPDATE ON playlist_scopes WHEN OLD.group_name IS NOT NEW.group_name OR OLD.origin IS NOT NEW.origin OR OLD.adopted IS NOT NEW.adopted BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_playlist_scope_preferences_delete AFTER DELETE ON playlist_scopes WHEN OLD.group_name IS NOT NULL OR OLD.origin IS NOT NULL BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_evidence_playlist_scope_preferences_insert AFTER INSERT ON playlist_scopes WHEN NEW.group_name IS NOT NULL OR NEW.origin IS NOT NULL BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_evidence_playlist_scope_preferences_update AFTER UPDATE ON playlist_scopes WHEN OLD.group_name IS NOT NEW.group_name OR OLD.origin IS NOT NEW.origin OR OLD.adopted IS NOT NEW.adopted BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_evidence_playlist_scope_preferences_delete AFTER DELETE ON playlist_scopes WHEN OLD.group_name IS NOT NULL OR OLD.origin IS NOT NULL BEGIN UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE UNIQUE INDEX ix_account_active_master ON accounts(is_master) WHERE active=1 AND is_master=1;

CREATE TRIGGER owned_playlist_membership_refs_insert BEFORE INSERT ON playlist_membership_refs WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND (s.kind<>'account' OR s.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;

CREATE TRIGGER owned_playlist_membership_refs_update BEFORE UPDATE ON playlist_membership_refs WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND (s.kind<>'account' OR s.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;

CREATE TRIGGER owned_playlist_library_revisions_insert BEFORE INSERT ON playlist_library_revisions WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND (s.kind<>'account' OR s.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;

CREATE TRIGGER owned_playlist_library_revisions_update BEFORE UPDATE ON playlist_library_revisions WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND (s.kind<>'account' OR s.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Playlist scope belongs to another account'); END;

CREATE TRIGGER immutable_playlist_scope_identity BEFORE UPDATE OF id,provider_playlist_id,account_id,kind ON playlist_scopes WHEN NEW.id IS NOT OLD.id OR NEW.provider_playlist_id IS NOT OLD.provider_playlist_id OR NEW.account_id IS NOT OLD.account_id OR NEW.kind IS NOT OLD.kind BEGIN SELECT RAISE(ABORT,'Durable playlist scope identity is immutable'); END;

-- Current finite metadata evidence and explicit lineage. No historical conversion.
ALTER TABLE provider_attempts ADD COLUMN delivery_id INTEGER REFERENCES metadata_deliveries(id);

ALTER TABLE recording_identifiers ADD COLUMN delivery_id INTEGER REFERENCES metadata_deliveries(id);

ALTER TABLE recording_identifiers ADD COLUMN observation_id INTEGER REFERENCES metadata_observations(id);

CREATE TABLE metadata_legacy_records (legacy_owner TEXT NOT NULL CHECK(legacy_owner IN ('metadata_findings','enrichment_log','metadata_decisions','entry_field_choices','enrichment_conflict','recording_identifiers','provider_attempts','enrichment_provider_state','catalog_field_hints')),legacy_id INTEGER NOT NULL CHECK(typeof(legacy_id)='integer'),delivery_id INTEGER NOT NULL REFERENCES metadata_deliveries(id),entry_id INTEGER REFERENCES catalog_entries(id),recording_id INTEGER REFERENCES recordings(id),input_video_id TEXT REFERENCES youtube_items(video_id),disposition TEXT NOT NULL CHECK(disposition IN ('catalog_evidence','native_observation','unsupported_field','invalid_value','unproven_subject','unproven_scope','operational_state')),PRIMARY KEY(legacy_owner,legacy_id)) WITHOUT ROWID;

CREATE INDEX ix_metadata_legacy_delivery ON metadata_legacy_records(delivery_id);

CREATE TRIGGER owned_metadata_legacy_record BEFORE INSERT ON metadata_legacy_records WHEN NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.key_contract='legacy_record' AND d.raw_filename IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Legacy metadata requires its retained original delivery'); END;

CREATE TRIGGER immutable_metadata_legacy_record BEFORE UPDATE ON metadata_legacy_records BEGIN SELECT RAISE(ABORT,'Legacy metadata capture is immutable'); END;

CREATE TRIGGER retained_metadata_legacy_record BEFORE DELETE ON metadata_legacy_records BEGIN SELECT RAISE(ABORT,'Legacy metadata capture requires a retention disposition'); END;

CREATE TABLE native_metadata_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,delivery_id INTEGER NOT NULL REFERENCES metadata_deliveries(id),position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),field TEXT NOT NULL CHECK(field IN ('tags','bpm','energy','danceability','mood_party','mood_aggressive','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','loudness','dynamic_complexity')),kind TEXT NOT NULL CHECK(kind IN ('reported','measurement','prediction','curated','inherited','derived')),unit TEXT CHECK(unit IS NULL OR (typeof(unit)='text' AND length(CAST(unit AS BLOB)) BETWEEN 1 AND 256)),legacy_finding_id INTEGER UNIQUE,UNIQUE(delivery_id,position));

CREATE TRIGGER owned_native_metadata_delivery BEFORE INSERT ON native_metadata_observations WHEN NEW.legacy_finding_id IS NULL AND NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.key_contract IN ('capture','provider_revision') AND d.input_entry_id IS NOT NULL AND d.input_recording_id IS NOT NULL AND d.provider_entity_type IN ('recording','release','artist','genre','item')) BEGIN SELECT RAISE(ABORT,'Native metadata requires its captured source and input'); END;

CREATE TRIGGER owned_native_metadata_legacy BEFORE INSERT ON native_metadata_observations WHEN NEW.legacy_finding_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.legacy_owner='metadata_findings' AND r.legacy_id=NEW.legacy_finding_id AND r.delivery_id=NEW.delivery_id) BEGIN SELECT RAISE(ABORT,'Native metadata requires its retained original'); END;

CREATE TRIGGER immutable_native_metadata_observation BEFORE UPDATE ON native_metadata_observations BEGIN SELECT RAISE(ABORT,'Native metadata evidence is immutable'); END;

CREATE TABLE musical_source_observations (source_key TEXT NOT NULL REFERENCES rec_musical_sources(source_key),field TEXT NOT NULL CHECK(field IN ('tags','bpm','energy','danceability','mood_party','mood_aggressive','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','loudness','dynamic_complexity')),observation_id INTEGER NOT NULL REFERENCES native_metadata_observations(id),PRIMARY KEY(source_key,field)) WITHOUT ROWID;

