CREATE TABLE recording_metadata_selections (recording_id INTEGER NOT NULL REFERENCES recordings(id),field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental')),observation_id INTEGER REFERENCES metadata_observations(id),attribution_status TEXT NOT NULL CHECK(attribution_status IN ('evidenced','legacy_unresolved')),legacy_source TEXT,selected_at REAL CHECK(selected_at IS NULL OR (typeof(selected_at) IN ('integer','real') AND selected_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),CHECK((attribution_status='evidenced' AND observation_id IS NOT NULL AND legacy_source IS NULL) OR (attribution_status='legacy_unresolved' AND observation_id IS NULL AND legacy_source IS NOT NULL)),PRIMARY KEY(recording_id,field)) WITHOUT ROWID;

CREATE INDEX ix_recording_metadata_selections_observation ON recording_metadata_selections(observation_id) WHERE observation_id IS NOT NULL;

CREATE TRIGGER owned_recording_metadata_selections_insert BEFORE INSERT ON recording_metadata_selections WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.recording_id=NEW.recording_id AND o.field=NEW.field AND o.field_scope='recording' AND o.value_kind IN ('value','null','blank') AND o.origin NOT IN ('user','legacy_choice')) BEGIN SELECT RAISE(ABORT,'Metadata selection evidence has a different subject, field or scope'); END;

CREATE TRIGGER owned_recording_metadata_selections_update BEFORE UPDATE ON recording_metadata_selections WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.recording_id=NEW.recording_id AND o.field=NEW.field AND o.field_scope='recording' AND o.value_kind IN ('value','null','blank') AND o.origin NOT IN ('user','legacy_choice')) BEGIN SELECT RAISE(ABORT,'Metadata selection evidence has a different subject, field or scope'); END;

CREATE TABLE entry_metadata_selections (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL CHECK(field IN ('title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label')),observation_id INTEGER REFERENCES metadata_observations(id),attribution_status TEXT NOT NULL CHECK(attribution_status IN ('evidenced','legacy_unresolved')),legacy_source TEXT,selected_at REAL CHECK(selected_at IS NULL OR (typeof(selected_at) IN ('integer','real') AND selected_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),CHECK((attribution_status='evidenced' AND observation_id IS NOT NULL AND legacy_source IS NULL) OR (attribution_status='legacy_unresolved' AND observation_id IS NULL AND legacy_source IS NOT NULL)),PRIMARY KEY(entry_id,field)) WITHOUT ROWID;

CREATE INDEX ix_entry_metadata_selections_observation ON entry_metadata_selections(observation_id) WHERE observation_id IS NOT NULL;

CREATE TRIGGER owned_entry_metadata_selections_insert BEFORE INSERT ON entry_metadata_selections WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.field=NEW.field AND o.field_scope IN ('item','release') AND o.value_kind IN ('value','null','blank') AND o.origin NOT IN ('user','legacy_choice')) BEGIN SELECT RAISE(ABORT,'Metadata selection evidence has a different subject, field or scope'); END;

CREATE TRIGGER owned_entry_metadata_selections_update BEFORE UPDATE ON entry_metadata_selections WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.field=NEW.field AND o.field_scope IN ('item','release') AND o.value_kind IN ('value','null','blank') AND o.origin NOT IN ('user','legacy_choice')) BEGIN SELECT RAISE(ABORT,'Metadata selection evidence has a different subject, field or scope'); END;

CREATE TABLE metadata_choice_heads (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label')),observation_id INTEGER NOT NULL REFERENCES metadata_observations(id),PRIMARY KEY(entry_id,field)) WITHOUT ROWID;

CREATE INDEX ix_metadata_choice_observation ON metadata_choice_heads(observation_id);

CREATE TRIGGER owned_metadata_choice_insert BEFORE INSERT ON metadata_choice_heads WHEN NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.field=NEW.field AND o.origin IN ('user','legacy_choice','selection_snapshot') AND o.value_kind<>'unresolved') BEGIN SELECT RAISE(ABORT,'Metadata choice requires its actual retained decision'); END;

CREATE TRIGGER owned_metadata_choice_update BEFORE UPDATE ON metadata_choice_heads WHEN NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.field=NEW.field AND o.origin IN ('user','legacy_choice','selection_snapshot') AND o.value_kind<>'unresolved') BEGIN SELECT RAISE(ABORT,'Metadata choice requires its actual retained decision'); END;

CREATE TABLE metadata_conflicts (id INTEGER PRIMARY KEY AUTOINCREMENT,entry_id INTEGER REFERENCES catalog_entries(id),recording_id INTEGER REFERENCES recordings(id),field_scope TEXT NOT NULL CHECK(field_scope IN ('recording','release','item','legacy_item')),field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label')),status TEXT NOT NULL CHECK(status IN ('unresolved','user_resolved','provider_converged')),selected_observation_id INTEGER REFERENCES metadata_observations(id),updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND updated_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),legacy_record_id INTEGER UNIQUE,legacy_resolution_reason TEXT CHECK(legacy_resolution_reason IS NULL OR length(legacy_resolution_reason)>0),CHECK((entry_id IS NULL)<>(recording_id IS NULL)),CHECK((recording_id IS NOT NULL AND field_scope='recording' AND field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental')) OR (entry_id IS NOT NULL AND field_scope='legacy_item' AND legacy_record_id IS NOT NULL) OR (entry_id IS NOT NULL AND field_scope='release' AND field IN ('mb_year','label')) OR (entry_id IS NOT NULL AND field_scope='item' AND field IN ('title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','loudness','dynamic_complexity','popularity','gain'))),CHECK(status<>'user_resolved' OR selected_observation_id IS NOT NULL OR (legacy_record_id IS NOT NULL AND legacy_resolution_reason IS NOT NULL)));

CREATE TRIGGER owned_legacy_metadata_conflict BEFORE INSERT ON metadata_conflicts WHEN NEW.legacy_record_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.legacy_owner='enrichment_conflict' AND r.legacy_id=NEW.legacy_record_id AND ((NEW.entry_id IS NOT NULL AND r.entry_id=NEW.entry_id) OR (NEW.recording_id IS NOT NULL AND r.recording_id=NEW.recording_id))) BEGIN SELECT RAISE(ABORT,'Legacy metadata conflict requires its retained original subject'); END;

CREATE UNIQUE INDEX ix_metadata_conflict_entry ON metadata_conflicts(entry_id,field) WHERE entry_id IS NOT NULL;

CREATE UNIQUE INDEX ix_metadata_conflict_recording ON metadata_conflicts(recording_id,field) WHERE recording_id IS NOT NULL;

CREATE INDEX ix_metadata_conflict_selection ON metadata_conflicts(selected_observation_id) WHERE selected_observation_id IS NOT NULL;

CREATE TABLE metadata_conflict_candidates (conflict_id INTEGER NOT NULL REFERENCES metadata_conflicts(id),observation_id INTEGER NOT NULL REFERENCES metadata_observations(id),position INTEGER NOT NULL DEFAULT 0 CHECK(typeof(position)='integer' AND position>=0),PRIMARY KEY(conflict_id,observation_id)) WITHOUT ROWID;

CREATE INDEX ix_metadata_candidate_observation ON metadata_conflict_candidates(observation_id,conflict_id);

CREATE TRIGGER owned_metadata_conflict_candidate_insert BEFORE INSERT ON metadata_conflict_candidates WHEN NOT EXISTS(SELECT 1 FROM metadata_observations o JOIN metadata_conflicts c ON c.id=NEW.conflict_id WHERE o.id=NEW.observation_id AND o.field=c.field AND ((c.entry_id IS NOT NULL AND o.entry_id=c.entry_id AND (o.field_scope=c.field_scope OR c.field_scope='legacy_item')) OR (c.recording_id IS NOT NULL AND o.recording_id=c.recording_id AND o.field_scope='recording')) AND o.value_kind<>'withdrawn') BEGIN SELECT RAISE(ABORT,'Metadata conflict candidate has a different subject, field or scope'); END;

CREATE TRIGGER owned_metadata_conflict_selection_insert BEFORE INSERT ON metadata_conflicts WHEN NEW.selected_observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.selected_observation_id AND (o.field=NEW.field AND ((NEW.entry_id IS NOT NULL AND o.entry_id=NEW.entry_id AND (o.field_scope=NEW.field_scope OR NEW.field_scope='legacy_item')) OR (NEW.recording_id IS NOT NULL AND o.recording_id=NEW.recording_id AND o.field_scope='recording')) OR (NEW.field_scope='legacy_item' AND o.entry_id=NEW.entry_id AND o.field=NEW.field AND o.origin IN ('user','legacy_choice'))) AND o.value_kind IN ('value','null','blank')) BEGIN SELECT RAISE(ABORT,'Metadata conflict selection has a different subject, field or scope'); END;

CREATE TRIGGER owned_metadata_conflict_candidate_update BEFORE UPDATE ON metadata_conflict_candidates WHEN NOT EXISTS(SELECT 1 FROM metadata_observations o JOIN metadata_conflicts c ON c.id=NEW.conflict_id WHERE o.id=NEW.observation_id AND o.field=c.field AND ((c.entry_id IS NOT NULL AND o.entry_id=c.entry_id AND (o.field_scope=c.field_scope OR c.field_scope='legacy_item')) OR (c.recording_id IS NOT NULL AND o.recording_id=c.recording_id AND o.field_scope='recording')) AND o.value_kind<>'withdrawn') BEGIN SELECT RAISE(ABORT,'Metadata conflict candidate has a different subject, field or scope'); END;

CREATE TRIGGER owned_metadata_conflict_selection_update BEFORE UPDATE ON metadata_conflicts WHEN NEW.selected_observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.selected_observation_id AND (o.field=NEW.field AND ((NEW.entry_id IS NOT NULL AND o.entry_id=NEW.entry_id AND (o.field_scope=NEW.field_scope OR NEW.field_scope='legacy_item')) OR (NEW.recording_id IS NOT NULL AND o.recording_id=NEW.recording_id AND o.field_scope='recording')) OR (NEW.field_scope='legacy_item' AND o.entry_id=NEW.entry_id AND o.field=NEW.field AND o.origin IN ('user','legacy_choice'))) AND o.value_kind IN ('value','null','blank')) BEGIN SELECT RAISE(ABORT,'Metadata conflict selection has a different subject, field or scope'); END;

CREATE TRIGGER immutable_metadata_conflict_subject BEFORE UPDATE OF id,entry_id,recording_id,field_scope,field,legacy_record_id ON metadata_conflicts BEGIN SELECT RAISE(ABORT,'Metadata conflict subject is immutable'); END;

CREATE INDEX ix_metadata_evidence_entry ON metadata_observations(entry_id,field,id);

CREATE TABLE provider_attempt_fields (attempt_id INTEGER NOT NULL REFERENCES provider_attempts(id),field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label','year','art','isrc','mb_release_ids','cover_url')),observation_id INTEGER REFERENCES metadata_observations(id),CHECK(field NOT IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label','year') OR observation_id IS NOT NULL),PRIMARY KEY(attempt_id,field)) WITHOUT ROWID;

CREATE INDEX ix_provider_attempt_field ON provider_attempt_fields(field,attempt_id);

CREATE INDEX ix_provider_attempt_field_observation ON provider_attempt_fields(observation_id) WHERE observation_id IS NOT NULL;

CREATE TABLE provider_state_fields (recording_id INTEGER NOT NULL,provider TEXT NOT NULL,field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label','year','art','isrc','mb_release_ids','cover_url')),delivery_id INTEGER NOT NULL REFERENCES metadata_deliveries(id),observation_id INTEGER REFERENCES metadata_observations(id),CHECK(field NOT IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label','year') OR observation_id IS NOT NULL),FOREIGN KEY(recording_id,provider) REFERENCES enrichment_provider_state(recording_id,provider),PRIMARY KEY(recording_id,provider,field)) WITHOUT ROWID;

CREATE INDEX ix_provider_state_field_observation ON provider_state_fields(observation_id) WHERE observation_id IS NOT NULL;

CREATE INDEX ix_provider_state_field_delivery ON provider_state_fields(delivery_id);

CREATE TRIGGER owned_provider_attempt_field_insert BEFORE INSERT ON provider_attempt_fields WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o JOIN provider_attempts a ON a.id=NEW.attempt_id WHERE o.id=NEW.observation_id AND o.field=CASE NEW.field WHEN 'year' THEN 'mb_year' ELSE NEW.field END AND o.delivery_id=a.delivery_id AND o.recording_id=a.recording_id) BEGIN SELECT RAISE(ABORT,'Attempt field has a different subject, delivery or field'); END;

CREATE TRIGGER owned_provider_state_field_insert BEFORE INSERT ON provider_state_fields WHEN NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.provider=NEW.provider AND (d.input_recording_id=NEW.recording_id OR EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.delivery_id=d.id AND r.legacy_owner IN ('provider_attempts','enrichment_provider_state') AND r.recording_id=NEW.recording_id))) OR (NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.delivery_id=NEW.delivery_id AND o.recording_id=NEW.recording_id AND o.field=CASE NEW.field WHEN 'year' THEN 'mb_year' ELSE NEW.field END)) BEGIN SELECT RAISE(ABORT,'Provider state field has a different subject, delivery or field'); END;

CREATE TRIGGER owned_provider_attempt_field_update BEFORE UPDATE ON provider_attempt_fields WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o JOIN provider_attempts a ON a.id=NEW.attempt_id WHERE o.id=NEW.observation_id AND o.field=CASE NEW.field WHEN 'year' THEN 'mb_year' ELSE NEW.field END AND o.delivery_id=a.delivery_id AND o.recording_id=a.recording_id) BEGIN SELECT RAISE(ABORT,'Attempt field has a different subject, delivery or field'); END;

CREATE TRIGGER owned_provider_state_field_update BEFORE UPDATE ON provider_state_fields WHEN NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.provider=NEW.provider AND (d.input_recording_id=NEW.recording_id OR EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.delivery_id=d.id AND r.legacy_owner IN ('provider_attempts','enrichment_provider_state') AND r.recording_id=NEW.recording_id))) OR (NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.delivery_id=NEW.delivery_id AND o.recording_id=NEW.recording_id AND o.field=CASE NEW.field WHEN 'year' THEN 'mb_year' ELSE NEW.field END)) BEGIN SELECT RAISE(ABORT,'Provider state field has a different subject, delivery or field'); END;

CREATE TABLE metadata_hints (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label')),source TEXT NOT NULL CHECK(length(source)>0),observation_id INTEGER NOT NULL REFERENCES metadata_observations(id),active INTEGER NOT NULL DEFAULT 1 CHECK(typeof(active)='integer' AND active IN (0,1)),PRIMARY KEY(entry_id,field,source)) WITHOUT ROWID;

CREATE INDEX ix_metadata_hint_observation ON metadata_hints(observation_id);

CREATE TRIGGER owned_metadata_hint_insert BEFORE INSERT ON metadata_hints WHEN NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.field=NEW.field) BEGIN SELECT RAISE(ABORT,'Metadata hint has a different entry or field'); END;

CREATE TRIGGER owned_metadata_hint_update BEFORE UPDATE ON metadata_hints WHEN NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.field=NEW.field) BEGIN SELECT RAISE(ABORT,'Metadata hint has a different entry or field'); END;

CREATE UNIQUE INDEX ix_provider_attempt_delivery ON provider_attempts(delivery_id) WHERE delivery_id IS NOT NULL;

CREATE INDEX ix_recording_identifier_delivery ON recording_identifiers(delivery_id);

CREATE UNIQUE INDEX ix_recording_identifier_delivery_value ON recording_identifiers(delivery_id,scheme,entity_type,value) WHERE delivery_id IS NOT NULL;

CREATE INDEX ix_recording_identifier_observation ON recording_identifiers(observation_id) WHERE observation_id IS NOT NULL;

CREATE TRIGGER owned_recording_identifier_delivery_insert BEFORE INSERT ON recording_identifiers WHEN NEW.delivery_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.provider=NEW.source AND ((d.input_recording_id=NEW.recording_id AND d.input_video_id IS NEW.input_video_id) OR EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.delivery_id=d.id AND r.legacy_owner='recording_identifiers' AND r.recording_id=NEW.recording_id AND r.input_video_id IS NEW.input_video_id))) BEGIN SELECT RAISE(ABORT,'Identifier delivery has a different provider or captured subject'); END;

CREATE TRIGGER owned_recording_identifier_observation_insert BEFORE INSERT ON recording_identifiers WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND NEW.scheme='musicbrainz' AND NEW.entity_type='recording' AND o.field='mb_recording_id' AND o.value_kind='value' AND o.text_value=NEW.value AND o.recording_id=NEW.recording_id AND o.delivery_id=NEW.delivery_id) BEGIN SELECT RAISE(ABORT,'Identifier observation has a different value, scheme or subject'); END;

CREATE TRIGGER owned_recording_identifier_delivery_update BEFORE UPDATE ON recording_identifiers WHEN NEW.delivery_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.provider=NEW.source AND ((d.input_recording_id=NEW.recording_id AND d.input_video_id IS NEW.input_video_id) OR EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.delivery_id=d.id AND r.legacy_owner='recording_identifiers' AND r.recording_id=NEW.recording_id AND r.input_video_id IS NEW.input_video_id))) BEGIN SELECT RAISE(ABORT,'Identifier delivery has a different provider or captured subject'); END;

CREATE TRIGGER owned_recording_identifier_observation_update BEFORE UPDATE ON recording_identifiers WHEN NEW.observation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_observations o WHERE o.id=NEW.observation_id AND NEW.scheme='musicbrainz' AND NEW.entity_type='recording' AND o.field='mb_recording_id' AND o.value_kind='value' AND o.text_value=NEW.value AND o.recording_id=NEW.recording_id AND o.delivery_id=NEW.delivery_id) BEGIN SELECT RAISE(ABORT,'Identifier observation has a different value, scheme or subject'); END;

CREATE VIEW entry_field_choices AS SELECT h.entry_id,h.field,json_quote(CASE WHEN o.number_value IS NOT NULL THEN o.number_value ELSE COALESCE((SELECT name FROM genre_catalog WHERE key=COALESCE((SELECT genre_key FROM genre_redirects WHERE retired_key=o.genre_key),o.genre_key)),o.text_value) END) AS value_json,o.legacy_source AS source FROM metadata_choice_heads h JOIN metadata_observations o ON o.id=h.observation_id WHERE o.value_kind<>'withdrawn';

CREATE VIEW metadata_decisions AS SELECT o.id,o.entry_id,o.field,json_quote(CASE WHEN o.number_value IS NOT NULL THEN o.number_value ELSE o.text_value END) AS value_json,o.legacy_source AS source,o.observed_at AS chosen_at,o.legacy_reference AS legacy_ref FROM metadata_observations o WHERE o.origin IN ('user','legacy_choice') AND o.value_kind<>'withdrawn';

CREATE VIEW catalog_field_hints AS SELECT h.entry_id,h.field,h.source,json_quote(CASE WHEN o.number_value IS NOT NULL THEN o.number_value ELSE o.text_value END) AS value_json,h.active FROM metadata_hints h JOIN metadata_observations o ON o.id=h.observation_id;

CREATE VIEW recording_field_sources AS SELECT s.recording_id,s.field,COALESCE(d.provider,o.legacy_source,s.legacy_source) AS source,s.selected_at FROM recording_metadata_selections s LEFT JOIN metadata_observations o ON o.id=s.observation_id LEFT JOIN metadata_deliveries d ON d.id=o.delivery_id;

CREATE VIEW item_field_sources AS SELECT s.entry_id,s.field,COALESCE(d.provider,o.legacy_source,s.legacy_source) AS source,s.selected_at FROM entry_metadata_selections s LEFT JOIN metadata_observations o ON o.id=s.observation_id LEFT JOIN metadata_deliveries d ON d.id=o.delivery_id;

CREATE VIEW enrichment_log AS SELECT o.id,o.entry_id AS track_id,o.source_run_id AS run_id,COALESCE(o.legacy_source,d.provider) AS provider,CASE o.field WHEN 'mb_year' THEN 'year' ELSE o.field END AS field,CAST(CASE WHEN o.number_value IS NOT NULL THEN o.number_value ELSE o.text_value END AS TEXT) AS value,o.observed_at AS created_at,o.recording_id,o.input_video_id,o.field_scope FROM metadata_observations o LEFT JOIN metadata_deliveries d ON d.id=o.delivery_id WHERE o.origin IN ('provider','legacy_log');

CREATE VIEW enrichment_conflict AS SELECT c.id,e.id AS track_id,CASE c.field WHEN 'mb_year' THEN 'year' ELSE c.field END AS field,(SELECT json_group_array(json(candidate)) FROM (SELECT json_object('provider',COALESCE(o.legacy_source,d.provider),'value',CASE WHEN o.number_value IS NOT NULL THEN o.number_value ELSE o.text_value END) AS candidate FROM metadata_conflict_candidates p JOIN metadata_observations o ON o.id=p.observation_id LEFT JOIN metadata_deliveries d ON d.id=o.delivery_id WHERE p.conflict_id=c.id ORDER BY p.position,o.id)) AS candidates,CASE c.status WHEN 'user_resolved' THEN 1 WHEN 'provider_converged' THEN 2 ELSE 0 END AS resolved,CAST(CASE WHEN chosen.number_value IS NOT NULL THEN chosen.number_value ELSE chosen.text_value END AS TEXT) AS resolved_value,c.updated_at,COALESCE(c.recording_id,r.recording_id) AS recording_id,r.input_video_id,c.field_scope FROM metadata_conflicts c JOIN catalog_entries e ON e.id=c.entry_id OR e.recording_id=c.recording_id LEFT JOIN metadata_observations chosen ON chosen.id=c.selected_observation_id LEFT JOIN metadata_legacy_records r ON r.legacy_owner='enrichment_conflict' AND r.legacy_id=c.legacy_record_id;

CREATE TRIGGER rec_capture_metadata_choice_heads_insert AFTER INSERT ON metadata_choice_heads BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_content_metadata_choice_heads_insert AFTER INSERT ON metadata_choice_heads BEGIN INSERT INTO rec_content_pending(identity_key) SELECT (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=NEW.entry_id) WHERE (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=NEW.entry_id) IS NOT NULL ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_metadata_choice_heads_update AFTER UPDATE ON metadata_choice_heads WHEN OLD.entry_id IS NOT NEW.entry_id OR OLD.field IS NOT NEW.field OR (SELECT value_kind FROM metadata_observations WHERE id=OLD.observation_id) IS NOT (SELECT value_kind FROM metadata_observations WHERE id=NEW.observation_id) OR (SELECT text_value FROM metadata_observations WHERE id=OLD.observation_id) IS NOT (SELECT text_value FROM metadata_observations WHERE id=NEW.observation_id) OR (SELECT number_value FROM metadata_observations WHERE id=OLD.observation_id) IS NOT (SELECT number_value FROM metadata_observations WHERE id=NEW.observation_id) BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_content_metadata_choice_heads_update AFTER UPDATE ON metadata_choice_heads WHEN OLD.entry_id IS NOT NEW.entry_id OR OLD.field IS NOT NEW.field OR (SELECT value_kind FROM metadata_observations WHERE id=OLD.observation_id) IS NOT (SELECT value_kind FROM metadata_observations WHERE id=NEW.observation_id) OR (SELECT text_value FROM metadata_observations WHERE id=OLD.observation_id) IS NOT (SELECT text_value FROM metadata_observations WHERE id=NEW.observation_id) OR (SELECT number_value FROM metadata_observations WHERE id=OLD.observation_id) IS NOT (SELECT number_value FROM metadata_observations WHERE id=NEW.observation_id) BEGIN INSERT INTO rec_content_pending(identity_key) SELECT (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=OLD.entry_id) WHERE (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=OLD.entry_id) IS NOT NULL ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1;INSERT INTO rec_content_pending(identity_key) SELECT (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=NEW.entry_id) WHERE (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=NEW.entry_id) IS NOT NULL ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_capture_metadata_choice_heads_delete AFTER DELETE ON metadata_choice_heads BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER rec_content_metadata_choice_heads_delete AFTER DELETE ON metadata_choice_heads BEGIN INSERT INTO rec_content_pending(identity_key) SELECT (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=OLD.entry_id) WHERE (SELECT r.identity_key FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id WHERE e.id=OLD.entry_id) IS NOT NULL ON CONFLICT(identity_key) DO UPDATE SET revision=revision+1; END;

CREATE INDEX ix_metadata_evidence_recording ON metadata_observations(recording_id,field,id);

CREATE INDEX ix_metadata_evidence_delivery ON metadata_observations(delivery_id,id);

CREATE INDEX ix_metadata_evidence_genre ON metadata_observations(genre_key,id);

CREATE INDEX ix_metadata_evidence_derived ON metadata_observations(derived_from_observation_id);

CREATE UNIQUE INDEX ix_metadata_observation_legacy ON metadata_observations(origin,legacy_owner,legacy_id,legacy_position) WHERE legacy_owner IS NOT NULL;

CREATE UNIQUE INDEX ix_metadata_observation_provider_field ON metadata_observations(delivery_id,field,field_scope) WHERE origin='provider';

CREATE TRIGGER immutable_metadata_observation BEFORE UPDATE ON metadata_observations BEGIN SELECT RAISE(ABORT,'Metadata evidence is immutable'); END;

CREATE TRIGGER retained_metadata_user_history BEFORE DELETE ON metadata_observations WHEN OLD.origin IN ('user','legacy_choice') BEGIN SELECT RAISE(ABORT,'Metadata choice history is retained'); END;

CREATE TRIGGER owned_metadata_observation_delivery BEFORE INSERT ON metadata_observations WHEN (NEW.origin NOT LIKE 'legacy_%' AND NEW.delivery_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.input_entry_id=NEW.entry_id AND d.input_recording_id=NEW.recording_id AND d.input_video_id IS NEW.input_video_id)) OR (NEW.origin LIKE 'legacy_%' AND NOT EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.legacy_owner=NEW.legacy_owner AND r.legacy_id=NEW.legacy_id AND r.delivery_id=NEW.delivery_id AND r.entry_id IS NEW.entry_id AND r.recording_id IS NEW.recording_id AND r.input_video_id IS NEW.input_video_id)) BEGIN SELECT RAISE(ABORT,'Metadata evidence has a different captured input'); END;

CREATE TRIGGER current_metadata_decision_subject BEFORE INSERT ON metadata_observations WHEN NEW.origin IN ('user','selection_snapshot','selection_transfer') AND NEW.delivery_id IS NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id AND e.video_id IS NEW.input_video_id) BEGIN SELECT RAISE(ABORT,'Metadata decision input changed before capture'); END;

CREATE TRIGGER owned_metadata_selection_transfer BEFORE INSERT ON metadata_observations WHEN NEW.origin='selection_transfer' AND NOT EXISTS(SELECT 1 FROM metadata_observations o LEFT JOIN metadata_deliveries d ON d.id=o.delivery_id WHERE o.id=NEW.derived_from_observation_id AND NEW.field_scope='recording' AND o.field_scope IN ('recording','legacy_recording') AND o.field=NEW.field AND o.field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental') AND o.origin NOT IN ('user','legacy_choice') AND o.value_kind=NEW.value_kind AND o.text_value IS NEW.text_value AND o.number_value IS NEW.number_value AND o.genre_key IS NEW.genre_key AND o.unit IS NEW.unit AND o.resolution_reason IS NEW.resolution_reason AND COALESCE(d.provider,o.legacy_source) IS NEW.legacy_source) BEGIN SELECT RAISE(ABORT,'Transferred metadata differs from its retained evidence'); END;

CREATE TABLE playback_feedback_receipts (
    capture_id TEXT PRIMARY KEY NOT NULL,
    account_id INTEGER NOT NULL REFERENCES accounts(id),
    kind TEXT NOT NULL CHECK(kind IN ('rating','player','live')),
    observed_at REAL NOT NULL CHECK(typeof(observed_at) IN ('integer','real') AND
                                  observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308),
    result INTEGER NOT NULL CHECK(typeof(result)='integer' AND result IN (0,1))
);

CREATE TABLE model_selection_schedule (
    id INTEGER PRIMARY KEY CHECK(id=1),
    next_at REAL NOT NULL CHECK(typeof(next_at) IN ('integer','real') AND next_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308),
    updated_at REAL NOT NULL CHECK(typeof(updated_at) IN ('integer','real') AND updated_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)
);

CREATE TABLE tv_preparation_state (
    id INTEGER PRIMARY KEY CHECK(id=1),
    failed INTEGER NOT NULL CHECK(typeof(failed)='integer' AND failed IN (0,1)),
    observed_at REAL CHECK(observed_at IS NULL OR (typeof(observed_at) IN ('integer','real') AND observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),
    updated_at REAL NOT NULL CHECK(typeof(updated_at) IN ('integer','real') AND updated_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)
);

CREATE TRIGGER retired_recommendation_work_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface IN ('daily_model_schedule','tv_preparation')
BEGIN SELECT RAISE(ABORT,'Recommendation work has a typed owner'); END;

CREATE TRIGGER retired_recommendation_work_update BEFORE UPDATE ON rec_proposals
WHEN NEW.surface IN ('daily_model_schedule','tv_preparation')
BEGIN SELECT RAISE(ABORT,'Recommendation work has a typed owner'); END;

CREATE TABLE home_offer_dedup (
    id INTEGER PRIMARY KEY CHECK(id=1),
    epoch INTEGER NOT NULL CHECK(typeof(epoch)='integer' AND epoch>=0),
    built_at REAL NOT NULL CHECK(typeof(built_at) IN ('integer','real') AND built_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)
);

CREATE TABLE home_offer_signatures (
    owner_id INTEGER NOT NULL REFERENCES home_offer_dedup(id) CHECK(owner_id=1),
    signature TEXT NOT NULL CHECK(typeof(signature)='text' AND length(CAST(signature AS BLOB)) BETWEEN 1 AND 1024),
    PRIMARY KEY(owner_id,signature)
) WITHOUT ROWID;

CREATE TRIGGER home_offer_signature_budget BEFORE INSERT ON home_offer_signatures
WHEN (SELECT count(*) FROM home_offer_signatures WHERE owner_id=NEW.owner_id)>=100
AND NOT EXISTS(SELECT 1 FROM home_offer_signatures WHERE owner_id=NEW.owner_id AND signature=NEW.signature)
BEGIN SELECT RAISE(ABORT,'Home offer deduplication exceeds its window budget'); END;

CREATE TRIGGER retired_home_offer_insert BEFORE INSERT ON rec_proposals WHEN NEW.surface='home_shown'
BEGIN SELECT RAISE(ABORT,'Home offer deduplication has a typed owner'); END;

CREATE TRIGGER retired_home_offer_update BEFORE UPDATE ON rec_proposals WHEN NEW.surface='home_shown'
BEGIN SELECT RAISE(ABORT,'Home offer deduplication has a typed owner'); END;

CREATE TABLE album_note_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT CHECK(id>=1),
    browse_id TEXT NOT NULL UNIQUE CHECK(typeof(browse_id)='text' AND length(browse_id)>0),
    provider TEXT NOT NULL DEFAULT 'youtube' CHECK(provider='youtube'),
    album_provider_id TEXT,
    unresolved_reason TEXT,
    artist TEXT NOT NULL CHECK(typeof(artist)='text' AND length(artist)>0),
    title TEXT NOT NULL CHECK(typeof(title)='text' AND length(title)>0),
    year_text TEXT,
    year_number INTEGER CHECK(year_number IS NULL OR typeof(year_number)='integer'),
    thumbnail TEXT,
    requested_until REAL CHECK(requested_until IS NULL OR (typeof(requested_until) IN ('real','integer') AND abs(requested_until)<=1.7976931348623157e308)),
    revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1),
    requested_at REAL CHECK(requested_at IS NULL OR (typeof(requested_at) IN ('real','integer') AND abs(requested_at)<=1.7976931348623157e308)),
    updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('real','integer') AND abs(updated_at)<=1.7976931348623157e308)),
    FOREIGN KEY(provider,album_provider_id) REFERENCES album_provider_ids(provider,provider_id),
    CHECK((album_provider_id IS NOT NULL AND album_provider_id=browse_id AND unresolved_reason IS NULL) OR
          (album_provider_id IS NULL AND unresolved_reason IS NOT NULL AND unresolved_reason='provider_album_not_admitted')),
    CHECK(year_text IS NULL OR year_number IS NULL)
);

CREATE TRIGGER album_note_request_budget BEFORE INSERT ON album_note_requests
WHEN (SELECT count(*) FROM album_note_requests)>=24
BEGIN SELECT RAISE(ABORT,'Album note demand exceeds its queue budget'); END;

CREATE TRIGGER album_note_request_identity BEFORE UPDATE OF id,browse_id,provider,requested_at ON album_note_requests
WHEN NEW.id<>OLD.id OR NEW.browse_id<>OLD.browse_id OR NEW.provider<>OLD.provider OR NEW.requested_at IS NOT OLD.requested_at
BEGIN SELECT RAISE(ABORT,'Album note request identity is immutable'); END;

CREATE TRIGGER album_note_request_revision BEFORE UPDATE ON album_note_requests
WHEN NEW.revision<=OLD.revision
BEGIN SELECT RAISE(ABORT,'Album note request revision must advance'); END;

CREATE TRIGGER retired_album_note_request_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface='album_note_requests'
BEGIN SELECT RAISE(ABORT,'Album note demand has a typed owner'); END;

CREATE TRIGGER retired_album_note_request_update BEFORE UPDATE OF surface,payload ON rec_proposals
WHEN NEW.surface='album_note_requests'
BEGIN SELECT RAISE(ABORT,'Album note demand has a typed owner'); END;

CREATE TABLE album_note_outputs (
    id INTEGER PRIMARY KEY AUTOINCREMENT CHECK(id>=1),
    browse_id TEXT NOT NULL UNIQUE CHECK(typeof(browse_id)='text' AND length(browse_id)>0),
    provider TEXT NOT NULL DEFAULT 'youtube' CHECK(provider='youtube'),
    album_provider_id TEXT,
    unresolved_reason TEXT,
    filename TEXT NOT NULL CHECK(typeof(filename)='text' AND length(filename)>0),
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),
    byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 1048576),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('real','integer') AND abs(built_at)<=1.7976931348623157e308)),
    FOREIGN KEY(provider,album_provider_id) REFERENCES album_provider_ids(provider,provider_id),
    CHECK((album_provider_id IS NOT NULL AND album_provider_id=browse_id AND unresolved_reason IS NULL) OR
          (album_provider_id IS NULL AND unresolved_reason IS NOT NULL AND unresolved_reason='provider_album_not_admitted'))
);

CREATE TRIGGER album_note_output_budget BEFORE INSERT ON album_note_outputs
WHEN (SELECT count(*) FROM album_note_outputs)>=128
BEGIN SELECT RAISE(ABORT,'Album note output exceeds its cache budget'); END;

CREATE TRIGGER album_note_output_immutable BEFORE UPDATE ON album_note_outputs
WHEN NEW.id<>OLD.id OR NEW.browse_id<>OLD.browse_id OR NEW.provider<>OLD.provider
  OR NEW.album_provider_id IS NOT OLD.album_provider_id OR NEW.unresolved_reason IS NOT OLD.unresolved_reason
  OR NEW.content_digest<>OLD.content_digest OR NEW.byte_size<>OLD.byte_size OR NEW.built_at IS NOT OLD.built_at
BEGIN SELECT RAISE(ABORT,'Replace album note output instead of mutating it'); END;

CREATE TRIGGER retired_album_note_output_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface='album_notes'
BEGIN SELECT RAISE(ABORT,'Album notes have a file owner'); END;

CREATE TRIGGER retired_album_note_output_update BEFORE UPDATE OF surface,payload ON rec_proposals
WHEN NEW.surface='album_notes'
BEGIN SELECT RAISE(ABORT,'Album notes have a file owner'); END;

CREATE TABLE genre_preferences (
    genre_key TEXT PRIMARY KEY NOT NULL REFERENCES genre_catalog(key),
    enabled INTEGER NOT NULL CHECK(typeof(enabled)='integer' AND enabled IN (0,1)),
    origin TEXT NOT NULL CHECK(origin IN ('default','custom','user','legacy'))
) WITHOUT ROWID;

CREATE INDEX ix_genre_preference_enabled ON genre_preferences(enabled,genre_key);

CREATE TABLE genre_redirects (
 retired_key TEXT PRIMARY KEY NOT NULL REFERENCES genre_catalog(key),
 genre_key TEXT NOT NULL REFERENCES genre_catalog(key),
 CHECK(retired_key<>genre_key)
) WITHOUT ROWID;

CREATE TRIGGER genre_redirect_current_insert BEFORE INSERT ON genre_redirects
WHEN EXISTS(SELECT 1 FROM genre_redirects WHERE retired_key=NEW.genre_key OR genre_key=NEW.retired_key)
BEGIN SELECT RAISE(ABORT,'Genre redirects must point directly to a current identity'); END;

CREATE TRIGGER genre_redirect_current_update BEFORE UPDATE ON genre_redirects
WHEN NEW.retired_key<>OLD.retired_key OR EXISTS(SELECT 1 FROM genre_redirects WHERE retired_key=NEW.genre_key)
BEGIN SELECT RAISE(ABORT,'Genre redirects must point directly to a current identity'); END;

CREATE TRIGGER genre_redirect_retained BEFORE DELETE ON genre_redirects
BEGIN SELECT RAISE(ABORT,'Genre merge lineage is retained'); END;

CREATE INDEX ix_genre_catalog_name ON genre_catalog(name COLLATE NOCASE);

CREATE INDEX ix_genre_alias_label ON genre_alias(label COLLATE NOCASE);

CREATE INDEX ix_genre_alias_owner ON genre_alias(genre_key);

CREATE TABLE genre_merge_preferences (
 id INTEGER PRIMARY KEY,
 retired_key TEXT NOT NULL REFERENCES genre_catalog(key),
 genre_key TEXT NOT NULL REFERENCES genre_catalog(key),
 enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),
 origin TEXT NOT NULL,
 merged_at REAL NOT NULL
);

CREATE INDEX ix_recordings_genre ON recordings(genre_key);

CREATE INDEX ix_albums_genre ON albums(genre_key);

CREATE INDEX ix_discovered_artists_genre ON discovered_artists(genre_key);

CREATE TABLE genre_classification_legacy (
    id INTEGER PRIMARY KEY,
    recording_id INTEGER REFERENCES recordings(id),
    album_id INTEGER REFERENCES albums(id),
    artist_id INTEGER REFERENCES artists(id),
    raw_label TEXT NOT NULL,
    genre_key TEXT REFERENCES genre_catalog(key),
    resolution_reason TEXT CHECK(resolution_reason IN ('unknown_genre','ambiguous_genre')),
    CHECK((recording_id IS NOT NULL)+(album_id IS NOT NULL)+(artist_id IS NOT NULL)=1),
    CHECK((genre_key IS NOT NULL AND resolution_reason IS NULL)
        OR (genre_key IS NULL AND resolution_reason IS NOT NULL) OR raw_label='')
);

CREATE UNIQUE INDEX ix_legacy_genre_recording_id ON genre_classification_legacy(recording_id) WHERE recording_id IS NOT NULL;

CREATE UNIQUE INDEX ix_legacy_genre_album_id ON genre_classification_legacy(album_id) WHERE album_id IS NOT NULL;

CREATE UNIQUE INDEX ix_legacy_genre_artist_id ON genre_classification_legacy(artist_id) WHERE artist_id IS NOT NULL;

CREATE TRIGGER immutable_genre_classification_legacy BEFORE UPDATE ON genre_classification_legacy BEGIN SELECT RAISE(ABORT,'Captured genre labels are immutable'); END;

ALTER TABLE album_note_requests ADD COLUMN work_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(work_revision)='integer' AND work_revision>=1);

CREATE TRIGGER album_note_request_work_revision BEFORE UPDATE ON album_note_requests
WHEN NEW.work_revision<OLD.work_revision OR
  ((NEW.artist IS NOT OLD.artist OR NEW.title IS NOT OLD.title OR NEW.year_text IS NOT OLD.year_text
    OR NEW.year_number IS NOT OLD.year_number OR NEW.thumbnail IS NOT OLD.thumbnail
    OR NEW.album_provider_id IS NOT OLD.album_provider_id)
   AND NEW.work_revision<=OLD.work_revision)
BEGIN SELECT RAISE(ABORT,'Changed album note inputs require a newer work revision'); END;

CREATE TABLE listening_choice_windows (
    format TEXT PRIMARY KEY NOT NULL CHECK(format IN ('albums','mixes','radio')),
    opportunity_key TEXT NOT NULL CHECK(typeof(opportunity_key)='text' AND length(CAST(opportunity_key AS BLOB)) BETWEEN 1 AND 64),
    window_text TEXT NOT NULL CHECK(typeof(window_text)='text' AND length(CAST(window_text AS BLOB))<=1024),
    updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308))
) WITHOUT ROWID;

CREATE TABLE album_menu_refresh_state (
    id INTEGER PRIMARY KEY CHECK(id=1),
    epoch INTEGER CHECK(epoch IS NULL OR (typeof(epoch)='integer' AND epoch>=0)),
    updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308))
);

CREATE TABLE album_menu_refresh_exclusions (
    request_id INTEGER NOT NULL DEFAULT 1 REFERENCES album_menu_refresh_state(id),
    position INTEGER PRIMARY KEY CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 99),
    browse_id TEXT NOT NULL CHECK(typeof(browse_id)='text' AND length(browse_id)>0),
    provider TEXT NOT NULL CHECK(provider='youtube'),
    album_provider_id TEXT,
    unresolved_reason TEXT,
    FOREIGN KEY(provider,album_provider_id) REFERENCES album_provider_ids(provider,provider_id),
    CHECK((album_provider_id IS NOT NULL AND album_provider_id=browse_id AND unresolved_reason IS NULL) OR
          (album_provider_id IS NULL AND unresolved_reason IS NOT NULL AND unresolved_reason='provider_album_not_admitted'))
);

CREATE TABLE home_genre_requests (
    id INTEGER PRIMARY KEY CHECK(id=1),
    epoch INTEGER CHECK(epoch IS NULL OR (typeof(epoch)='integer' AND epoch>=0)),
    has_includes INTEGER NOT NULL CHECK(typeof(has_includes)='integer' AND has_includes IN (0,1)),
    has_avoids INTEGER NOT NULL CHECK(typeof(has_avoids)='integer' AND has_avoids IN (0,1)),
    held_by_vibe INTEGER CHECK(held_by_vibe IS NULL OR (typeof(held_by_vibe)='integer' AND held_by_vibe IN (0,1))),
    suspended_by_vibe INTEGER CHECK(suspended_by_vibe IS NULL OR (typeof(suspended_by_vibe)='integer' AND suspended_by_vibe IN (0,1))),
    updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)),
    CHECK(epoch IS NOT NULL OR (has_includes=0 AND has_avoids=0 AND held_by_vibe IS NULL AND suspended_by_vibe IS NULL))
);

CREATE TABLE home_genre_request_items (
    request_id INTEGER NOT NULL DEFAULT 1 REFERENCES home_genre_requests(id),
    kind TEXT NOT NULL CHECK(kind IN ('include','avoid')),
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 99),
    raw_key TEXT NOT NULL CHECK(typeof(raw_key)='text' AND length(raw_key)>0),
    family_key TEXT REFERENCES genre_family(key),
    genre_key TEXT REFERENCES genre_catalog(key),
    resolution_reason TEXT CHECK(resolution_reason IN ('ambiguous_genre','unknown_genre')),
    PRIMARY KEY(kind,position),
    CHECK((family_key IS NOT NULL AND genre_key IS NULL AND resolution_reason IS NULL) OR
          (family_key IS NULL AND genre_key IS NOT NULL AND resolution_reason IS NULL) OR
          (family_key IS NULL AND genre_key IS NULL AND resolution_reason IS NOT NULL))
) WITHOUT ROWID;

CREATE TRIGGER album_menu_exclusion_owner BEFORE INSERT ON album_menu_refresh_exclusions
WHEN NOT EXISTS(SELECT 1 FROM album_menu_refresh_state WHERE id=NEW.request_id AND epoch IS NOT NULL)
BEGIN SELECT RAISE(ABORT,'Album exclusion requires an active refresh request'); END;

CREATE TRIGGER home_genre_request_item_owner BEFORE INSERT ON home_genre_request_items
WHEN NOT EXISTS(SELECT 1 FROM home_genre_requests WHERE id=NEW.request_id AND
               ((NEW.kind='include' AND has_includes=1) OR (NEW.kind='avoid' AND has_avoids=1)))
BEGIN SELECT RAISE(ABORT,'Genre demand item requires its enabled request list'); END;

CREATE TRIGGER home_genre_request_item_update_owner BEFORE UPDATE OF request_id,kind ON home_genre_request_items
WHEN NOT EXISTS(SELECT 1 FROM home_genre_requests WHERE id=NEW.request_id AND
               ((NEW.kind='include' AND has_includes=1) OR (NEW.kind='avoid' AND has_avoids=1)))
BEGIN SELECT RAISE(ABORT,'Genre demand item requires its enabled request list'); END;

CREATE TRIGGER home_genre_request_list_owner BEFORE UPDATE OF has_includes,has_avoids ON home_genre_requests
WHEN EXISTS(SELECT 1 FROM home_genre_request_items WHERE request_id=OLD.id AND
            ((kind='include' AND NEW.has_includes=0) OR (kind='avoid' AND NEW.has_avoids=0)))
BEGIN SELECT RAISE(ABORT,'Retire genre demand items before disabling their list'); END;

CREATE TRIGGER retired_recommendation_request_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface IN ('album_menu_refresh','home_genre_request','choice_window:albums','choice_window:mixes','choice_window:radio')
BEGIN SELECT RAISE(ABORT,'Recommendation demand has typed owners'); END;

CREATE TRIGGER retired_recommendation_request_update BEFORE UPDATE OF surface,payload ON rec_proposals
WHEN NEW.surface IN ('album_menu_refresh','home_genre_request','choice_window:albums','choice_window:mixes','choice_window:radio')
BEGIN SELECT RAISE(ABORT,'Recommendation demand has typed owners'); END;

CREATE TABLE taste_axes (
 id INTEGER PRIMARY KEY,
 kind TEXT NOT NULL CHECK(kind IN ('genre','family','other','unresolved_genre')),
 genre_key TEXT REFERENCES genre_catalog(key),
 family_key TEXT REFERENCES genre_family(key),
 value TEXT,
 resolution_reason TEXT CHECK(resolution_reason IN ('unknown_genre','ambiguous_genre')),
 CHECK((kind='genre' AND genre_key IS NOT NULL AND family_key IS NULL AND value IS NULL AND resolution_reason IS NULL)
    OR (kind='family' AND family_key IS NOT NULL AND genre_key IS NULL AND value IS NULL AND resolution_reason IS NULL)
    OR (kind='other' AND genre_key IS NULL AND family_key IS NULL AND value IS NOT NULL AND length(value)>0 AND value NOT LIKE 'genre:%' AND value NOT LIKE 'family:%' AND resolution_reason IS NULL)
    OR (kind='unresolved_genre' AND genre_key IS NULL AND family_key IS NULL AND value IS NOT NULL AND resolution_reason IS NOT NULL))
);

CREATE UNIQUE INDEX ix_taste_axis_genre ON taste_axes(genre_key) WHERE kind='genre';

CREATE UNIQUE INDEX ix_taste_axis_family ON taste_axes(family_key) WHERE kind='family';

CREATE UNIQUE INDEX ix_taste_axis_value ON taste_axes(kind,value) WHERE value IS NOT NULL;

CREATE TABLE taste_axis_legacy (
 table_name TEXT NOT NULL,
 row_key TEXT NOT NULL,
 raw_axis TEXT NOT NULL,
 axis_id INTEGER NOT NULL REFERENCES taste_axes(id),
 weight REAL,
 lean_value REAL,
 score REAL,
 updated_at REAL,
 last_graduated_day TEXT,
 source TEXT,
 factor REAL,
 new_weight REAL,
 created_at REAL,
 PRIMARY KEY(table_name,row_key)
) WITHOUT ROWID;

CREATE TABLE recipe_artists (
 recipe_id INTEGER NOT NULL REFERENCES road_trip_recipes(id) ON DELETE CASCADE,
 artist_id INTEGER NOT NULL REFERENCES artists(id),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 PRIMARY KEY(recipe_id,artist_id), UNIQUE(recipe_id,position)
) WITHOUT ROWID;

CREATE INDEX ix_recipe_artist ON recipe_artists(artist_id,recipe_id);

CREATE TABLE recipe_genres (
 recipe_id INTEGER NOT NULL REFERENCES road_trip_recipes(id) ON DELETE CASCADE,
 genre_key TEXT NOT NULL REFERENCES genre_catalog(key),
 role TEXT NOT NULL CHECK(role IN ('include','exclude')),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 PRIMARY KEY(recipe_id,genre_key,role), UNIQUE(recipe_id,role,position)
) WITHOUT ROWID;

CREATE INDEX ix_recipe_genre ON recipe_genres(genre_key,recipe_id);

CREATE TABLE recipe_unresolved_artists (
 recipe_id INTEGER NOT NULL REFERENCES road_trip_recipes(id) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 raw_label TEXT NOT NULL,
 reason TEXT NOT NULL CHECK(reason='unknown_or_ambiguous_artist'),
 PRIMARY KEY(recipe_id,position)
) WITHOUT ROWID;

CREATE TABLE recipe_unresolved_genres (
 recipe_id INTEGER NOT NULL REFERENCES road_trip_recipes(id) ON DELETE CASCADE,
 role TEXT NOT NULL CHECK(role IN ('include','exclude')),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 raw_label TEXT NOT NULL,
 reason TEXT NOT NULL CHECK(reason IN ('unknown_genre','ambiguous_genre')),
 PRIMARY KEY(recipe_id,role,position)
) WITHOUT ROWID;

CREATE TRIGGER recipe_artist_position BEFORE INSERT ON recipe_artists
WHEN EXISTS(SELECT 1 FROM recipe_unresolved_artists WHERE recipe_id=NEW.recipe_id AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains an unresolved artist'); END;

CREATE TRIGGER recipe_unresolved_artist_position BEFORE INSERT ON recipe_unresolved_artists
WHEN EXISTS(SELECT 1 FROM recipe_artists WHERE recipe_id=NEW.recipe_id AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains an artist'); END;

CREATE TRIGGER recipe_genre_position BEFORE INSERT ON recipe_genres
WHEN EXISTS(SELECT 1 FROM recipe_unresolved_genres WHERE recipe_id=NEW.recipe_id AND role=NEW.role AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains an unresolved genre'); END;

CREATE TRIGGER recipe_unresolved_genre_position BEFORE INSERT ON recipe_unresolved_genres
WHEN EXISTS(SELECT 1 FROM recipe_genres WHERE recipe_id=NEW.recipe_id AND role=NEW.role AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains a genre'); END;

CREATE TRIGGER recipe_artist_position_update BEFORE UPDATE ON recipe_artists
WHEN EXISTS(SELECT 1 FROM recipe_unresolved_artists WHERE recipe_id=NEW.recipe_id AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains an unresolved artist'); END;

CREATE TRIGGER recipe_unresolved_artist_position_update BEFORE UPDATE ON recipe_unresolved_artists
WHEN EXISTS(SELECT 1 FROM recipe_artists WHERE recipe_id=NEW.recipe_id AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains an artist'); END;

CREATE TRIGGER recipe_genre_position_update BEFORE UPDATE ON recipe_genres
WHEN EXISTS(SELECT 1 FROM recipe_unresolved_genres WHERE recipe_id=NEW.recipe_id AND role=NEW.role AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains an unresolved genre'); END;

CREATE TRIGGER recipe_unresolved_genre_position_update BEFORE UPDATE ON recipe_unresolved_genres
WHEN EXISTS(SELECT 1 FROM recipe_genres WHERE recipe_id=NEW.recipe_id AND role=NEW.role AND position=NEW.position)
BEGIN SELECT RAISE(ABORT,'Recipe position already contains a genre'); END;

CREATE TABLE listening_output_publications (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    status TEXT NOT NULL DEFAULT 'building' CHECK(status IN ('building','published','retiring')),
    schema_version INTEGER CHECK(schema_version IS NULL OR (typeof(schema_version)='integer' AND schema_version>0)),
    generation_key TEXT CHECK(generation_key IS NULL OR (length(generation_key)=24 AND generation_key NOT GLOB '*[^0-9a-f]*')),
    timezone TEXT CHECK(timezone IS NULL OR length(CAST(timezone AS BLOB)) BETWEEN 1 AND 1024),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    input_revision INTEGER CHECK(input_revision IS NULL OR (typeof(input_revision)='integer' AND input_revision>=0)),
    revision_reason TEXT CHECK((input_revision IS NULL AND revision_reason IS NOT NULL AND revision_reason='legacy_not_recorded') OR (input_revision IS NOT NULL AND revision_reason IS NULL)),
    output_count INTEGER NOT NULL CHECK(typeof(output_count)='integer' AND output_count BETWEEN 0 AND 4098),
    chunk_count INTEGER NOT NULL CHECK(typeof(chunk_count)='integer' AND chunk_count BETWEEN 0 AND 4096)
);

CREATE TABLE listening_output_files (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    publication_id INTEGER NOT NULL REFERENCES listening_output_publications(id),
    surface TEXT NOT NULL CHECK(surface IN ('listening_analytics','listening_edition','listening_chunk')),
    chunk_key TEXT NOT NULL CHECK((surface='listening_chunk' AND length(chunk_key)=24 AND chunk_key NOT GLOB '*[^0-9a-f]*') OR (surface<>'listening_chunk' AND chunk_key='')),
    filename TEXT NOT NULL CHECK(length(filename)>0),
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),
    byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 1048576),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    UNIQUE(publication_id,surface,chunk_key)
);

CREATE TABLE listening_output_chunks (
    publication_id INTEGER NOT NULL,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 4095),
    surface TEXT NOT NULL DEFAULT 'listening_chunk' CHECK(surface='listening_chunk'),
    chunk_key TEXT NOT NULL,
    from_day TEXT NOT NULL CHECK(length(from_day)=10 AND date(from_day) IS NOT NULL AND date(from_day)=from_day),
    until_day TEXT NOT NULL CHECK(length(until_day)=10 AND date(until_day) IS NOT NULL AND date(until_day)=until_day AND from_day<=until_day),
    encoded_bytes INTEGER NOT NULL CHECK(typeof(encoded_bytes)='integer' AND encoded_bytes BETWEEN 1 AND 1048576),
    PRIMARY KEY(publication_id,position),
    UNIQUE(publication_id,chunk_key),
    FOREIGN KEY(publication_id,surface,chunk_key) REFERENCES listening_output_files(publication_id,surface,chunk_key)
) WITHOUT ROWID;

CREATE TABLE listening_output_heads (
    slot TEXT PRIMARY KEY NOT NULL CHECK(slot IN ('current','previous')),
    publication_id INTEGER NOT NULL UNIQUE REFERENCES listening_output_publications(id)
) WITHOUT ROWID;

CREATE TRIGGER listening_output_new BEFORE INSERT ON listening_output_publications
WHEN NEW.status<>'building' BEGIN SELECT RAISE(ABORT,'Listening publication starts privately'); END;

CREATE TRIGGER listening_output_identity BEFORE UPDATE OF id,schema_version,generation_key,timezone,built_at,input_revision,revision_reason,output_count,chunk_count ON listening_output_publications
BEGIN SELECT RAISE(ABORT,'Listening publication inputs are immutable'); END;

CREATE TRIGGER listening_output_transition BEFORE UPDATE OF status ON listening_output_publications
WHEN NOT ((OLD.status='building' AND NEW.status='published' AND NEW.output_count=(SELECT count(*) FROM listening_output_files WHERE publication_id=OLD.id)
    AND NEW.chunk_count=(SELECT count(*) FROM listening_output_chunks WHERE publication_id=OLD.id)
    AND (NEW.chunk_count=0 OR ((SELECT min(position) FROM listening_output_chunks WHERE publication_id=OLD.id)=0 AND (SELECT max(position) FROM listening_output_chunks WHERE publication_id=OLD.id)=NEW.chunk_count-1)))
    OR (OLD.status='published' AND NEW.status='retiring' AND NOT EXISTS(SELECT 1 FROM listening_output_heads WHERE publication_id=OLD.id)))
BEGIN SELECT RAISE(ABORT,'Listening publication is incomplete or retained'); END;

CREATE TRIGGER listening_output_retained BEFORE DELETE ON listening_output_publications
WHEN OLD.status<>'retiring' BEGIN SELECT RAISE(ABORT,'Listening publication must retire first'); END;

CREATE TRIGGER listening_output_head_insert BEFORE INSERT ON listening_output_heads
WHEN NOT EXISTS(SELECT 1 FROM listening_output_publications WHERE id=NEW.publication_id AND status='published')
BEGIN SELECT RAISE(ABORT,'Listening head requires published output'); END;

CREATE TRIGGER listening_output_head_update BEFORE UPDATE ON listening_output_heads
WHEN NOT EXISTS(SELECT 1 FROM listening_output_publications WHERE id=NEW.publication_id AND status='published')
BEGIN SELECT RAISE(ABORT,'Listening head requires published output'); END;

CREATE TRIGGER listening_output_file_insert BEFORE INSERT ON listening_output_files
WHEN NOT EXISTS(SELECT 1 FROM listening_output_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Listening output is sealed'); END;

CREATE TRIGGER listening_output_file_update BEFORE UPDATE ON listening_output_files
WHEN NEW.id IS NOT OLD.id OR NEW.publication_id IS NOT OLD.publication_id OR NEW.surface IS NOT OLD.surface OR NEW.chunk_key IS NOT OLD.chunk_key OR NEW.content_digest IS NOT OLD.content_digest OR NEW.byte_size IS NOT OLD.byte_size OR NEW.built_at IS NOT OLD.built_at
BEGIN SELECT RAISE(ABORT,'Listening output is immutable'); END;

CREATE TRIGGER listening_output_file_delete BEFORE DELETE ON listening_output_files
WHEN NOT EXISTS(SELECT 1 FROM listening_output_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Listening output is retained'); END;

CREATE TRIGGER listening_output_chunk_insert BEFORE INSERT ON listening_output_chunks
WHEN NOT EXISTS(SELECT 1 FROM listening_output_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Listening chunk index is sealed'); END;

CREATE TRIGGER listening_output_chunk_update BEFORE UPDATE ON listening_output_chunks
BEGIN SELECT RAISE(ABORT,'Listening chunk index is immutable'); END;

CREATE TRIGGER listening_output_chunk_delete BEFORE DELETE ON listening_output_chunks
WHEN NOT EXISTS(SELECT 1 FROM listening_output_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Listening chunk index is retained'); END;

CREATE TRIGGER retired_listening_output_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface IN ('listening_analytics','listening_edition') OR substr(NEW.surface,1,16)='listening_chunk:'
BEGIN SELECT RAISE(ABORT,'Listening output has a publication owner'); END;

CREATE TRIGGER retired_listening_output_update BEFORE UPDATE ON rec_proposals
WHEN NEW.surface IN ('listening_analytics','listening_edition') OR substr(NEW.surface,1,16)='listening_chunk:'
BEGIN SELECT RAISE(ABORT,'Listening output has a publication owner'); END;

CREATE TABLE home_display_publications (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    surface TEXT NOT NULL CHECK(surface IN ('home_prepared','home_tuned','home_choice','album_prepared','adaptive_group_preview','home_discovery','home_revisit','into_recently','trend_rollups','cleanup')),
    status TEXT NOT NULL DEFAULT 'building' CHECK(status IN ('building','published','retiring')),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    schema_version INTEGER CHECK(schema_version IS NULL OR (typeof(schema_version)='integer' AND schema_version>=0)),
    generation_key TEXT CHECK(generation_key IS NULL OR length(CAST(generation_key AS BLOB)) BETWEEN 1 AND 1024),
    mix_regions INTEGER NOT NULL CHECK(typeof(mix_regions)='integer' AND mix_regions>=0),
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),
    total_bytes INTEGER NOT NULL CHECK(typeof(total_bytes)='integer' AND total_bytes BETWEEN 1 AND 8388608),
    part_count INTEGER NOT NULL CHECK(typeof(part_count)='integer' AND part_count BETWEEN 1 AND 128),
    has_content INTEGER NOT NULL CHECK(typeof(has_content)='integer' AND has_content IN (0,1)),
    input_revision INTEGER CHECK(input_revision IS NULL OR (typeof(input_revision)='integer' AND input_revision>=0)),
    revision_reason TEXT CHECK((input_revision IS NULL AND revision_reason IS NOT NULL AND revision_reason IN ('legacy_not_recorded','publisher_not_recorded')) OR (input_revision IS NOT NULL AND revision_reason IS NULL)),
    UNIQUE(id,surface)
);

CREATE TABLE home_display_heads (
    surface TEXT PRIMARY KEY NOT NULL,
    publication_id INTEGER NOT NULL UNIQUE,
    FOREIGN KEY(publication_id,surface) REFERENCES home_display_publications(id,surface)
) WITHOUT ROWID;

CREATE TABLE home_display_files (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    publication_id INTEGER NOT NULL,
    surface TEXT NOT NULL,
    chunk_key TEXT NOT NULL CHECK(chunk_key=CAST(CAST(chunk_key AS INTEGER) AS TEXT) AND CAST(chunk_key AS INTEGER) BETWEEN 0 AND 127),
    filename TEXT NOT NULL CHECK(length(filename)>0),
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),
    byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 1048576),
    UNIQUE(publication_id,chunk_key),
    FOREIGN KEY(publication_id,surface) REFERENCES home_display_publications(id,surface)
);

CREATE TABLE home_display_policies (
    publication_id INTEGER NOT NULL REFERENCES home_display_publications(id),
    raw_key TEXT NOT NULL CHECK(length(raw_key)>0),
    policy_version TEXT REFERENCES recommendation_policies(version),
    resolution_reason TEXT,
    CHECK((policy_version IS NOT NULL AND policy_version=raw_key AND resolution_reason IS NULL) OR (policy_version IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_policy')),
    PRIMARY KEY(publication_id,raw_key)
) WITHOUT ROWID;

CREATE INDEX ix_home_display_policy ON home_display_policies(policy_version,publication_id) WHERE policy_version IS NOT NULL;

CREATE TABLE home_display_group_roots (
    publication_id INTEGER NOT NULL REFERENCES home_display_publications(id),
    field TEXT NOT NULL CHECK(field IN ('context','choice_context','album_choice_context')),
    kind TEXT NOT NULL CHECK(kind='prepared'),
    external_key TEXT NOT NULL CHECK(external_key='home-output:'||publication_id||':'||field),
    PRIMARY KEY(publication_id,field),
    FOREIGN KEY(kind,external_key) REFERENCES group_evidence_owners(kind,external_key)
) WITHOUT ROWID;

CREATE TABLE home_display_recommendation_roots (
    publication_id INTEGER NOT NULL REFERENCES home_display_publications(id),
    field TEXT NOT NULL CHECK(field IN ('context','choice_context','album_choice_context','recommendations')),
    kind TEXT NOT NULL CHECK(kind='prepared'),
    external_key TEXT NOT NULL CHECK(external_key='home-output:'||publication_id||':'||field),
    generation_id INTEGER NOT NULL,
    PRIMARY KEY(publication_id,field,generation_id),
    FOREIGN KEY(kind,external_key,generation_id) REFERENCES recommendation_generation_refs(kind,external_key,generation_id)
) WITHOUT ROWID;

CREATE TRIGGER home_display_new BEFORE INSERT ON home_display_publications
WHEN NEW.status<>'building' BEGIN SELECT RAISE(ABORT,'Home display starts privately'); END;

CREATE TRIGGER home_display_identity BEFORE UPDATE OF id,surface,built_at,schema_version,generation_key,mix_regions,content_digest,total_bytes,part_count,input_revision,revision_reason,has_content ON home_display_publications
BEGIN SELECT RAISE(ABORT,'Home display inputs are immutable'); END;

CREATE TRIGGER home_display_transition BEFORE UPDATE OF status ON home_display_publications
WHEN NOT ((OLD.status='building' AND NEW.status='published'
    AND NEW.part_count=(SELECT count(*) FROM home_display_files WHERE publication_id=OLD.id)
    AND (SELECT min(CAST(chunk_key AS INTEGER)) FROM home_display_files WHERE publication_id=OLD.id)=0
    AND (SELECT max(CAST(chunk_key AS INTEGER)) FROM home_display_files WHERE publication_id=OLD.id)=NEW.part_count-1)
    OR (OLD.status='published' AND NEW.status='retiring' AND NOT EXISTS(SELECT 1 FROM home_display_heads WHERE publication_id=OLD.id)))
BEGIN SELECT RAISE(ABORT,'Home display is incomplete or retained'); END;

CREATE TRIGGER home_display_retained BEFORE DELETE ON home_display_publications
WHEN OLD.status<>'retiring' BEGIN SELECT RAISE(ABORT,'Home display must retire first'); END;

CREATE TRIGGER home_display_head_insert BEFORE INSERT ON home_display_heads
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=NEW.publication_id AND status='published')
BEGIN SELECT RAISE(ABORT,'Home head requires published display'); END;

CREATE TRIGGER home_display_head_update BEFORE UPDATE ON home_display_heads
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=NEW.publication_id AND status='published')
BEGIN SELECT RAISE(ABORT,'Home head requires published display'); END;

CREATE TRIGGER home_display_file_insert BEFORE INSERT ON home_display_files
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Home display files are sealed'); END;

CREATE TRIGGER home_display_file_update BEFORE UPDATE ON home_display_files
WHEN NEW.id IS NOT OLD.id OR NEW.publication_id IS NOT OLD.publication_id OR NEW.surface IS NOT OLD.surface OR NEW.chunk_key IS NOT OLD.chunk_key OR NEW.content_digest IS NOT OLD.content_digest OR NEW.byte_size IS NOT OLD.byte_size
BEGIN SELECT RAISE(ABORT,'Home display files are immutable'); END;

CREATE TRIGGER home_display_file_delete BEFORE DELETE ON home_display_files
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Home display files are retained'); END;

CREATE TRIGGER home_display_policy_insert BEFORE INSERT ON home_display_policies
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Home display policy references are sealed'); END;

CREATE TRIGGER home_display_policy_update BEFORE UPDATE ON home_display_policies
BEGIN SELECT RAISE(ABORT,'Home display policy references are immutable'); END;

CREATE TRIGGER home_display_policy_delete BEFORE DELETE ON home_display_policies
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Home display policy references are retained'); END;

CREATE TRIGGER home_display_group_insert BEFORE INSERT ON home_display_group_roots
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Home display group references are sealed'); END;

CREATE TRIGGER home_display_group_update BEFORE UPDATE ON home_display_group_roots
BEGIN SELECT RAISE(ABORT,'Home display group references are immutable'); END;

CREATE TRIGGER home_display_group_delete BEFORE DELETE ON home_display_group_roots
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Home display group references are retained'); END;

CREATE TRIGGER home_display_recommendation_insert BEFORE INSERT ON home_display_recommendation_roots
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Home display generation references are sealed'); END;

CREATE TRIGGER home_display_recommendation_update BEFORE UPDATE ON home_display_recommendation_roots
BEGIN SELECT RAISE(ABORT,'Home display generation references are immutable'); END;

CREATE TRIGGER home_display_recommendation_delete BEFORE DELETE ON home_display_recommendation_roots
WHEN NOT EXISTS(SELECT 1 FROM home_display_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Home display generation references are retained'); END;

CREATE TRIGGER retired_home_display_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface IN ('home_prepared','home_tuned','home_choice','album_prepared','adaptive_group_preview','home_discovery','home_revisit','into_recently','trend_rollups','cleanup')
BEGIN SELECT RAISE(ABORT,'Home display has a publication owner'); END;

CREATE TRIGGER retired_home_display_update BEFORE UPDATE ON rec_proposals
WHEN NEW.surface IN ('home_prepared','home_tuned','home_choice','album_prepared','adaptive_group_preview','home_discovery','home_revisit','into_recently','trend_rollups','cleanup')
BEGIN SELECT RAISE(ABORT,'Home display has a publication owner'); END;

CREATE TABLE choice_learning_publications (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    surface TEXT NOT NULL CHECK(surface IN ('choice_bandit','group_choice_bandit','choice_interests')),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 131071),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    schema_version INTEGER CHECK(schema_version IS NULL OR (typeof(schema_version)='integer' AND schema_version>=0)),
    policy TEXT,
    generation TEXT,
    state_version TEXT,
    at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
    since REAL CHECK(since IS NULL OR (typeof(since) IN ('integer','real') AND abs(since)<=1.7976931348623157e308)),
    expires_at REAL CHECK(expires_at IS NULL OR (typeof(expires_at) IN ('integer','real') AND abs(expires_at)<=1.7976931348623157e308)),
    offered INTEGER CHECK(offered IS NULL OR (typeof(offered)='integer' AND offered>=0)),
    picked INTEGER CHECK(picked IS NULL OR (typeof(picked)='integer' AND picked>=0)),
    watermark TEXT,
    contexts_total INTEGER CHECK(contexts_total IS NULL OR (typeof(contexts_total)='integer' AND contexts_total>=0)),
    interest_version TEXT,
    UNIQUE(id,surface)
);

CREATE TABLE choice_learning_heads (
    surface TEXT PRIMARY KEY NOT NULL,
    publication_id INTEGER NOT NULL UNIQUE,
    FOREIGN KEY(publication_id,surface) REFERENCES choice_learning_publications(id,surface)
) WITHOUT ROWID;

CREATE TABLE choice_learning_parameters (
    publication_id INTEGER NOT NULL REFERENCES choice_learning_publications(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK(name IN ('choice','open','start','completion','promotion','early_exit','window_d','match_threshold')),
    value REAL NOT NULL CHECK(typeof(value) IN ('integer','real') AND abs(value)<=1.7976931348623157e308),
    PRIMARY KEY(publication_id,name)
) WITHOUT ROWID;

CREATE TABLE choice_learning_exclusions (
    publication_id INTEGER NOT NULL REFERENCES choice_learning_publications(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK(name IN ('unseen','unmapped_mode','drifted_mode','future_context','missing_context','unmapped_definition','legacy_ambiguous')),
    value INTEGER NOT NULL CHECK(typeof(value)='integer' AND value>=0),
    PRIMARY KEY(publication_id,name)
) WITHOUT ROWID;

CREATE TABLE choice_mode_estimates (
    publication_id INTEGER NOT NULL REFERENCES choice_learning_publications(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 8191),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 511),
    mode_id CHECK(mode_id IS NULL OR typeof(mode_id) IN ('integer','text')),
    label TEXT,
    positive REAL CHECK(positive IS NULL OR (typeof(positive) IN ('integer','real') AND positive>=0 AND positive<=1.7976931348623157e308)),
    negative REAL CHECK(negative IS NULL OR (typeof(negative) IN ('integer','real') AND negative>=0 AND negative<=1.7976931348623157e308)),
    days INTEGER CHECK(days IS NULL OR (typeof(days)='integer' AND days>=0)),
    menus INTEGER CHECK(menus IS NULL OR (typeof(menus)='integer' AND menus>=0)),
    estimate REAL CHECK(estimate IS NULL OR estimate BETWEEN 0 AND 1),
    low REAL CHECK(low IS NULL OR low BETWEEN 0 AND 1),
    high REAL CHECK(high IS NULL OR high BETWEEN 0 AND 1),
    resolved_mode_id INTEGER REFERENCES taste_modes(mode_id),
    resolution_reason TEXT,
    CHECK((resolved_mode_id IS NOT NULL AND resolved_mode_id=mode_id AND resolution_reason IS NULL) OR (resolved_mode_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_mode')),
    PRIMARY KEY(publication_id,position),
    UNIQUE(publication_id,mode_id)
) WITHOUT ROWID;

CREATE TABLE choice_group_estimates (
    publication_id INTEGER NOT NULL REFERENCES choice_learning_publications(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 8191),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 8191),
    group_id TEXT,
    version TEXT,
    positive REAL CHECK(positive IS NULL OR (typeof(positive) IN ('integer','real') AND positive>=0 AND positive<=1.7976931348623157e308)),
    negative REAL CHECK(negative IS NULL OR (typeof(negative) IN ('integer','real') AND negative>=0 AND negative<=1.7976931348623157e308)),
    offered INTEGER CHECK(offered IS NULL OR (typeof(offered)='integer' AND offered>=0)),
    picked INTEGER CHECK(picked IS NULL OR (typeof(picked)='integer' AND picked>=0)),
    days INTEGER CHECK(days IS NULL OR (typeof(days)='integer' AND days>=0)),
    shared_strength REAL CHECK(shared_strength IS NULL OR shared_strength BETWEEN 0 AND 1),
    shared_from TEXT,
    alpha REAL CHECK(alpha IS NULL OR (typeof(alpha) IN ('integer','real') AND alpha>0 AND alpha<=1.7976931348623157e308)),
    beta REAL CHECK(beta IS NULL OR (typeof(beta) IN ('integer','real') AND beta>0 AND beta<=1.7976931348623157e308)),
    estimate REAL CHECK(estimate IS NULL OR estimate BETWEEN 0 AND 1),
    PRIMARY KEY(publication_id,position),
    UNIQUE(publication_id,group_id)
) WITHOUT ROWID;

CREATE TABLE choice_group_opportunities (
    publication_id INTEGER NOT NULL,
    estimate_position INTEGER NOT NULL,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 8191),
    opportunity_id TEXT NOT NULL CHECK(length(opportunity_id)>0),
    PRIMARY KEY(publication_id,estimate_position,position),
    UNIQUE(publication_id,estimate_position,opportunity_id),
    FOREIGN KEY(publication_id,estimate_position) REFERENCES choice_group_estimates(publication_id,position) ON DELETE CASCADE
) WITHOUT ROWID;

CREATE TABLE choice_learning_group_roots (
    publication_id INTEGER PRIMARY KEY NOT NULL REFERENCES choice_learning_publications(id),
    kind TEXT NOT NULL CHECK(kind='prepared'),
    external_key TEXT NOT NULL UNIQUE CHECK(external_key='choice-learning:'||publication_id),
    FOREIGN KEY(kind,external_key) REFERENCES group_evidence_owners(kind,external_key)
) WITHOUT ROWID;

CREATE TABLE choice_interest_contexts (
    publication_id INTEGER NOT NULL REFERENCES choice_learning_publications(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 127),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 8191),
    format TEXT CHECK(format IS NULL OR format IN ('mixes','albums','radio')),
    option_id TEXT,
    mode_id CHECK(mode_id IS NULL OR typeof(mode_id) IN ('integer','text')),
    intent TEXT,
    basis TEXT,
    at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
    episode TEXT,
    opportunity_id TEXT,
    days INTEGER CHECK(days IS NULL OR (typeof(days)='integer' AND days>=0)),
    episodes INTEGER CHECK(episodes IS NULL OR (typeof(episodes)='integer' AND episodes>=0)),
    episode_support REAL CHECK(episode_support IS NULL OR (typeof(episode_support) IN ('integer','real') AND episode_support>=0 AND episode_support<=1.7976931348623157e308)),
    feature_null INTEGER NOT NULL CHECK(typeof(feature_null)='integer' AND feature_null IN (0,1)),
    album_id INTEGER REFERENCES albums(id),
    resolution_reason TEXT,
    CHECK((format='albums' AND ((album_id IS NOT NULL AND resolution_reason IS NULL) OR (album_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_album'))) OR ((format IS NULL OR format<>'albums') AND album_id IS NULL AND resolution_reason IS NULL)),
    PRIMARY KEY(publication_id,position)
) WITHOUT ROWID;

CREATE TABLE choice_interest_features (
    publication_id INTEGER NOT NULL,
    context_position INTEGER NOT NULL,
    dimension INTEGER NOT NULL CHECK(typeof(dimension)='integer' AND dimension BETWEEN 0 AND 8191),
    value REAL NOT NULL CHECK(typeof(value) IN ('integer','real') AND abs(value)<=1.7976931348623157e308),
    PRIMARY KEY(publication_id,context_position,dimension),
    FOREIGN KEY(publication_id,context_position) REFERENCES choice_interest_contexts(publication_id,position) ON DELETE CASCADE
) WITHOUT ROWID;

CREATE TABLE choice_interest_tracks (
    publication_id INTEGER NOT NULL,
    context_position INTEGER NOT NULL,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 99),
    raw_key TEXT NOT NULL CHECK(length(raw_key)>0),
    recording_id INTEGER REFERENCES recordings(id),
    resolution_reason TEXT,
    CHECK((recording_id IS NOT NULL AND resolution_reason IS NULL) OR (recording_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_recording')),
    PRIMARY KEY(publication_id,context_position,position),
    UNIQUE(publication_id,context_position,raw_key),
    FOREIGN KEY(publication_id,context_position) REFERENCES choice_interest_contexts(publication_id,position) ON DELETE CASCADE
) WITHOUT ROWID;

CREATE INDEX ix_choice_interest_recording ON choice_interest_tracks(recording_id,publication_id) WHERE recording_id IS NOT NULL;

CREATE TABLE choice_album_interests (
    publication_id INTEGER NOT NULL REFERENCES choice_learning_publications(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 127),
    browse_id TEXT NOT NULL CHECK(length(browse_id)>0),
    album_id INTEGER REFERENCES albums(id),
    resolution_reason TEXT,
    CHECK((album_id IS NOT NULL AND resolution_reason IS NULL) OR (album_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_album')),
    PRIMARY KEY(publication_id,position),
    UNIQUE(publication_id,browse_id)
) WITHOUT ROWID;

CREATE INDEX ix_choice_interest_album ON choice_album_interests(album_id,publication_id) WHERE album_id IS NOT NULL;

CREATE TABLE choice_album_track_days (
    publication_id INTEGER NOT NULL,
    album_position INTEGER NOT NULL,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 999),
    raw_key TEXT NOT NULL CHECK(length(raw_key)>0),
    recording_id INTEGER REFERENCES recordings(id),
    days INTEGER NOT NULL CHECK(typeof(days)='integer' AND days>=0),
    resolution_reason TEXT,
    CHECK((recording_id IS NOT NULL AND resolution_reason IS NULL) OR (recording_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_recording')),
    PRIMARY KEY(publication_id,album_position,position),
    UNIQUE(publication_id,album_position,raw_key),
    FOREIGN KEY(publication_id,album_position) REFERENCES choice_album_interests(publication_id,position) ON DELETE CASCADE
) WITHOUT ROWID;

CREATE INDEX ix_choice_album_day_recording ON choice_album_track_days(recording_id,publication_id) WHERE recording_id IS NOT NULL;

CREATE TRIGGER retired_choice_learning_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface IN ('choice_bandit','group_choice_bandit','choice_interests')
BEGIN SELECT RAISE(ABORT,'Choice learning has a relational owner'); END;

CREATE TRIGGER retired_choice_learning_update BEFORE UPDATE ON rec_proposals
WHEN NEW.surface IN ('choice_bandit','group_choice_bandit','choice_interests')
BEGIN SELECT RAISE(ABORT,'Choice learning has a relational owner'); END;

CREATE TABLE recommendation_report_publications (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    surface TEXT NOT NULL CHECK(surface IN ('listening_choices','choice_daily','model_health','model_live_report')),
    status TEXT NOT NULL DEFAULT 'building' CHECK(status IN ('building','published','retiring')),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    observed_at REAL CHECK(observed_at IS NULL OR (typeof(observed_at) IN ('integer','real') AND abs(observed_at)<=1.7976931348623157e308)),
    schema_version INTEGER CHECK(schema_version IS NULL OR (typeof(schema_version)='integer' AND schema_version>=0)),
    watermark TEXT,
    report_key TEXT,
    evidence_generation TEXT,
    inputs_key TEXT,
    next_at REAL CHECK(next_at IS NULL OR (typeof(next_at) IN ('integer','real') AND abs(next_at)<=1.7976931348623157e308)),
    vibe_episodes INTEGER CHECK(vibe_episodes IS NULL OR (typeof(vibe_episodes)='integer' AND vibe_episodes>=0)),
    half_life_days REAL CHECK(half_life_days IS NULL OR (typeof(half_life_days) IN ('integer','real') AND half_life_days>0 AND half_life_days<=1.7976931348623157e308)),
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),
    total_bytes INTEGER NOT NULL CHECK(typeof(total_bytes)='integer' AND total_bytes BETWEEN 1 AND 4194304),
    has_content INTEGER NOT NULL CHECK(typeof(has_content)='integer' AND has_content IN (0,1)),
    part_count INTEGER NOT NULL CHECK(typeof(part_count)='integer' AND part_count BETWEEN 1 AND 64),
    UNIQUE(id,surface)
);

CREATE TABLE recommendation_report_heads (
    surface TEXT PRIMARY KEY NOT NULL,
    publication_id INTEGER NOT NULL UNIQUE,
    FOREIGN KEY(publication_id,surface) REFERENCES recommendation_report_publications(id,surface)
) WITHOUT ROWID;

CREATE TABLE recommendation_report_files (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    publication_id INTEGER NOT NULL,
    surface TEXT NOT NULL,
    chunk_key TEXT NOT NULL CHECK(chunk_key=CAST(CAST(chunk_key AS INTEGER) AS TEXT) AND CAST(chunk_key AS INTEGER) BETWEEN 0 AND 63),
    filename TEXT NOT NULL CHECK(length(filename)>0),
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),
    byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 1048576),
    UNIQUE(publication_id,chunk_key),
    FOREIGN KEY(publication_id,surface) REFERENCES recommendation_report_publications(id,surface)
);

CREATE TABLE choice_format_usage (
    publication_id INTEGER NOT NULL REFERENCES recommendation_report_publications(id),
    format TEXT NOT NULL CHECK(format IN ('mixes','albums','radio')),
    field TEXT NOT NULL CHECK(field IN ('scores','episodes','days')),
    value NOT NULL CHECK(typeof(value) IN ('integer','real') AND value>=0 AND value<=1.7976931348623157e308 AND (field='scores' OR typeof(value)='integer')),
    PRIMARY KEY(publication_id,format,field)
) WITHOUT ROWID;

CREATE TRIGGER recommendation_report_new BEFORE INSERT ON recommendation_report_publications
WHEN NEW.status<>'building' BEGIN SELECT RAISE(ABORT,'Report starts privately'); END;

CREATE TRIGGER recommendation_report_identity BEFORE UPDATE OF id,surface,built_at,observed_at,schema_version,watermark,report_key,evidence_generation,inputs_key,next_at,vibe_episodes,half_life_days,content_digest,total_bytes,has_content,part_count ON recommendation_report_publications
BEGIN SELECT RAISE(ABORT,'Report inputs are immutable'); END;

CREATE TRIGGER recommendation_report_transition BEFORE UPDATE OF status ON recommendation_report_publications
WHEN NOT ((OLD.status='building' AND NEW.status='published'
    AND NEW.part_count=(SELECT count(*) FROM recommendation_report_files WHERE publication_id=OLD.id)
    AND (SELECT min(CAST(chunk_key AS INTEGER)) FROM recommendation_report_files WHERE publication_id=OLD.id)=0
    AND (SELECT max(CAST(chunk_key AS INTEGER)) FROM recommendation_report_files WHERE publication_id=OLD.id)=NEW.part_count-1)
    OR (OLD.status='published' AND NEW.status='retiring' AND NOT EXISTS(SELECT 1 FROM recommendation_report_heads WHERE publication_id=OLD.id)))
BEGIN SELECT RAISE(ABORT,'Report is incomplete or retained'); END;

CREATE TRIGGER recommendation_report_retained BEFORE DELETE ON recommendation_report_publications
WHEN OLD.status<>'retiring' BEGIN SELECT RAISE(ABORT,'Report must retire first'); END;

CREATE TRIGGER recommendation_report_head_insert BEFORE INSERT ON recommendation_report_heads
WHEN NOT EXISTS(SELECT 1 FROM recommendation_report_publications WHERE id=NEW.publication_id AND status='published')
BEGIN SELECT RAISE(ABORT,'Report head requires published output'); END;

CREATE TRIGGER recommendation_report_head_update BEFORE UPDATE ON recommendation_report_heads
WHEN NOT EXISTS(SELECT 1 FROM recommendation_report_publications WHERE id=NEW.publication_id AND status='published')
BEGIN SELECT RAISE(ABORT,'Report head requires published output'); END;

CREATE TRIGGER recommendation_report_file_insert BEFORE INSERT ON recommendation_report_files
WHEN NOT EXISTS(SELECT 1 FROM recommendation_report_publications WHERE id=NEW.publication_id AND status='building')
BEGIN SELECT RAISE(ABORT,'Report files are sealed'); END;

CREATE TRIGGER recommendation_report_file_update BEFORE UPDATE ON recommendation_report_files
WHEN NEW.id IS NOT OLD.id OR NEW.publication_id IS NOT OLD.publication_id OR NEW.surface IS NOT OLD.surface OR NEW.chunk_key IS NOT OLD.chunk_key OR NEW.content_digest IS NOT OLD.content_digest OR NEW.byte_size IS NOT OLD.byte_size
BEGIN SELECT RAISE(ABORT,'Report files are immutable'); END;

CREATE TRIGGER recommendation_report_file_delete BEFORE DELETE ON recommendation_report_files
WHEN NOT EXISTS(SELECT 1 FROM recommendation_report_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Report files are retained'); END;

CREATE TRIGGER choice_format_usage_insert BEFORE INSERT ON choice_format_usage
WHEN NOT EXISTS(SELECT 1 FROM recommendation_report_publications WHERE id=NEW.publication_id AND surface='listening_choices' AND status='building')
BEGIN SELECT RAISE(ABORT,'Format usage belongs to the choice report'); END;

CREATE TRIGGER choice_format_usage_update BEFORE UPDATE ON choice_format_usage
BEGIN SELECT RAISE(ABORT,'Published format usage is immutable'); END;

CREATE TRIGGER choice_format_usage_delete BEFORE DELETE ON choice_format_usage
WHEN NOT EXISTS(SELECT 1 FROM recommendation_report_publications WHERE id=OLD.publication_id AND status IN ('building','retiring'))
BEGIN SELECT RAISE(ABORT,'Format usage is retained'); END;

CREATE TRIGGER retired_recommendation_report_insert BEFORE INSERT ON rec_proposals
WHEN NEW.surface IN ('listening_choices','choice_daily','model_health','model_live_report')
BEGIN SELECT RAISE(ABORT,'Reports have publication owners'); END;

CREATE TRIGGER retired_recommendation_report_update BEFORE UPDATE ON rec_proposals
WHEN NEW.surface IN ('listening_choices','choice_daily','model_health','model_live_report')
BEGIN SELECT RAISE(ABORT,'Reports have publication owners'); END;

CREATE TABLE account_auth_expirations (
 id INTEGER PRIMARY KEY,
 account_id INTEGER REFERENCES accounts(id),
 unresolved_account_id INTEGER CHECK(unresolved_account_id IS NULL OR (typeof(unresolved_account_id)='integer' AND unresolved_account_id>0)),
 label TEXT NOT NULL,
 CHECK((account_id IS NOT NULL AND unresolved_account_id IS NULL) OR (account_id IS NULL AND unresolved_account_id IS NOT NULL))
);

CREATE UNIQUE INDEX ix_auth_expiration_account ON account_auth_expirations(account_id) WHERE account_id IS NOT NULL;

CREATE UNIQUE INDEX ix_auth_expiration_unresolved ON account_auth_expirations(unresolved_account_id) WHERE unresolved_account_id IS NOT NULL;

CREATE TABLE album_feedback (
 id INTEGER PRIMARY KEY,
 account_id INTEGER REFERENCES accounts(id),
 album_id INTEGER NOT NULL REFERENCES albums(id),
 source_browse_id TEXT NOT NULL,
 response TEXT NOT NULL CHECK(response IN ('more','known','reject')),
 created_at REAL NOT NULL CHECK(typeof(created_at) IN ('integer','real') AND abs(created_at)<=1.7976931348623157e308),
 withdrawn_at REAL CHECK(withdrawn_at IS NULL OR (typeof(withdrawn_at) IN ('integer','real') AND abs(withdrawn_at)<=1.7976931348623157e308)),
 opportunity_id TEXT,
 action_id TEXT,
 legacy_author_unknown INTEGER NOT NULL DEFAULT 0 CHECK(legacy_author_unknown IN (0,1)),
 CHECK((account_id IS NOT NULL AND legacy_author_unknown=0) OR (account_id IS NULL AND legacy_author_unknown=1)),
 CHECK(withdrawn_at IS NULL OR withdrawn_at>=created_at)
);

CREATE UNIQUE INDEX ix_album_feedback_current ON album_feedback(account_id,album_id) WHERE withdrawn_at IS NULL AND account_id IS NOT NULL;

CREATE UNIQUE INDEX ix_album_feedback_unscoped ON album_feedback(album_id) WHERE withdrawn_at IS NULL AND account_id IS NULL;

CREATE INDEX ix_album_feedback_album ON album_feedback(album_id,withdrawn_at,account_id);

CREATE TABLE album_feedback_legacy_dismissals (
 account_id INTEGER NOT NULL REFERENCES accounts(id),
 album_id INTEGER NOT NULL REFERENCES albums(id),
 dismissed_at REAL NOT NULL CHECK(typeof(dismissed_at) IN ('integer','real') AND abs(dismissed_at)<=1.7976931348623157e308),
 PRIMARY KEY(account_id,album_id)
) WITHOUT ROWID;

CREATE TABLE discovery_artist_image_state (
 artist_id INTEGER PRIMARY KEY REFERENCES artists(id),
 retry_at REAL NOT NULL CHECK(typeof(retry_at) IN ('integer','real') AND abs(retry_at)<=1.7976931348623157e308)
);

CREATE TABLE discovery_fetch_history (
 source_type TEXT NOT NULL CHECK(source_type IN ('album','artist','genre','radio')),
 source_id TEXT NOT NULL CHECK(length(source_id)>0),
 album_id INTEGER REFERENCES albums(id),
 PRIMARY KEY(source_type,source_id),
 CHECK((source_type='album' AND album_id IS NOT NULL) OR (source_type<>'album' AND album_id IS NULL))
) WITHOUT ROWID;

CREATE TABLE provider_refresh_frontiers (
 provider TEXT PRIMARY KEY NOT NULL REFERENCES enrichment_provider_config(provider),
 cursor INTEGER NOT NULL CHECK(typeof(cursor)='integer' AND cursor>=0),
 cutoff INTEGER NOT NULL CHECK(typeof(cutoff)='integer' AND cutoff>=0),
 fingerprint TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1)
) WITHOUT ROWID;

CREATE TABLE road_trip_drafts (
 id TEXT PRIMARY KEY NOT NULL,
 recipe_id INTEGER UNIQUE REFERENCES road_trip_recipes(id) ON DELETE CASCADE,
 account_id INTEGER REFERENCES accounts(id),
 legacy_author_unknown INTEGER NOT NULL DEFAULT 0 CHECK(legacy_author_unknown IN (0,1)),
 revision TEXT NOT NULL CHECK(length(revision)>0),
 state TEXT NOT NULL CHECK(state IN ('building','ready','saved','failed')),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 updated_at REAL NOT NULL CHECK(typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308),
 CHECK((account_id IS NOT NULL AND legacy_author_unknown=0) OR (account_id IS NULL AND legacy_author_unknown=1))
);

CREATE TABLE road_trip_draft_entries (
 draft_id TEXT NOT NULL REFERENCES road_trip_drafts(id) ON DELETE CASCADE,
 selection_state TEXT NOT NULL CHECK(selection_state IN ('picked','excluded')),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 recording_id INTEGER NOT NULL REFERENCES recordings(id),
 entry_id INTEGER REFERENCES catalog_entries(id),
 video_id TEXT NOT NULL REFERENCES youtube_items(video_id),
 PRIMARY KEY(draft_id,selection_state,position)
) WITHOUT ROWID;

CREATE INDEX ix_draft_entry_recording ON road_trip_draft_entries(recording_id,draft_id);

CREATE INDEX ix_draft_entry_source ON road_trip_draft_entries(entry_id);

CREATE TRIGGER draft_entry_subject_insert BEFORE INSERT ON road_trip_draft_entries
WHEN NOT EXISTS(SELECT 1 FROM youtube_items WHERE video_id=NEW.video_id AND recording_id=NEW.recording_id)
 OR (NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=NEW.entry_id AND recording_id=NEW.recording_id AND video_id=NEW.video_id))
BEGIN SELECT RAISE(ABORT,'Draft source belongs to another recording'); END;

CREATE TRIGGER draft_entry_subject_update BEFORE UPDATE ON road_trip_draft_entries
WHEN NOT EXISTS(SELECT 1 FROM youtube_items WHERE video_id=NEW.video_id AND recording_id=NEW.recording_id)
 OR (NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=NEW.entry_id AND recording_id=NEW.recording_id AND video_id=NEW.video_id))
BEGIN SELECT RAISE(ABORT,'Draft source belongs to another recording'); END;

CREATE TABLE radio_playlist_origins (
 id INTEGER PRIMARY KEY,
 playlist_scope_id TEXT UNIQUE REFERENCES playlist_scopes(id),
 unresolved_provider_id TEXT UNIQUE CHECK(unresolved_provider_id IS NULL OR length(unresolved_provider_id)>0),
 CHECK((playlist_scope_id IS NOT NULL AND unresolved_provider_id IS NULL)
    OR (playlist_scope_id IS NULL AND unresolved_provider_id IS NOT NULL))
);

CREATE TABLE radio_sessions (
 id TEXT PRIMARY KEY NOT NULL CHECK(length(id)>0),
 account_id INTEGER NOT NULL REFERENCES accounts(id),
 playlist_scope_id TEXT REFERENCES playlist_scopes(id),
 status TEXT NOT NULL CHECK(status IN ('preparing','awaiting_playback','playing','appending','replacing','conflict','stopping','stopped')),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 updated_at REAL NOT NULL CHECK(typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)
);

CREATE TABLE radio_session_head (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 session_id TEXT NOT NULL UNIQUE REFERENCES radio_sessions(id)
);

CREATE TABLE radio_queue_items (
 session_id TEXT NOT NULL REFERENCES radio_sessions(id) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 recording_id INTEGER NOT NULL REFERENCES recordings(id),
 entry_id INTEGER REFERENCES catalog_entries(id),
 video_id TEXT NOT NULL REFERENCES youtube_items(video_id),
 state TEXT NOT NULL CHECK(state IN ('played','current','queued','initial','pending')),
 PRIMARY KEY(session_id,position)
) WITHOUT ROWID;

CREATE INDEX ix_radio_queue_recording ON radio_queue_items(recording_id,session_id);

CREATE TRIGGER radio_queue_subject_insert BEFORE INSERT ON radio_queue_items
WHEN NOT EXISTS(SELECT 1 FROM youtube_items WHERE video_id=NEW.video_id AND recording_id=NEW.recording_id)
 OR (NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=NEW.entry_id AND recording_id=NEW.recording_id AND video_id=NEW.video_id))
BEGIN SELECT RAISE(ABORT,'Radio source belongs to another recording'); END;

CREATE TRIGGER radio_queue_subject_update BEFORE UPDATE ON radio_queue_items
WHEN NOT EXISTS(SELECT 1 FROM youtube_items WHERE video_id=NEW.video_id AND recording_id=NEW.recording_id)
 OR (NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=NEW.entry_id AND recording_id=NEW.recording_id AND video_id=NEW.video_id))
BEGIN SELECT RAISE(ABORT,'Radio source belongs to another recording'); END;

CREATE TRIGGER radio_session_scope_insert BEFORE INSERT ON radio_sessions
WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s
 WHERE s.id=NEW.playlist_scope_id AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Radio playlist belongs to another account'); END;

CREATE TRIGGER radio_session_scope_update BEFORE UPDATE ON radio_sessions
WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s
 WHERE s.id=NEW.playlist_scope_id AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Radio playlist belongs to another account'); END;

CREATE TABLE album_playback_intents (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 account_id INTEGER REFERENCES accounts(id),
 album_id INTEGER NOT NULL REFERENCES albums(id),
 source_browse_id TEXT NOT NULL,
 playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),
 opportunity_id TEXT NOT NULL,
 action_id TEXT,
 started_at REAL NOT NULL CHECK(typeof(started_at) IN ('integer','real') AND abs(started_at)<=1.7976931348623157e308),
 has_videos INTEGER NOT NULL CHECK(has_videos IN (0,1)),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1)
);

CREATE TABLE album_playback_intent_items (
 intent_id INTEGER NOT NULL REFERENCES album_playback_intents(singleton) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 video_id TEXT NOT NULL REFERENCES youtube_items(video_id),
 PRIMARY KEY(intent_id,position)
) WITHOUT ROWID;

CREATE TRIGGER album_playback_scope_insert BEFORE INSERT ON album_playback_intents
WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id
 AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Album playback playlist belongs to another account'); END;

CREATE TRIGGER album_playback_scope_update BEFORE UPDATE ON album_playback_intents
WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id
 AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Album playback playlist belongs to another account'); END;

CREATE TABLE listening_playback_bindings (
 account_id INTEGER NOT NULL REFERENCES accounts(id),
 playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),
 video_id TEXT NOT NULL REFERENCES youtube_items(video_id),
 opportunity_id TEXT NOT NULL,
 option_id TEXT NOT NULL,
 bound_at REAL NOT NULL CHECK(typeof(bound_at) IN ('integer','real') AND abs(bound_at)<=1.7976931348623157e308),
 PRIMARY KEY(account_id,playlist_scope_id,video_id)
) WITHOUT ROWID;

CREATE INDEX ix_playback_binding_time ON listening_playback_bindings(bound_at);

CREATE TRIGGER playback_binding_scope_insert BEFORE INSERT ON listening_playback_bindings
WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id
 AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Playback playlist belongs to another account'); END;

CREATE TRIGGER playback_binding_scope_update BEFORE UPDATE ON listening_playback_bindings
WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id
 AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Playback playlist belongs to another account'); END;

CREATE TABLE sync_attempts (
 id INTEGER PRIMARY KEY CHECK(id=1),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1),
 phase TEXT NOT NULL CHECK(phase IN ('running','complete','partial','failed','skipped')),
 outcome TEXT CHECK(outcome IN ('complete','partial','failed','skipped')),
 started_at REAL CHECK(started_at IS NULL OR (typeof(started_at) IN ('integer','real') AND abs(started_at)<=1.7976931348623157e308)),
 finished_at REAL CHECK(finished_at IS NULL OR (typeof(finished_at) IN ('integer','real') AND abs(finished_at)<=1.7976931348623157e308)),
 last_success_at REAL CHECK(last_success_at IS NULL OR (typeof(last_success_at) IN ('integer','real') AND abs(last_success_at)<=1.7976931348623157e308)),
 recovery_filename TEXT,
 recovery_digest TEXT CHECK(recovery_digest IS NULL OR length(recovery_digest)=64),
 recovery_bytes INTEGER CHECK(recovery_bytes IS NULL OR (typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)),
 CHECK((recovery_filename IS NULL AND recovery_digest IS NULL AND recovery_bytes IS NULL) OR (recovery_filename IS NOT NULL AND recovery_digest IS NOT NULL AND recovery_bytes IS NOT NULL))
);

CREATE TABLE sync_cursors (
 id INTEGER PRIMARY KEY,
 account_id INTEGER REFERENCES accounts(id),
 provider TEXT NOT NULL CHECK(provider='youtube'),
 collection TEXT NOT NULL CHECK(collection IN ('account','playlist_listing','playlists','ratings','history','saved_albums','saved_album_mirror','album_tracks','playlist')),
 playlist_scope_id TEXT REFERENCES playlist_scopes(id),
 cursor TEXT,
 phase TEXT NOT NULL CHECK(phase IN ('complete','partial','failed','skipped')),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1),
 updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)),
 last_success_at REAL CHECK(last_success_at IS NULL OR (typeof(last_success_at) IN ('integer','real') AND abs(last_success_at)<=1.7976931348623157e308)),
 failures INTEGER CHECK(failures IS NULL OR (typeof(failures)='integer' AND failures BETWEEN 0 AND 16)),
 retry_at REAL CHECK(retry_at IS NULL OR (typeof(retry_at) IN ('integer','real') AND abs(retry_at)<=1.7976931348623157e308)),
 CHECK((collection='playlist' AND playlist_scope_id IS NOT NULL AND account_id IS NOT NULL) OR (collection<>'playlist' AND playlist_scope_id IS NULL)),
 CHECK(account_id IS NOT NULL OR collection IN ('saved_album_mirror','album_tracks'))
);

CREATE UNIQUE INDEX ix_sync_account_resource ON sync_cursors(account_id,provider,collection) WHERE account_id IS NOT NULL AND playlist_scope_id IS NULL;

CREATE UNIQUE INDEX ix_sync_global_resource ON sync_cursors(provider,collection) WHERE account_id IS NULL;

CREATE UNIQUE INDEX ix_sync_playlist_resource ON sync_cursors(account_id,provider,playlist_scope_id) WHERE playlist_scope_id IS NOT NULL;

CREATE INDEX ix_sync_retry ON sync_cursors(phase,retry_at,account_id);

CREATE TRIGGER sync_cursor_scope_insert BEFORE INSERT ON sync_cursors
WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s
 WHERE s.id=NEW.playlist_scope_id AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Sync playlist belongs to another account'); END;

CREATE TRIGGER sync_cursor_scope_update BEFORE UPDATE ON sync_cursors
WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_scopes s
 WHERE s.id=NEW.playlist_scope_id AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id)))
BEGIN SELECT RAISE(ABORT,'Sync playlist belongs to another account'); END;

CREATE TABLE album_menu_controls (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 expires_at REAL NOT NULL CHECK(typeof(expires_at) IN ('integer','real') AND abs(expires_at)<=1.7976931348623157e308),
 novelty REAL NOT NULL CHECK(typeof(novelty) IN ('integer','real') AND novelty BETWEEN 0 AND 1)
);

CREATE TABLE album_menu_control_genres (
 singleton INTEGER NOT NULL REFERENCES album_menu_controls(singleton) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 99),
 genre_key TEXT REFERENCES genre_catalog(key),
 unresolved_value TEXT CHECK(unresolved_value IS NULL OR length(unresolved_value) BETWEEN 1 AND 100),
 PRIMARY KEY(singleton,position),
 CHECK((genre_key IS NOT NULL AND unresolved_value IS NULL) OR (genre_key IS NULL AND unresolved_value IS NOT NULL))
) WITHOUT ROWID;

CREATE INDEX ix_album_menu_control_genre ON album_menu_control_genres(genre_key);

CREATE TABLE model_selection_heads (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 active_run_id INTEGER REFERENCES rec_model_selection_runs(id),
 display_run_id INTEGER REFERENCES rec_model_selection_runs(id),
 live_run_id INTEGER REFERENCES rec_model_selection_runs(id),
 restore_run_id INTEGER REFERENCES rec_model_selection_runs(id)
);

CREATE TABLE candidate_refresh_checkpoint (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 preferences_fingerprint TEXT,
 expires_at REAL CHECK(expires_at IS NULL OR (typeof(expires_at) IN ('integer','real') AND abs(expires_at)<=1.7976931348623157e308))
);

CREATE TABLE vibe_preparation_checkpoint (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 policy_version TEXT
);

CREATE TABLE taste_model_state (
 id TEXT PRIMARY KEY NOT NULL CHECK(id IN ('recording','artist')),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1),
 generation TEXT,
 input_fingerprint TEXT,
 genre_revision TEXT,
 fit_fingerprint TEXT,
 recovery_filename TEXT,
 recovery_digest TEXT CHECK(recovery_digest IS NULL OR length(recovery_digest)=64),
 recovery_bytes INTEGER CHECK(recovery_bytes IS NULL OR (typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)),
 CHECK((recovery_filename IS NULL AND recovery_digest IS NULL AND recovery_bytes IS NULL) OR (recovery_filename IS NOT NULL AND recovery_digest IS NOT NULL AND recovery_bytes IS NOT NULL))
) WITHOUT ROWID;

CREATE TABLE content_basis_checkpoint (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 serial INTEGER CHECK(serial IS NULL OR (typeof(serial)='integer' AND serial>=0)),
 rows INTEGER CHECK(rows IS NULL OR (typeof(rows)='integer' AND rows>=0)),
 at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
 reason TEXT,
 estimated_bytes INTEGER CHECK(estimated_bytes IS NULL OR (typeof(estimated_bytes)='integer' AND estimated_bytes>=0)),
 dimensions INTEGER CHECK(dimensions IS NULL OR (typeof(dimensions)='integer' AND dimensions>=0)),
 input_fingerprint TEXT,
 has_modes INTEGER NOT NULL CHECK(has_modes IN (0,1)),
 mode_count INTEGER CHECK(mode_count IS NULL OR (typeof(mode_count)='integer' AND mode_count>0)),
 mode_min_members INTEGER CHECK(mode_min_members IS NULL OR (typeof(mode_min_members)='integer' AND mode_min_members>0)),
 mode_match_threshold REAL CHECK(mode_match_threshold IS NULL OR (typeof(mode_match_threshold) IN ('integer','real') AND mode_match_threshold BETWEEN 0 AND 1)),
 has_phases INTEGER NOT NULL CHECK(has_phases IN (0,1)),
 bytes_encoding INTEGER CHECK(bytes_encoding IS NULL OR (typeof(bytes_encoding)='integer' AND bytes_encoding>=0)),
 bytes_clustering INTEGER CHECK(bytes_clustering IS NULL OR (typeof(bytes_clustering)='integer' AND bytes_clustering>=0)),
 bytes_publication INTEGER CHECK(bytes_publication IS NULL OR (typeof(bytes_publication)='integer' AND bytes_publication>=0)),
 CHECK((has_modes=0 AND mode_count IS NULL AND mode_min_members IS NULL AND mode_match_threshold IS NULL)
    OR (has_modes=1 AND mode_count IS NOT NULL AND mode_min_members IS NOT NULL AND mode_match_threshold IS NOT NULL)),
 CHECK(has_phases=1 OR (bytes_encoding IS NULL AND bytes_clustering IS NULL AND bytes_publication IS NULL))
);

CREATE TABLE content_full_checkpoint (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 content INTEGER CHECK(content IS NULL OR (typeof(content)='integer' AND content>=0)),
 evidence INTEGER CHECK(evidence IS NULL OR (typeof(evidence)='integer' AND evidence>=0)),
 rows INTEGER CHECK(rows IS NULL OR (typeof(rows)='integer' AND rows>=0)),
 at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
 has_config INTEGER NOT NULL CHECK(has_config IN (0,1)),
 embed_method TEXT,
 dimensions_setting TEXT,
 cooc_weighting TEXT,
 restore_run TEXT,
 mode_count_setting TEXT,
 mode_min_members_setting TEXT,
 mode_match_threshold_setting TEXT
);

CREATE TABLE content_fit_checkpoint (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 state TEXT CHECK(state IN ('ready','waiting','deferred')),
 reason TEXT,
 attempted_at REAL CHECK(attempted_at IS NULL OR (typeof(attempted_at) IN ('integer','real') AND abs(attempted_at)<=1.7976931348623157e308)),
 attempts INTEGER CHECK(attempts IS NULL OR (typeof(attempts)='integer' AND attempts>=0)),
 since REAL CHECK(since IS NULL OR (typeof(since) IN ('integer','real') AND abs(since)<=1.7976931348623157e308)),
 next_attempt_at REAL CHECK(next_attempt_at IS NULL OR (typeof(next_attempt_at) IN ('integer','real') AND abs(next_attempt_at)<=1.7976931348623157e308)),
 memory_bytes INTEGER CHECK(memory_bytes IS NULL OR (typeof(memory_bytes)='integer' AND memory_bytes>=0)),
 estimated_bytes INTEGER CHECK(estimated_bytes IS NULL OR (typeof(estimated_bytes)='integer' AND estimated_bytes>=0)),
 rows INTEGER CHECK(rows IS NULL OR (typeof(rows)='integer' AND rows>=0)),
 dimensions INTEGER CHECK(dimensions IS NULL OR (typeof(dimensions)='integer' AND dimensions>=0)),
 max_rows INTEGER CHECK(max_rows IS NULL OR (typeof(max_rows)='integer' AND max_rows>=0)),
 has_phases INTEGER NOT NULL CHECK(has_phases IN (0,1)),
 bytes_encoding INTEGER CHECK(bytes_encoding IS NULL OR (typeof(bytes_encoding)='integer' AND bytes_encoding>=0)),
 bytes_clustering INTEGER CHECK(bytes_clustering IS NULL OR (typeof(bytes_clustering)='integer' AND bytes_clustering>=0)),
 bytes_publication INTEGER CHECK(bytes_publication IS NULL OR (typeof(bytes_publication)='integer' AND bytes_publication>=0)),
 CHECK(has_phases=1 OR (bytes_encoding IS NULL AND bytes_clustering IS NULL AND bytes_publication IS NULL))
);

CREATE TABLE group_preparation_state (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 fit_fingerprint TEXT,
 phase TEXT CHECK(phase IN ('preparing','ready','deferred')),
 reported_at REAL CHECK(reported_at IS NULL OR (typeof(reported_at) IN ('integer','real') AND abs(reported_at)<=1.7976931348623157e308)),
 reason TEXT,
 generation_id INTEGER REFERENCES group_generations(id),
 unresolved_generation TEXT,
 input_serial INTEGER CHECK(input_serial IS NULL OR (typeof(input_serial)='integer' AND input_serial>=0)),
 checkpoint_at REAL CHECK(checkpoint_at IS NULL OR (typeof(checkpoint_at) IN ('integer','real') AND abs(checkpoint_at)<=1.7976931348623157e308)),
 CHECK((phase IS NULL AND reported_at IS NULL AND reason IS NULL) OR (phase IS NOT NULL AND reported_at IS NOT NULL)),
 CHECK((generation_id IS NULL AND unresolved_generation IS NULL AND input_serial IS NULL AND checkpoint_at IS NULL)
  OR (((generation_id IS NOT NULL AND unresolved_generation IS NULL) OR (generation_id IS NULL AND unresolved_generation IS NOT NULL)) AND input_serial IS NOT NULL AND checkpoint_at IS NOT NULL))
);

CREATE TABLE tv_pool_state (
    id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 255),
    schema_version INTEGER CHECK(schema_version IS NULL OR (typeof(schema_version)='integer' AND schema_version>=0)),
    cache_key TEXT,
    at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
    offset INTEGER CHECK(offset IS NULL OR (typeof(offset)='integer' AND offset>=0)),
    state TEXT CHECK(state IS NULL OR state IN ('searching','exhausted','no_sources')),
    retry_at REAL CHECK(retry_at IS NULL OR (typeof(retry_at) IN ('integer','real') AND abs(retry_at)<=1.7976931348623157e308))
);

CREATE TABLE tv_pool_items (
    pool_id INTEGER NOT NULL REFERENCES tv_pool_state(id),
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 59),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 2047),
    video_id TEXT NOT NULL CHECK(length(video_id)=11 AND video_id NOT GLOB '*[^A-Za-z0-9_-]*'),
    title TEXT,
    artist TEXT,
    thumbnail TEXT,
    duration INTEGER CHECK(duration IS NULL OR (typeof(duration)='integer' AND duration>0)),
    kind TEXT,
    source_key TEXT,
    source_artist TEXT,
    source_group TEXT CHECK(source_group IS NULL OR source_group IN ('liked','your_artists','discovery')),
    connection TEXT,
    key TEXT CHECK(key IS NULL OR key=video_id),
    source_recording_id INTEGER REFERENCES recordings(id),
    source_resolution TEXT,
    recording_id INTEGER REFERENCES recordings(id),
    video_resolution TEXT,
    CHECK((source_recording_id IS NOT NULL AND source_resolution IS NULL) OR (source_recording_id IS NULL AND source_resolution IS NOT NULL AND source_resolution='missing_recording')),
    CHECK((recording_id IS NOT NULL AND video_resolution IS NULL) OR (recording_id IS NULL AND video_resolution IS NOT NULL AND video_resolution='external_video')),
    PRIMARY KEY(pool_id,position),
    UNIQUE(pool_id,video_id)
) WITHOUT ROWID;

CREATE TABLE tv_pool_attempts (
    pool_id INTEGER NOT NULL REFERENCES tv_pool_state(id),
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 59),
    raw_key TEXT NOT NULL CHECK(length(raw_key)>0),
    recording_id INTEGER REFERENCES recordings(id),
    resolution_reason TEXT,
    CHECK((recording_id IS NOT NULL AND resolution_reason IS NULL) OR (recording_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_recording')),
    PRIMARY KEY(pool_id,position),
    UNIQUE(pool_id,raw_key)
) WITHOUT ROWID;

CREATE TABLE tv_artwork_state (
    id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308))
);

CREATE TABLE tv_artist_artwork (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    artist_key TEXT NOT NULL UNIQUE CHECK(length(artist_key)>0),
    artist_id INTEGER REFERENCES artists(id),
    resolution_reason TEXT,
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 7),
    retry_at REAL CHECK(retry_at IS NULL OR (typeof(retry_at) IN ('integer','real') AND abs(retry_at)<=1.7976931348623157e308)),
    at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
    CHECK((artist_id IS NOT NULL AND resolution_reason IS NULL) OR (artist_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_artist'))
);

CREATE TABLE tv_artist_images (
    artwork_id INTEGER NOT NULL REFERENCES tv_artist_artwork(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 5),
    url TEXT NOT NULL CHECK(length(url)>0),
    PRIMARY KEY(artwork_id,position),
    UNIQUE(artwork_id,url)
) WITHOUT ROWID;

CREATE TABLE tv_artwork_request_state (
    id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308))
);

CREATE TABLE tv_artist_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    artist_key TEXT NOT NULL UNIQUE CHECK(length(artist_key)>0),
    display_name TEXT NOT NULL CHECK(length(display_name)>0),
    artist_id INTEGER REFERENCES artists(id),
    requested_at REAL CHECK(requested_at IS NULL OR (typeof(requested_at) IN ('integer','real') AND abs(requested_at)<=1.7976931348623157e308)),
    resolution_reason TEXT,
    CHECK((artist_id IS NOT NULL AND resolution_reason IS NULL) OR (artist_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_artist'))
);

CREATE TABLE tv_visual_state (
    id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308))
);

CREATE TABLE tv_visual_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    video_id TEXT NOT NULL UNIQUE CHECK(length(video_id)=11 AND video_id NOT GLOB '*[^A-Za-z0-9_-]*'),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 127),
    verdict TEXT CHECK(verdict IS NULL OR verdict IN ('static','moving','unknown')),
    version INTEGER CHECK(version IS NULL OR (typeof(version)='integer' AND version>=0)),
    at REAL CHECK(at IS NULL OR (typeof(at) IN ('integer','real') AND abs(at)<=1.7976931348623157e308)),
    retry_at REAL CHECK(retry_at IS NULL OR (typeof(retry_at) IN ('integer','real') AND abs(retry_at)<=1.7976931348623157e308)),
    difference REAL CHECK(difference IS NULL OR (typeof(difference) IN ('integer','real') AND difference>=0 AND difference<=1.7976931348623157e308)),
    changed_fraction REAL CHECK(changed_fraction IS NULL OR changed_fraction BETWEEN 0 AND 1)
);

CREATE INDEX ix_tv_visual_verdict ON tv_visual_results(version,verdict,video_id);

CREATE TABLE tv_visual_samples (
    result_id INTEGER NOT NULL REFERENCES tv_visual_results(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 1),
    at REAL NOT NULL CHECK(typeof(at) IN ('integer','real') AND at>=0 AND at<=1.7976931348623157e308),
    PRIMARY KEY(result_id,position)
) WITHOUT ROWID;

CREATE TABLE tv_continuation_receipts (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK(id>0),
    request_key TEXT NOT NULL UNIQUE CHECK(length(request_key)>0),
    source_playlist_id INTEGER NOT NULL CHECK(typeof(source_playlist_id)='integer' AND source_playlist_id>0),
    source_ref INTEGER REFERENCES playlist_membership_refs(id),
    source_resolution TEXT,
    input_stream TEXT NOT NULL,
    request_id TEXT NOT NULL CHECK(length(request_id)>0),
    status TEXT NOT NULL CHECK(status IN ('pending','complete')),
    target_playlist_id INTEGER CHECK(target_playlist_id IS NULL OR (typeof(target_playlist_id)='integer' AND target_playlist_id>0)),
    target_ref INTEGER REFERENCES playlist_membership_refs(id),
    target_resolution TEXT,
    target_stream TEXT NOT NULL CHECK(length(target_stream)>0),
    created_at REAL CHECK(created_at IS NULL OR (typeof(created_at) IN ('integer','real') AND abs(created_at)<=1.7976931348623157e308)),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    CHECK((source_ref IS NOT NULL AND source_ref=source_playlist_id AND source_resolution IS NULL) OR (source_ref IS NULL AND source_resolution IS NOT NULL AND source_resolution='missing_playlist')),
    CHECK((status='pending' AND target_playlist_id IS NULL AND target_ref IS NULL AND target_resolution IS NULL) OR
          (status='complete' AND target_playlist_id IS NOT NULL AND ((target_ref IS NOT NULL AND target_ref=target_playlist_id AND target_resolution IS NULL) OR
           (target_ref IS NULL AND target_resolution IS NOT NULL AND target_resolution='missing_playlist')))),
    UNIQUE(source_playlist_id,input_stream,request_id)
);

CREATE INDEX ix_tv_continuations_status ON tv_continuation_receipts(status,id);

CREATE TABLE tv_continuation_items (
    receipt_id INTEGER NOT NULL REFERENCES tv_continuation_receipts(id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 59),
    field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 2047),
    video_id TEXT NOT NULL CHECK(length(video_id)=11 AND video_id NOT GLOB '*[^A-Za-z0-9_-]*'),
    title TEXT,
    artist TEXT,
    thumbnail TEXT,
    duration INTEGER CHECK(duration IS NULL OR (typeof(duration)='integer' AND duration>0)),
    kind TEXT,
    source_key TEXT,
    source_artist TEXT,
    source_group TEXT CHECK(source_group IS NULL OR source_group IN ('liked','your_artists','discovery')),
    connection TEXT,
    key TEXT CHECK(key IS NULL OR key=video_id),
    source_recording_id INTEGER REFERENCES recordings(id),
    source_resolution TEXT,
    recording_id INTEGER REFERENCES recordings(id),
    video_resolution TEXT,
    CHECK((source_recording_id IS NOT NULL AND source_resolution IS NULL) OR (source_recording_id IS NULL AND source_resolution IS NOT NULL AND source_resolution='missing_recording')),
    CHECK((recording_id IS NOT NULL AND video_resolution IS NULL) OR (recording_id IS NULL AND video_resolution IS NOT NULL AND video_resolution='external_video')),
    PRIMARY KEY(receipt_id,position),
    UNIQUE(receipt_id,video_id)
) WITHOUT ROWID;

CREATE TRIGGER tv_receipt_complete_update BEFORE UPDATE ON tv_continuation_receipts WHEN OLD.status='complete'
BEGIN SELECT RAISE(ABORT,'Completed TV receipt is immutable'); END;

CREATE TRIGGER tv_receipt_pending_delete BEFORE DELETE ON tv_continuation_receipts WHEN OLD.status='pending'
BEGIN SELECT RAISE(ABORT,'Unconfirmed TV creation must be retained'); END;

CREATE TABLE clicked_library_pools (
    generation_id INTEGER PRIMARY KEY NOT NULL REFERENCES recommendation_generations(id) ON DELETE CASCADE,
    lane TEXT NOT NULL CHECK(lane IN ('wheelhouse','explore','comfort','temporal')),
    epoch INTEGER NOT NULL CHECK(typeof(epoch)='integer' AND epoch>=0),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308))
);

CREATE TABLE clicked_library_genres (
    generation_id INTEGER NOT NULL REFERENCES clicked_library_pools(generation_id) ON DELETE CASCADE,
    kind TEXT NOT NULL CHECK(kind IN ('include','avoid')),
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 99),
    raw_key TEXT NOT NULL CHECK(length(raw_key)>0),
    family_key TEXT REFERENCES genre_family(key),
    genre_key TEXT REFERENCES genre_catalog(key),
    resolution_reason TEXT,
    CHECK((family_key IS NOT NULL AND genre_key IS NULL AND resolution_reason IS NULL) OR
          (family_key IS NULL AND genre_key IS NOT NULL AND resolution_reason IS NULL) OR
          (family_key IS NULL AND genre_key IS NULL AND resolution_reason IS NOT NULL AND resolution_reason IN ('unknown_genre','ambiguous_genre'))),
    PRIMARY KEY(generation_id,kind,position),
    UNIQUE(generation_id,kind,raw_key)
) WITHOUT ROWID;

CREATE TRIGGER clicked_library_pool_owner BEFORE INSERT ON clicked_library_pools WHEN NOT EXISTS (
    SELECT 1 FROM recommendation_generation_surfaces WHERE generation_id=NEW.generation_id AND surface='home_pool:'||NEW.lane)
BEGIN SELECT RAISE(ABORT,'Clicked pool must belong to its lane publication'); END;

CREATE TRIGGER clicked_library_pool_update BEFORE UPDATE ON clicked_library_pools
BEGIN SELECT RAISE(ABORT,'Clicked pool parameters are immutable'); END;

CREATE TRIGGER clicked_library_pool_delete BEFORE DELETE ON clicked_library_pools WHEN EXISTS (
    SELECT 1 FROM recommendation_heads WHERE generation_id=OLD.generation_id)
BEGIN SELECT RAISE(ABORT,'Clicked pool parameters are retained'); END;

CREATE TRIGGER clicked_library_pool_insert BEFORE INSERT ON clicked_library_pools WHEN EXISTS (
    SELECT 1 FROM recommendation_heads WHERE generation_id=NEW.generation_id)
BEGIN SELECT RAISE(ABORT,'Published clicked pool parameters are immutable'); END;

CREATE TRIGGER clicked_library_genre_update BEFORE UPDATE ON clicked_library_genres
BEGIN SELECT RAISE(ABORT,'Clicked pool genres are immutable'); END;

CREATE TRIGGER clicked_library_genre_insert BEFORE INSERT ON clicked_library_genres WHEN EXISTS (
    SELECT 1 FROM recommendation_heads WHERE generation_id=NEW.generation_id)
BEGIN SELECT RAISE(ABORT,'Published clicked pool genres are immutable'); END;

CREATE TRIGGER clicked_library_genre_delete BEFORE DELETE ON clicked_library_genres WHEN EXISTS (
    SELECT 1 FROM recommendation_heads WHERE generation_id=OLD.generation_id)
BEGIN SELECT RAISE(ABORT,'Clicked pool genres are retained'); END;

CREATE TABLE model_pair_publications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id INTEGER NOT NULL CHECK(typeof(run_id)='integer' AND run_id>0),
    run_ref INTEGER REFERENCES rec_model_selection_runs(id),
    run_resolution TEXT,
    arm TEXT NOT NULL CHECK(arm IN ('incumbent','challenger')),
    format TEXT NOT NULL CHECK(format IN ('mixes','albums','radio')),
    generation_id INTEGER REFERENCES recommendation_generations(id),
    encoding_model TEXT CHECK(encoding_model IS NULL OR length(encoding_model) BETWEEN 1 AND 4096),
    built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('integer','real') AND abs(built_at)<=1.7976931348623157e308)),
    output_digest TEXT NOT NULL CHECK(length(output_digest)=64),
    part_count INTEGER NOT NULL CHECK(part_count BETWEEN 1 AND 128),
    status TEXT NOT NULL DEFAULT 'building' CHECK(status IN ('building','published','retiring')),
    CHECK((run_ref IS NOT NULL AND run_ref=run_id AND run_resolution IS NULL) OR
          (run_ref IS NULL AND run_resolution IS NOT NULL AND run_resolution='missing_run'))
);

CREATE TABLE model_pair_heads (
    run_id INTEGER NOT NULL,
    arm TEXT NOT NULL CHECK(arm IN ('incumbent','challenger')),
    format TEXT NOT NULL CHECK(format IN ('mixes','albums','radio')),
    publication_id INTEGER NOT NULL UNIQUE REFERENCES model_pair_publications(id),
    PRIMARY KEY(run_id,arm,format)
) WITHOUT ROWID;

CREATE TABLE model_pair_files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    publication_id INTEGER NOT NULL REFERENCES model_pair_publications(id),
    surface TEXT NOT NULL,
    chunk_key TEXT NOT NULL,
    filename TEXT NOT NULL,
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64),
    byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 1048576),
    UNIQUE(publication_id,chunk_key)
);

CREATE TABLE model_pair_policies (
    publication_id INTEGER NOT NULL REFERENCES model_pair_publications(id),
    raw_version TEXT NOT NULL,
    policy_version TEXT REFERENCES recommendation_policies(version),
    resolution_reason TEXT,
    PRIMARY KEY(publication_id,raw_version),
    CHECK((policy_version IS NOT NULL AND policy_version=raw_version AND resolution_reason IS NULL) OR
          (policy_version IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_policy'))
) WITHOUT ROWID;

CREATE INDEX ix_model_pair_policies ON model_pair_policies(policy_version);

CREATE TABLE model_pair_contexts (
    publication_id INTEGER NOT NULL REFERENCES model_pair_publications(id),
    field TEXT NOT NULL CHECK(field IN ('context','choice_context','album_choice_context')),
    artifact TEXT NOT NULL CHECK(length(artifact) BETWEEN 1 AND 1024),
    PRIMARY KEY(publication_id,field)
) WITHOUT ROWID;

CREATE TABLE model_pair_modes (
    publication_id INTEGER NOT NULL REFERENCES model_pair_publications(id),
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 511),
    mode_id INTEGER NOT NULL CHECK(typeof(mode_id)='integer' AND mode_id>0),
    mode_ref INTEGER REFERENCES taste_modes(mode_id),
    resolution_reason TEXT,
    space TEXT NOT NULL,
    centroid BLOB NOT NULL CHECK(typeof(centroid)='blob' AND length(centroid) BETWEEN 8 AND 32768 AND length(centroid)%8=0),
    PRIMARY KEY(publication_id,position),
    UNIQUE(publication_id,mode_id),
    CHECK((mode_ref IS NOT NULL AND mode_ref=mode_id AND resolution_reason IS NULL) OR
          (mode_ref IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_mode'))
) WITHOUT ROWID;

CREATE TABLE model_pair_group_roots (
    publication_id INTEGER NOT NULL REFERENCES model_pair_publications(id),
    field TEXT NOT NULL,
    kind TEXT NOT NULL CHECK(kind='comparison'),
    external_key TEXT NOT NULL,
    PRIMARY KEY(publication_id,field),
    FOREIGN KEY(kind,external_key) REFERENCES group_evidence_owners(kind,external_key)
) WITHOUT ROWID;

CREATE TABLE model_pair_recommendation_roots (
    publication_id INTEGER NOT NULL REFERENCES model_pair_publications(id),
    field TEXT NOT NULL,
    kind TEXT NOT NULL CHECK(kind='comparison'),
    external_key TEXT NOT NULL,
    generation_id INTEGER NOT NULL,
    PRIMARY KEY(publication_id,field,generation_id),
    FOREIGN KEY(kind,external_key,generation_id) REFERENCES recommendation_generation_refs(kind,external_key,generation_id)
) WITHOUT ROWID;

CREATE TRIGGER model_pair_head_insert BEFORE INSERT ON model_pair_heads BEGIN
    SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM model_pair_publications p WHERE p.id=NEW.publication_id
      AND p.run_id=NEW.run_id AND p.arm=NEW.arm AND p.format=NEW.format AND p.status='published')
      THEN RAISE(ABORT,'Comparison head requires matching published output') END;
END;

CREATE TRIGGER model_pair_head_update BEFORE UPDATE ON model_pair_heads BEGIN
    SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM model_pair_publications p WHERE p.id=NEW.publication_id
      AND p.run_id=NEW.run_id AND p.arm=NEW.arm AND p.format=NEW.format AND p.status='published')
      THEN RAISE(ABORT,'Comparison head requires matching published output') END;
END;

CREATE TRIGGER model_pair_seal BEFORE UPDATE OF status ON model_pair_publications
WHEN NEW.status='published' BEGIN
    SELECT CASE WHEN OLD.status<>'building' OR NEW.part_count<>(SELECT count(*) FROM model_pair_files WHERE publication_id=NEW.id)
      OR (NEW.generation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM recommendation_generations g
          WHERE g.id=NEW.generation_id AND g.status='published'))
      THEN RAISE(ABORT,'Comparison publication is incomplete') END;
END;

CREATE TRIGGER model_pair_retire BEFORE UPDATE OF status ON model_pair_publications
WHEN NEW.status='retiring' AND EXISTS(SELECT 1 FROM model_pair_heads WHERE publication_id=OLD.id) BEGIN
    SELECT RAISE(ABORT,'Comparison output still has a serving head');
END;

CREATE TRIGGER model_pair_publication_immutable BEFORE UPDATE ON model_pair_publications
WHEN OLD.status<>'building' AND NOT (OLD.status='published' AND NEW.status='retiring'
    AND NEW.id=OLD.id AND NEW.run_id=OLD.run_id AND NEW.run_ref IS OLD.run_ref
    AND NEW.run_resolution IS OLD.run_resolution AND NEW.arm=OLD.arm AND NEW.format=OLD.format
    AND NEW.generation_id IS OLD.generation_id AND NEW.encoding_model IS OLD.encoding_model
    AND NEW.built_at IS OLD.built_at AND NEW.output_digest=OLD.output_digest AND NEW.part_count=OLD.part_count) BEGIN
    SELECT RAISE(ABORT,'Published comparison is immutable');
END;

CREATE TABLE radio_session_policies (
    session_id TEXT NOT NULL REFERENCES radio_sessions(id) ON DELETE CASCADE,
    raw_version TEXT NOT NULL,
    policy_version TEXT REFERENCES recommendation_policies(version),
    resolution_reason TEXT,
    PRIMARY KEY(session_id,raw_version),
    CHECK((policy_version IS NOT NULL AND policy_version=raw_version AND resolution_reason IS NULL) OR
          (policy_version IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_policy'))
) WITHOUT ROWID;

CREATE INDEX ix_radio_session_policies ON radio_session_policies(policy_version);

CREATE TABLE taste_settings_checkpoints (
 id INTEGER PRIMARY KEY CHECK(id=1),
 revision TEXT NOT NULL CHECK(length(revision)>0),
 saved_at REAL NOT NULL CHECK(typeof(saved_at) IN ('integer','real') AND abs(saved_at)<=1.7976931348623157e308),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)
);

CREATE TABLE taste_checkpoint_weights (
 checkpoint_id INTEGER NOT NULL REFERENCES taste_settings_checkpoints(id) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 axis_id INTEGER NOT NULL REFERENCES taste_axes(id),
 captured_axis TEXT NOT NULL,
 weight REAL NOT NULL CHECK(typeof(weight) IN ('integer','real') AND abs(weight)<=1.7976931348623157e308),
 updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)),
 PRIMARY KEY(checkpoint_id,position),
 UNIQUE(checkpoint_id,axis_id)
) WITHOUT ROWID;

CREATE INDEX ix_taste_checkpoint_axis ON taste_checkpoint_weights(axis_id);

CREATE TABLE taste_comparison_baselines (
 id INTEGER PRIMARY KEY CHECK(id=1),
 revision TEXT NOT NULL CHECK(length(revision)>0),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)
);

CREATE TABLE taste_comparison_entries (
 baseline_id INTEGER NOT NULL REFERENCES taste_comparison_baselines(id) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 recording_id INTEGER REFERENCES recordings(id),
 unresolved_key TEXT,
 captured_key TEXT NOT NULL CHECK(length(captured_key)>0),
 rank INTEGER CHECK(rank IS NULL OR (typeof(rank)='integer' AND rank>0)),
 score REAL NOT NULL CHECK(typeof(score) IN ('integer','real') AND abs(score)<=1.7976931348623157e308),
 lane TEXT NOT NULL,
 lane_weight REAL CHECK(lane_weight IS NULL OR (typeof(lane_weight) IN ('integer','real') AND abs(lane_weight)<=1.7976931348623157e308)),
 PRIMARY KEY(baseline_id,position),
 CHECK((recording_id IS NOT NULL AND unresolved_key IS NULL) OR (recording_id IS NULL AND unresolved_key IS NOT NULL AND length(unresolved_key)>0))
) WITHOUT ROWID;

CREATE UNIQUE INDEX ix_comparison_recording ON taste_comparison_entries(baseline_id,recording_id) WHERE recording_id IS NOT NULL;

CREATE UNIQUE INDEX ix_comparison_unresolved ON taste_comparison_entries(baseline_id,unresolved_key) WHERE unresolved_key IS NOT NULL;

CREATE TABLE experiment_decisions (
 id INTEGER PRIMARY KEY,
 decision TEXT NOT NULL CHECK(decision IN ('promote','retire')),
 cohort TEXT NOT NULL CHECK(length(cohort)<=100),
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 2000),
 created_at REAL NOT NULL CHECK(typeof(created_at) IN ('integer','real') AND abs(created_at)<=1.7976931348623157e308),
 powered INTEGER NOT NULL CHECK(typeof(powered)='integer' AND powered IN (0,1)),
 basis TEXT NOT NULL,
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)
);

CREATE INDEX ix_experiment_decision_cohort ON experiment_decisions(cohort,created_at);

CREATE TABLE spotify_import_jobs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  revision TEXT NOT NULL CHECK(length(revision)=32),
  account_id INTEGER REFERENCES accounts(id),
  unresolved_account_id INTEGER,
  account_present INTEGER NOT NULL CHECK(account_present IN (0,1)),
  field_mask INTEGER NOT NULL CHECK(typeof(field_mask)='integer' AND field_mask BETWEEN 0 AND 4095),
  status TEXT NOT NULL CHECK(status IN ('queued','running','preview','done','error')),
  phase TEXT CHECK(phase IN ('preview','import')),
  started_at REAL CHECK(started_at IS NULL OR (typeof(started_at) IN ('integer','real') AND abs(started_at)<=1.7976931348623157e308)),
  finished_at REAL CHECK(finished_at IS NULL OR (typeof(finished_at) IN ('integer','real') AND abs(finished_at)<=1.7976931348623157e308)),
  identity_label TEXT,
  report_schema INTEGER CHECK(report_schema IS NULL OR (typeof(report_schema)='integer' AND report_schema>=0)),
  dismissed INTEGER CHECK(dismissed IS NULL OR dismissed IN (0,1)),
  error TEXT,
  playlists_found INTEGER CHECK(playlists_found IS NULL OR (typeof(playlists_found)='integer' AND playlists_found>=0)),
  track_entries INTEGER CHECK(track_entries IS NULL OR (typeof(track_entries)='integer' AND track_entries>=0)),
  albums_found INTEGER CHECK(albums_found IS NULL OR (typeof(albums_found)='integer' AND albums_found>=0)),
  lookup_count INTEGER CHECK(lookup_count IS NULL OR (typeof(lookup_count)='integer' AND lookup_count>=0)),
  estimate_label TEXT,
  recovery_filename TEXT NOT NULL,
  recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64 AND recovery_digest NOT GLOB '*[^0-9a-f]*'),
  recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
  CHECK((account_id IS NULL OR unresolved_account_id IS NULL) AND
        (account_present=1 OR (account_id IS NULL AND unresolved_account_id IS NULL)))
);

CREATE TABLE spotify_import_job_head (
  id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
  job_id INTEGER NOT NULL UNIQUE REFERENCES spotify_import_jobs(id)
);

CREATE INDEX ix_spotify_import_job_account ON spotify_import_jobs(account_id,status,id);

CREATE TABLE rec_recipes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  playlist_scope_id TEXT NOT NULL UNIQUE REFERENCES playlist_scopes(id),
  revision TEXT NOT NULL CHECK(length(revision)=32),
  created_at REAL CHECK(created_at IS NULL OR (typeof(created_at) IN ('integer','real') AND abs(created_at)<=1.7976931348623157e308)),
  media TEXT CHECK(media IS NULL OR media IN ('audio','video')),
  model TEXT,
  journey TEXT,
  opportunity_id TEXT,
  option_id TEXT,
  recovery_filename TEXT NOT NULL,
  recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64 AND recovery_digest NOT GLOB '*[^0-9a-f]*'),
  recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)
);

CREATE TABLE playlist_recipe_facets (
  recipe_id INTEGER NOT NULL REFERENCES rec_recipes(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK(kind IN ('genre','era')),
  position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
  axis_id INTEGER NOT NULL REFERENCES taste_axes(id),
  captured_value TEXT NOT NULL CHECK(length(captured_value)>0),
  PRIMARY KEY(recipe_id,kind,position)
) WITHOUT ROWID;

CREATE INDEX ix_playlist_recipe_axis ON playlist_recipe_facets(axis_id,recipe_id);

CREATE TABLE cluster_canvas (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  playlist_scope_id TEXT NOT NULL UNIQUE REFERENCES playlist_scopes(id),
  revision TEXT NOT NULL CHECK(length(revision)=32),
  created_at REAL CHECK(created_at IS NULL OR (typeof(created_at) IN ('integer','real') AND abs(created_at)<=1.7976931348623157e308)),
  recovery_filename TEXT NOT NULL,
  recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64 AND recovery_digest NOT GLOB '*[^0-9a-f]*'),
  recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)
);

CREATE TABLE actions (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 kind TEXT NOT NULL CHECK(length(trim(kind))>0),
 status TEXT NOT NULL CHECK(status IN ('draft','planned','pending','executing','executed','failed','cancelled','delete_pending','delete_failed','undoing','undo_failed','undone')),
 revision TEXT NOT NULL CHECK(length(revision)=32),
 idempotency_key TEXT NOT NULL UNIQUE CHECK(length(idempotency_key)>0),
 intent_digest TEXT NOT NULL CHECK(length(intent_digest)=64 AND intent_digest NOT GLOB '*[^0-9a-f]*'),
 parent_action_id INTEGER REFERENCES actions(id),
 undo_of_action_id INTEGER REFERENCES actions(id),
 reviewed_draft_id INTEGER,
 reviewed_draft_revision TEXT,
 reviewed_draft_signature TEXT,
 execution_token TEXT CHECK(execution_token IS NULL OR length(execution_token)=32),
 execution_mode TEXT CHECK(execution_mode IS NULL OR execution_mode IN ('delete','merge','move','copy')),
 created_at REAL CHECK(created_at IS NULL OR (typeof(created_at) IN ('integer','real') AND abs(created_at)<=1.7976931348623157e308)),
 executed_at REAL CHECK(executed_at IS NULL OR (typeof(executed_at) IN ('integer','real') AND abs(executed_at)<=1.7976931348623157e308)),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64 AND recovery_digest NOT GLOB '*[^0-9a-f]*'),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 CHECK(parent_action_id IS NULL OR parent_action_id<>id),
 CHECK(undo_of_action_id IS NULL OR undo_of_action_id<>id),
 CHECK((reviewed_draft_id IS NULL AND reviewed_draft_revision IS NULL AND reviewed_draft_signature IS NULL) OR
       (reviewed_draft_id IS NOT NULL AND reviewed_draft_revision IS NOT NULL AND reviewed_draft_signature IS NOT NULL))
);

CREATE INDEX ix_actions_status ON actions(kind,status,id);

CREATE UNIQUE INDEX uq_action_reviewed_revision ON actions(reviewed_draft_id,reviewed_draft_revision)
 WHERE reviewed_draft_id IS NOT NULL;

CREATE TABLE action_drafts (
 id INTEGER PRIMARY KEY REFERENCES actions(id) ON DELETE CASCADE,
 account_id INTEGER REFERENCES accounts(id),
 signature TEXT NOT NULL UNIQUE,
 revision TEXT NOT NULL CHECK(length(revision)=32),
 updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64 AND recovery_digest NOT GLOB '*[^0-9a-f]*'),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216)
);

CREATE TABLE action_targets (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 action_id INTEGER NOT NULL REFERENCES actions(id),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 role TEXT NOT NULL CHECK(role IN ('source','destination','keeper','deletion','recovery','placement')),
 account_id INTEGER REFERENCES accounts(id),
 unresolved_account_id INTEGER,
 playlist_scope_id TEXT REFERENCES playlist_scopes(id),
 provider_playlist_id_snapshot TEXT NOT NULL CHECK(length(provider_playlist_id_snapshot)>0),
 membership_ref_id INTEGER REFERENCES playlist_membership_refs(id),
 unresolved_membership_ref_id INTEGER,
 resolution_reason TEXT CHECK(resolution_reason IS NULL OR resolution_reason IN ('missing_account','missing_membership','unrecorded_account','missing_scope','membership_snapshot_mismatch')),
 UNIQUE(action_id,role,position),
 UNIQUE(id,action_id),
 UNIQUE(id,account_id,playlist_scope_id),
 CHECK(account_id IS NULL OR unresolved_account_id IS NULL),
 CHECK(membership_ref_id IS NULL OR unresolved_membership_ref_id IS NULL),
 CHECK(account_id IS NOT NULL OR resolution_reason IS NOT NULL)
);

CREATE INDEX ix_action_target_owner ON action_targets(account_id,provider_playlist_id_snapshot,action_id);

CREATE INDEX ix_action_target_scope ON action_targets(playlist_scope_id,account_id,action_id);

CREATE INDEX ix_action_target_membership ON action_targets(membership_ref_id,role,action_id);

CREATE TABLE action_steps (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 action_id INTEGER NOT NULL REFERENCES actions(id),
 target_id INTEGER,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 operation TEXT NOT NULL CHECK(operation IN ('delete_playlist','restore_backup','restore_keeper','delete_copy','place_tracks','merge_plan')),
 phase TEXT NOT NULL CHECK(phase IN ('prepared','pending','uncertain','failed','creating','created','restoring','deleting','remote_complete','complete','cancelled')),
 outcome TEXT NOT NULL CHECK(outcome IN ('not_sent','unknown','confirmed_present','confirmed_absent','complete','conflict')),
 claim_token TEXT CHECK(claim_token IS NULL OR length(claim_token)=32),
 creation_marker TEXT,
 created_provider_id_snapshot TEXT,
 created_playlist_scope_id TEXT REFERENCES playlist_scopes(id),
 original_survived INTEGER CHECK(original_survived IS NULL OR (typeof(original_survived)='integer' AND original_survived IN (0,1))),
 observed_status TEXT NOT NULL CHECK(observed_status IN ('unrecorded','unknown','present')),
 backup_filename TEXT,
 backup_digest TEXT CHECK(backup_digest IS NULL OR (length(backup_digest)=64 AND backup_digest NOT GLOB '*[^0-9a-f]*')),
 backup_bytes INTEGER CHECK(backup_bytes IS NULL OR (typeof(backup_bytes)='integer' AND backup_bytes>0)),
 backup_status TEXT NOT NULL CHECK(backup_status IN ('none','verified','missing_historical')),
 updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64 AND recovery_digest NOT GLOB '*[^0-9a-f]*'),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 FOREIGN KEY(target_id,action_id) REFERENCES action_targets(id,action_id),
 UNIQUE(action_id,position),
 CHECK((backup_status='none' AND backup_filename IS NULL AND backup_digest IS NULL AND backup_bytes IS NULL) OR
       (backup_status='verified' AND backup_filename IS NOT NULL AND backup_digest IS NOT NULL AND backup_bytes IS NOT NULL) OR
       (backup_status='missing_historical' AND backup_filename IS NOT NULL AND backup_digest IS NULL AND backup_bytes IS NULL)),
 CHECK(phase<>'uncertain' OR outcome='unknown'),
 CHECK(phase<>'complete' OR outcome='complete')
);

CREATE INDEX ix_action_step_pending ON action_steps(operation,phase,target_id,action_id);

CREATE TABLE action_backups (
 action_id INTEGER NOT NULL REFERENCES actions(id),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 filename TEXT NOT NULL CHECK(length(filename)>0),
 retained_filename TEXT,
 digest TEXT CHECK(digest IS NULL OR (length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*')),
 bytes INTEGER CHECK(bytes IS NULL OR (typeof(bytes)='integer' AND bytes>0)),
 availability TEXT NOT NULL CHECK(availability IN ('verified','missing_historical')),
 PRIMARY KEY(action_id,position),
 UNIQUE(action_id,filename),
 CHECK((availability='verified' AND retained_filename IS NOT NULL AND digest IS NOT NULL AND bytes IS NOT NULL) OR
       (availability='missing_historical' AND retained_filename IS NULL AND digest IS NULL AND bytes IS NULL))
) WITHOUT ROWID;

CREATE TABLE action_target_claims (
 account_id INTEGER NOT NULL REFERENCES accounts(id),
 playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),
 action_target_id INTEGER NOT NULL UNIQUE,
 claim_token TEXT NOT NULL CHECK(length(claim_token)=32),
 lease_until REAL NOT NULL CHECK(typeof(lease_until) IN ('integer','real') AND abs(lease_until)<=1.7976931348623157e308),
 PRIMARY KEY(account_id,playlist_scope_id),
 FOREIGN KEY(action_target_id,account_id,playlist_scope_id) REFERENCES action_targets(id,account_id,playlist_scope_id)
) WITHOUT ROWID;

CREATE TABLE action_plan_resolutions (
 action_id INTEGER NOT NULL REFERENCES actions(id),
 list_kind TEXT NOT NULL CHECK(list_kind IN ('additions','unresolved')),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 recording_id INTEGER REFERENCES recordings(id),
 unresolved_key TEXT,
 captured_identity_key TEXT NOT NULL,
 source_video_id_snapshot TEXT,
 target_video_id_snapshot TEXT,
 method TEXT NOT NULL CHECK(method IN ('reuse','search','unresolved')),
 PRIMARY KEY(action_id,list_kind,position),
 CHECK((recording_id IS NOT NULL AND unresolved_key IS NULL) OR
       (recording_id IS NULL AND unresolved_key IS NOT NULL AND unresolved_key=captured_identity_key))
) WITHOUT ROWID;

CREATE TABLE action_placement_intents (
 action_id INTEGER PRIMARY KEY REFERENCES actions(id),
 target_id INTEGER NOT NULL,
 after_video_id_snapshot TEXT,
 handles_present INTEGER NOT NULL CHECK(typeof(handles_present)='integer' AND handles_present IN (0,1)),
 FOREIGN KEY(target_id,action_id) REFERENCES action_targets(id,action_id)
);

CREATE TABLE action_placement_items (
 action_id INTEGER NOT NULL REFERENCES action_placement_intents(action_id),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 video_id_snapshot TEXT NOT NULL CHECK(length(video_id_snapshot)>0),
 PRIMARY KEY(action_id,position)
) WITHOUT ROWID;

CREATE TABLE action_placement_handles (
 action_id INTEGER NOT NULL REFERENCES action_placement_intents(action_id),
 video_id_snapshot TEXT NOT NULL CHECK(length(video_id_snapshot)>0),
 occurrence_handle_snapshot TEXT NOT NULL CHECK(length(occurrence_handle_snapshot)>0),
 PRIMARY KEY(action_id,video_id_snapshot)
) WITHOUT ROWID;

CREATE TABLE playlist_gc_attempts (
 id INTEGER PRIMARY KEY,
 captured_account_id INTEGER NOT NULL CHECK(typeof(captured_account_id)='integer'),
 account_id INTEGER REFERENCES accounts(id),
 playlist_scope_id TEXT REFERENCES playlist_scopes(id),
 provider_playlist_id_snapshot TEXT NOT NULL CHECK(length(provider_playlist_id_snapshot)>0),
 revision TEXT NOT NULL CHECK(length(revision)=32),
 attempts INTEGER NOT NULL CHECK(typeof(attempts)='integer' AND attempts>=1),
 last_attempt_at REAL NOT NULL CHECK(typeof(last_attempt_at) IN ('integer','real') AND abs(last_attempt_at)<=1.7976931348623157e308),
 next_retry_at REAL NOT NULL CHECK(typeof(next_retry_at) IN ('integer','real') AND abs(next_retry_at)<=1.7976931348623157e308),
 phase TEXT CHECK(phase IS NULL OR phase IN ('reconcile','backup','delete')),
 failure_class TEXT,
 error TEXT,
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 UNIQUE(captured_account_id,provider_playlist_id_snapshot),
 CHECK(account_id IS NULL OR account_id=captured_account_id)
);

CREATE INDEX ix_gc_attempt_deadline ON playlist_gc_attempts(next_retry_at);

CREATE TABLE spotify_transfer_receipts (
 id INTEGER PRIMARY KEY,
 source_kind TEXT NOT NULL CHECK(source_kind IN ('playlist','album')),
 captured_account_id INTEGER CHECK(captured_account_id IS NULL OR typeof(captured_account_id)='integer'),
 account_id INTEGER REFERENCES accounts(id),
 fingerprint TEXT NOT NULL CHECK(length(fingerprint)>0),
 revision TEXT NOT NULL CHECK(length(revision)=32),
 creation_phase TEXT NOT NULL CHECK(creation_phase IN ('legacy','prepared','creating','created')),
 marker TEXT,
 playlist_scope_id TEXT REFERENCES playlist_scopes(id),
 provider_playlist_id_snapshot TEXT,
 complete INTEGER CHECK(complete IS NULL OR (typeof(complete)='integer' AND complete IN (0,1))),
 order_verified INTEGER CHECK(order_verified IS NULL OR (typeof(order_verified)='integer' AND order_verified IN (0,1))),
 updated_at REAL CHECK(updated_at IS NULL OR (typeof(updated_at) IN ('integer','real') AND abs(updated_at)<=1.7976931348623157e308)),
 last_run_added INTEGER CHECK(last_run_added IS NULL OR (typeof(last_run_added)='integer' AND last_run_added>=0)),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 CHECK(account_id IS NULL OR account_id=captured_account_id),
 CHECK(creation_phase<>'creating' OR marker IS NOT NULL),
 CHECK(creation_phase<>'created' OR provider_playlist_id_snapshot IS NOT NULL)
);

CREATE UNIQUE INDEX uq_spotify_scoped_receipt ON spotify_transfer_receipts(captured_account_id,source_kind,fingerprint)
 WHERE captured_account_id IS NOT NULL;

CREATE UNIQUE INDEX uq_spotify_legacy_receipt ON spotify_transfer_receipts(source_kind,fingerprint)
 WHERE captured_account_id IS NULL;

CREATE TABLE spotify_transfer_items (
 receipt_id INTEGER NOT NULL REFERENCES spotify_transfer_receipts(id) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 video_id_snapshot TEXT CHECK(video_id_snapshot IS NULL OR length(video_id_snapshot)>0),
 PRIMARY KEY(receipt_id,position)
) WITHOUT ROWID;

CREATE TABLE tv_append_intents (
 id INTEGER PRIMARY KEY,
 recipe_id INTEGER REFERENCES rec_recipes(id) ON DELETE SET NULL,
 playlist_scope_id TEXT NOT NULL REFERENCES playlist_scopes(id),
 stream_token TEXT NOT NULL,
 request_id TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('pending','complete')),
 started_at REAL CHECK(started_at IS NULL OR (typeof(started_at) IN ('integer','real') AND abs(started_at)<=1.7976931348623157e308)),
 recovery_filename TEXT NOT NULL,
 recovery_digest TEXT NOT NULL CHECK(length(recovery_digest)=64),
 recovery_bytes INTEGER NOT NULL CHECK(typeof(recovery_bytes)='integer' AND recovery_bytes BETWEEN 1 AND 16777216),
 UNIQUE(playlist_scope_id,stream_token,request_id)
);

CREATE INDEX ix_tv_append_pending ON tv_append_intents(state,playlist_scope_id);

CREATE TABLE tv_append_items (
 intent_id INTEGER NOT NULL REFERENCES tv_append_intents(id),
 role TEXT NOT NULL CHECK(role IN ('before','additions','items')),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 video_id_snapshot TEXT NOT NULL CHECK(length(video_id_snapshot)>0),
 PRIMARY KEY(intent_id,role,position)
) WITHOUT ROWID;

CREATE TABLE radio_operations (
 session_id TEXT PRIMARY KEY REFERENCES radio_sessions(id),
 session_revision INTEGER NOT NULL CHECK(typeof(session_revision)='integer' AND session_revision>=1),
 kind TEXT NOT NULL CHECK(kind IN ('append','replacement')),
 sent INTEGER NOT NULL CHECK(typeof(sent)='integer' AND sent IN (0,1)),
 started_at REAL CHECK(started_at IS NULL OR (typeof(started_at) IN ('integer','real') AND abs(started_at)<=1.7976931348623157e308)),
 receipt_status TEXT,
 receipt_video_id_snapshot TEXT,
 receipt_handle_snapshot TEXT,
 allowed_count INTEGER NOT NULL CHECK(typeof(allowed_count)='integer' AND allowed_count>=0),
 waiting_present INTEGER NOT NULL CHECK(typeof(waiting_present)='integer' AND waiting_present IN (0,1)),
 play_prefix_present INTEGER NOT NULL CHECK(typeof(play_prefix_present)='integer' AND play_prefix_present IN (0,1)),
 adding_video_id_snapshot TEXT,
 slot INTEGER CHECK(slot IS NULL OR (typeof(slot)='integer' AND slot>=0)),
 choice_id TEXT
);

CREATE TABLE radio_operation_items (
 session_id TEXT NOT NULL REFERENCES radio_operations(session_id) ON DELETE CASCADE,
 role TEXT NOT NULL CHECK(role IN ('allowed','confirmed','waiting','play_prefix','proposed','excluded')),
 list_position INTEGER NOT NULL CHECK(typeof(list_position)='integer' AND list_position>=0),
 position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
 video_id_snapshot TEXT NOT NULL CHECK(length(video_id_snapshot)>0),
 PRIMARY KEY(session_id,role,list_position,position)
) WITHOUT ROWID;

CREATE INDEX ix_album_current_tracklist ON albums(current_tracklist_id);

CREATE TABLE album_tracklists (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    album_id INTEGER NOT NULL REFERENCES albums(id),
    provider TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),
    capture_kind TEXT NOT NULL CHECK(capture_kind IN ('provider','legacy_full','legacy_share','share')),
    status TEXT NOT NULL CHECK(status IN ('building','partial','complete','snapshot')),
    order_status TEXT NOT NULL CHECK(order_status IN ('known','unknown','mixed')),
    expected_count INTEGER CHECK(expected_count IS NULL OR (typeof(expected_count)='integer' AND expected_count>=0)),
    fetched_at REAL CHECK(fetched_at IS NULL OR (typeof(fetched_at) IN ('integer','real') AND fetched_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),
    CHECK((status<>'snapshot' OR capture_kind IN ('legacy_share','share')) AND (status<>'complete' OR capture_kind IN ('provider','legacy_full'))),
    FOREIGN KEY(provider,provider_id) REFERENCES album_provider_ids(provider,provider_id),
    UNIQUE(provider,provider_id,revision),
    UNIQUE(id,album_id)
);

CREATE INDEX ix_album_tracklist_owner ON album_tracklists(album_id,id);

CREATE TABLE album_track_occurrences (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tracklist_id INTEGER NOT NULL REFERENCES album_tracklists(id),
    position INTEGER CHECK(position IS NULL OR (typeof(position)='integer' AND position>=0)),
    disc_number INTEGER CHECK(disc_number IS NULL OR (typeof(disc_number)='integer' AND disc_number>0)),
    track_number INTEGER CHECK(track_number IS NULL OR (typeof(track_number)='integer' AND track_number>0)),
    recording_id INTEGER REFERENCES recordings(id),
    captured_title TEXT,
    captured_credit TEXT,
    raw_identity_key TEXT,
    raw_source_ref TEXT,
    captured_source TEXT,
    resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','unresolved','unavailable')),
    legacy_row_id INTEGER UNIQUE,
    CHECK((recording_id IS NOT NULL AND resolution_status='resolved') OR (recording_id IS NULL AND resolution_status IN ('unresolved','unavailable'))),
    UNIQUE(tracklist_id,position),
    UNIQUE(id,tracklist_id)
);

CREATE INDEX ix_album_occurrence_recording ON album_track_occurrences(recording_id,tracklist_id);

CREATE TABLE album_occurrence_sources (
    occurrence_id INTEGER NOT NULL REFERENCES album_track_occurrences(id),
    entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),
    provider TEXT NOT NULL CHECK(provider IN ('youtube','local','unresolved')),
    PRIMARY KEY(occurrence_id,entry_id,provider)
);

CREATE INDEX ix_album_occurrence_entry ON album_occurrence_sources(entry_id,occurrence_id);

CREATE TABLE album_item_observations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    album_id INTEGER NOT NULL REFERENCES albums(id),
    entry_id INTEGER REFERENCES catalog_entries(id),
    provider TEXT NOT NULL CHECK(length(trim(provider))>0),
    first_seen REAL,
    last_seen REAL,
    recording_id INTEGER REFERENCES recordings(id),
    raw_identity_key TEXT,
    legacy_row_id INTEGER UNIQUE,
    captured_position INTEGER,
    captured_disc_number INTEGER,
    captured_track_number INTEGER,
    CHECK(entry_id IS NOT NULL OR recording_id IS NOT NULL OR raw_identity_key IS NOT NULL),
    CHECK(first_seen IS NULL OR last_seen IS NULL OR first_seen<=last_seen)
);

CREATE UNIQUE INDEX ix_album_item_known ON album_item_observations(album_id,entry_id,provider) WHERE entry_id IS NOT NULL;

CREATE INDEX ix_album_item_entry ON album_item_observations(entry_id,album_id);

CREATE INDEX ix_album_item_recording ON album_item_observations(recording_id,album_id);

CREATE TABLE album_share_snapshots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    album_id INTEGER NOT NULL REFERENCES albums(id),
    tracklist_id INTEGER NOT NULL,
    captured_provider_id TEXT NOT NULL,
    title TEXT NOT NULL,
    created_at REAL,
    FOREIGN KEY(tracklist_id,album_id) REFERENCES album_tracklists(id,album_id) DEFERRABLE INITIALLY DEFERRED,
    UNIQUE(id,tracklist_id)
);

CREATE INDEX ix_album_share_provider ON album_share_snapshots(captured_provider_id,id DESC);

CREATE INDEX ix_album_share_owner ON album_share_snapshots(album_id,id DESC);

CREATE INDEX ix_album_share_tracklist ON album_share_snapshots(tracklist_id,id);

CREATE TABLE album_share_items (
    snapshot_id INTEGER NOT NULL,
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),
    tracklist_id INTEGER NOT NULL,
    occurrence_id INTEGER NOT NULL,
    entry_id INTEGER REFERENCES catalog_entries(id),
    raw_source_ref TEXT,
    CHECK(entry_id IS NOT NULL OR raw_source_ref IS NOT NULL),
    FOREIGN KEY(snapshot_id,tracklist_id) REFERENCES album_share_snapshots(id,tracklist_id),
    FOREIGN KEY(occurrence_id,tracklist_id) REFERENCES album_track_occurrences(id,tracklist_id),
    PRIMARY KEY(snapshot_id,position)
);

CREATE INDEX ix_album_share_occurrence ON album_share_items(occurrence_id);

CREATE VIEW album_tracks AS
    SELECT o.id,t.album_id,(SELECT min(s.entry_id) FROM album_occurrence_sources s WHERE s.occurrence_id=o.id) entry_id,
           CASE WHEN EXISTS(SELECT 1 FROM album_occurrence_sources s WHERE s.occurrence_id=o.id) THEN NULL ELSE o.recording_id END recording_id,
           o.raw_identity_key legacy_track_key,o.position,o.disc_number,o.track_number,1 is_full,coalesce(o.captured_source,'full_fetch') source
    FROM albums a JOIN album_tracklists t ON t.id=a.current_tracklist_id JOIN album_track_occurrences o ON o.tracklist_id=t.id
    UNION ALL
    SELECT -i.id,i.album_id,i.entry_id,i.recording_id,i.raw_identity_key,i.captured_position,i.captured_disc_number,i.captured_track_number,0,i.provider
    FROM album_item_observations i WHERE NOT EXISTS(
        SELECT 1 FROM albums a JOIN album_track_occurrences o ON o.tracklist_id=a.current_tracklist_id
        JOIN album_occurrence_sources s ON s.occurrence_id=o.id WHERE a.id=i.album_id AND s.entry_id=i.entry_id);

CREATE VIEW album_fetch_state AS
    SELECT a.id album_id,t.fetched_at,1 complete,t.expected_count expected_track_count
    FROM albums a JOIN album_tracklists t ON t.id=a.current_tracklist_id WHERE t.status='complete';

CREATE VIEW album_track_links AS
    SELECT min(t.id) id,p.provider_id browse_id,e.recording_id,t.entry_id,e.video_id,min(t.source) source
    FROM album_tracks t JOIN album_provider_ids p ON p.album_id=t.album_id AND p.provider='youtube'
    JOIN catalog_entries e ON e.id=t.entry_id GROUP BY p.provider_id,t.entry_id;

CREATE VIEW album_tracklist_keys AS
    SELECT p.provider_id browse_id,a.title,a.artist,a.thumbnail,
        (SELECT json_group_array(k) FROM (SELECT coalesce(r.identity_key,o.raw_identity_key) k
         FROM album_track_occurrences o LEFT JOIN recordings r ON r.id=o.recording_id
         WHERE o.tracklist_id=t.id ORDER BY o.position IS NULL,o.position,o.id)) track_keys
    FROM albums a JOIN album_tracklists t ON t.id=a.current_tracklist_id
    JOIN album_provider_ids p ON p.album_id=a.id AND p.provider='youtube' WHERE t.status='complete';

CREATE INDEX ix_listening_observation_unresolved_scope ON listening_observations
    (account_id,unresolved_subject_key,source_day,timezone)
    WHERE recording_id IS NULL AND precision='calendar_day';

CREATE INDEX ix_play_event_account_unresolved_time ON play_events
    (account_id,unresolved_subject_key,played_at) WHERE unresolved_subject_key IS NOT NULL;

CREATE TRIGGER choice_learning_parameters_owner_insert BEFORE INSERT ON choice_learning_parameters WHEN NOT EXISTS(SELECT 1 FROM choice_learning_publications WHERE id=NEW.publication_id AND surface IN ('choice_bandit','group_choice_bandit')) BEGIN SELECT RAISE(ABORT,'Wrong choice learning owner'); END;

CREATE TRIGGER choice_learning_parameters_owner_update BEFORE UPDATE ON choice_learning_parameters WHEN NOT EXISTS(SELECT 1 FROM choice_learning_publications WHERE id=NEW.publication_id AND surface IN ('choice_bandit','group_choice_bandit')) BEGIN SELECT RAISE(ABORT,'Wrong choice learning owner'); END;

