CREATE TRIGGER model_pair_files_insert BEFORE INSERT ON model_pair_files WHEN (SELECT status FROM model_pair_publications WHERE id=NEW.publication_id)<>'building' BEGIN SELECT RAISE(ABORT,'Published comparison child is immutable'); END;

CREATE TRIGGER model_pair_files_delete BEFORE DELETE ON model_pair_files WHEN (SELECT status FROM model_pair_publications WHERE id=OLD.publication_id)<>'retiring' BEGIN SELECT RAISE(ABORT,'Published comparison child is immutable'); END;

CREATE TRIGGER model_pair_files_update BEFORE UPDATE ON model_pair_files WHEN NEW.id<>OLD.id OR NEW.publication_id<>OLD.publication_id OR NEW.surface<>OLD.surface OR NEW.chunk_key<>OLD.chunk_key OR NEW.content_digest<>OLD.content_digest OR NEW.byte_size<>OLD.byte_size BEGIN SELECT RAISE(ABORT,'Published comparison child is immutable'); END;

