CREATE TRIGGER retired_recommendation_bucket_insert BEFORE INSERT ON rec_proposals BEGIN SELECT RAISE(ABORT,'Recommendation state requires its domain owner'); END;

CREATE TRIGGER retired_recommendation_bucket_update BEFORE UPDATE ON rec_proposals BEGIN SELECT RAISE(ABORT,'Recommendation state requires its domain owner'); END;

CREATE TABLE radio_seed_output (
    id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
    surface TEXT NOT NULL DEFAULT 'radio_seed_offer' CHECK(surface='radio_seed_offer'),
    chunk_key TEXT NOT NULL DEFAULT '' CHECK(chunk_key=''),
    menu_id TEXT CHECK(menu_id IS NULL OR length(menu_id) BETWEEN 1 AND 4096),
    comparison_run_id INTEGER CHECK(comparison_run_id IS NULL OR (typeof(comparison_run_id)='integer' AND comparison_run_id>0)),
    run_ref INTEGER REFERENCES rec_model_selection_runs(id),
    run_resolution TEXT,
    filename TEXT NOT NULL,
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64),
    byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 1048576),
    CHECK((comparison_run_id IS NULL AND run_ref IS NULL AND run_resolution IS NULL) OR
          (comparison_run_id IS NOT NULL AND ((run_ref IS NOT NULL AND run_ref=comparison_run_id AND run_resolution IS NULL) OR
           (run_ref IS NULL AND run_resolution IS NOT NULL AND run_resolution='missing_run'))))
);

CREATE TABLE radio_seed_subjects (
    offer_id INTEGER NOT NULL REFERENCES radio_seed_output(id),
    position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 999),
    video_id TEXT NOT NULL CHECK(length(video_id)>0),
    entry_id INTEGER REFERENCES catalog_entries(id),
    resolution_reason TEXT,
    PRIMARY KEY(offer_id,position),
    CHECK((entry_id IS NOT NULL AND resolution_reason IS NULL) OR
          (entry_id IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_entry'))
) WITHOUT ROWID;

CREATE TABLE radio_seed_policies (
    offer_id INTEGER NOT NULL REFERENCES radio_seed_output(id),
    raw_version TEXT NOT NULL,
    policy_version TEXT REFERENCES recommendation_policies(version),
    resolution_reason TEXT,
    PRIMARY KEY(offer_id,raw_version),
    CHECK((policy_version IS NOT NULL AND policy_version=raw_version AND resolution_reason IS NULL) OR
          (policy_version IS NULL AND resolution_reason IS NOT NULL AND resolution_reason='missing_policy'))
) WITHOUT ROWID;

CREATE INDEX ix_radio_seed_policies ON radio_seed_policies(policy_version);

CREATE TABLE model_autotune_output (
    id INTEGER PRIMARY KEY NOT NULL CHECK(id=1),
    surface TEXT NOT NULL DEFAULT 'rec_autotune_result' CHECK(surface='rec_autotune_result'),
    chunk_key TEXT NOT NULL DEFAULT '' CHECK(chunk_key=''),
    observed_at REAL CHECK(observed_at IS NULL OR (typeof(observed_at) IN ('integer','real') AND abs(observed_at)<=1.7976931348623157e308)),
    filename TEXT NOT NULL,
    content_digest TEXT NOT NULL CHECK(length(content_digest)=64),
    byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 1048576)
);

CREATE TRIGGER saved_recommendation_settings_insert BEFORE INSERT ON settings WHEN NEW.key IN ('radio_seed_offer','rec_autotune_result') BEGIN SELECT RAISE(ABORT,'Saved recommendation output requires its domain owner'); END;

CREATE TRIGGER radio_seed_subject_insert BEFORE INSERT ON radio_seed_subjects WHEN NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=NEW.entry_id AND video_id=NEW.video_id) BEGIN SELECT RAISE(ABORT,'Radio seed does not match its catalog entry'); END;

CREATE TRIGGER saved_recommendation_settings_update BEFORE UPDATE ON settings WHEN NEW.key IN ('radio_seed_offer','rec_autotune_result') BEGIN SELECT RAISE(ABORT,'Saved recommendation output requires its domain owner'); END;

CREATE TRIGGER radio_seed_subject_update BEFORE UPDATE ON radio_seed_subjects WHEN NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=NEW.entry_id AND video_id=NEW.video_id) BEGIN SELECT RAISE(ABORT,'Radio seed does not match its catalog entry'); END;

CREATE TRIGGER model_comparison_plan_fields_insert BEFORE INSERT ON model_comparison_plan WHEN NEW.policy_mask>2047 OR NEW.previous_mask>3 OR NEW.challenger_mask>3 BEGIN SELECT RAISE(ABORT,'Invalid model comparison fields'); END;

CREATE TRIGGER model_comparison_plan_fields_update BEFORE UPDATE ON model_comparison_plan WHEN NEW.policy_mask>2047 OR NEW.previous_mask>3 OR NEW.challenger_mask>3 BEGIN SELECT RAISE(ABORT,'Invalid model comparison fields'); END;

CREATE TRIGGER model_listening_monitor_fields_insert BEFORE INSERT ON model_listening_monitor WHEN NEW.policy_mask>2047 OR NEW.setup_mask>3 BEGIN SELECT RAISE(ABORT,'Invalid model comparison fields'); END;

CREATE TRIGGER model_listening_monitor_fields_update BEFORE UPDATE ON model_listening_monitor WHEN NEW.policy_mask>2047 OR NEW.setup_mask>3 BEGIN SELECT RAISE(ABORT,'Invalid model comparison fields'); END;

CREATE TRIGGER model_album_assignment_fields_insert BEFORE INSERT ON model_album_assignment WHEN NEW.comparison_mask>1023 OR (typeof(NEW.epoch)='text' AND length(NEW.epoch) NOT BETWEEN 1 AND 4096) BEGIN SELECT RAISE(ABORT,'Invalid model comparison fields'); END;

CREATE TRIGGER model_album_assignment_fields_update BEFORE UPDATE ON model_album_assignment WHEN NEW.comparison_mask>1023 OR (typeof(NEW.epoch)='text' AND length(NEW.epoch) NOT BETWEEN 1 AND 4096) BEGIN SELECT RAISE(ABORT,'Invalid model comparison fields'); END;

CREATE TRIGGER taste_control_settings_insert BEFORE INSERT ON settings WHEN NEW.key IN ('ppr_experiment_decisions','taste_comparison_baseline_v2','taste_settings_checkpoint_v1') BEGIN SELECT RAISE(ABORT,'Taste controls require their domain owner'); END;

CREATE TRIGGER taste_control_settings_update BEFORE UPDATE ON settings WHEN NEW.key IN ('ppr_experiment_decisions','taste_comparison_baseline_v2','taste_settings_checkpoint_v1') BEGIN SELECT RAISE(ABORT,'Taste controls require their domain owner'); END;

CREATE TRIGGER spotify_import_job_account_update BEFORE UPDATE ON spotify_import_jobs WHEN NEW.account_id IS NOT OLD.account_id OR NEW.unresolved_account_id IS NOT OLD.unresolved_account_id OR NEW.account_present IS NOT OLD.account_present BEGIN SELECT RAISE(ABORT,'Spotify import job account cannot change'); END;

CREATE TRIGGER spotify_import_settings_insert BEFORE INSERT ON settings WHEN NEW.key='spotify_library_import_job' BEGIN SELECT RAISE(ABORT,'Spotify import state requires its job owner'); END;

CREATE TRIGGER spotify_import_settings_update BEFORE UPDATE ON settings WHEN NEW.key='spotify_library_import_job' BEGIN SELECT RAISE(ABORT,'Spotify import state requires its job owner'); END;

CREATE TRIGGER playlist_recipe_facet_insert BEFORE INSERT ON playlist_recipe_facets WHEN NOT EXISTS (SELECT 1 FROM taste_axes a WHERE a.id=NEW.axis_id AND ((NEW.kind='genre' AND a.kind IN ('genre','family','unresolved_genre')) OR (NEW.kind='era' AND a.kind='other' AND a.value='era:'||NEW.captured_value))) BEGIN SELECT RAISE(ABORT,'Playlist recipe facet axis disagrees with its kind'); END;

CREATE TRIGGER playlist_recipe_facet_update BEFORE UPDATE ON playlist_recipe_facets WHEN NOT EXISTS (SELECT 1 FROM taste_axes a WHERE a.id=NEW.axis_id AND ((NEW.kind='genre' AND a.kind IN ('genre','family','unresolved_genre')) OR (NEW.kind='era' AND a.kind='other' AND a.value='era:'||NEW.captured_value))) BEGIN SELECT RAISE(ABORT,'Playlist recipe facet axis disagrees with its kind'); END;

CREATE TRIGGER action_identity BEFORE UPDATE ON actions WHEN NEW.id<>OLD.id OR NEW.kind<>OLD.kind OR NEW.idempotency_key<>OLD.idempotency_key OR NEW.intent_digest<>OLD.intent_digest OR NEW.parent_action_id IS NOT OLD.parent_action_id OR NEW.undo_of_action_id IS NOT OLD.undo_of_action_id OR NEW.created_at IS NOT OLD.created_at OR NEW.execution_mode IS NOT OLD.execution_mode OR (OLD.reviewed_draft_id IS NOT NULL AND (NEW.reviewed_draft_id IS NOT OLD.reviewed_draft_id OR NEW.reviewed_draft_revision IS NOT OLD.reviewed_draft_revision OR NEW.reviewed_draft_signature IS NOT OLD.reviewed_draft_signature)) BEGIN SELECT RAISE(ABORT,'Committed action identity and reviewed revision cannot change'); END;

CREATE TRIGGER action_status_transition BEFORE UPDATE ON actions WHEN NEW.status<>OLD.status AND NOT ((OLD.status='draft' AND NEW.status IN ('cancelled')) OR (OLD.status='planned' AND NEW.status IN ('executing','executed','delete_pending','delete_failed','failed','cancelled')) OR (OLD.status='pending' AND NEW.status IN ('executing','executed','failed','cancelled')) OR (OLD.status='executing' AND NEW.status IN ('executed','delete_pending','delete_failed','failed')) OR (OLD.status='executed' AND NEW.status IN ('undoing','delete_pending','delete_failed')) OR (OLD.status='delete_pending' AND NEW.status IN ('executed','delete_failed')) OR (OLD.status='delete_failed' AND NEW.status IN ('delete_pending','executed','undoing')) OR (OLD.status='undoing' AND NEW.status IN ('undo_failed','undone')) OR (OLD.status='undo_failed' AND NEW.status IN ('undoing')) OR (OLD.status='failed' AND NEW.status IN ('executing','cancelled'))) BEGIN SELECT RAISE(ABORT,'Invalid action status transition'); END;

CREATE TRIGGER action_reviewed_draft_insert BEFORE INSERT ON actions WHEN NEW.reviewed_draft_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM action_drafts d WHERE d.id=NEW.reviewed_draft_id AND d.revision=NEW.reviewed_draft_revision AND d.signature=NEW.reviewed_draft_signature) BEGIN SELECT RAISE(ABORT,'Reviewed draft revision is no longer current'); END;

CREATE TRIGGER action_draft_owner_insert BEFORE INSERT ON action_drafts WHEN NOT EXISTS (SELECT 1 FROM actions a WHERE a.id=NEW.id AND a.kind='merge_draft' AND a.status='draft') BEGIN SELECT RAISE(ABORT,'Mutable preparation requires its draft action'); END;

CREATE TRIGGER action_reviewed_draft_update BEFORE UPDATE ON actions WHEN NEW.reviewed_draft_id IS NOT NULL AND OLD.reviewed_draft_id IS NULL AND NOT EXISTS (SELECT 1 FROM action_drafts d WHERE d.id=NEW.reviewed_draft_id AND d.revision=NEW.reviewed_draft_revision AND d.signature=NEW.reviewed_draft_signature) BEGIN SELECT RAISE(ABORT,'Reviewed draft revision is no longer current'); END;

CREATE TRIGGER action_draft_owner_update BEFORE UPDATE ON action_drafts WHEN NOT EXISTS (SELECT 1 FROM actions a WHERE a.id=NEW.id AND a.kind='merge_draft' AND a.status='draft') BEGIN SELECT RAISE(ABORT,'Mutable preparation requires its draft action'); END;

CREATE TRIGGER action_target_agreement_insert BEFORE INSERT ON action_targets WHEN (NEW.playlist_scope_id IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id_snapshot AND ((s.kind='shared' AND s.account_id IS NULL) OR (s.kind='account' AND s.account_id=NEW.account_id))))) OR (NEW.membership_ref_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.membership_ref_id AND m.playlist_scope_id IS NEW.playlist_scope_id AND m.account_id IS NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Action target disagrees with its account, scope or membership'); END;

CREATE TRIGGER action_target_agreement_update BEFORE UPDATE ON action_targets WHEN (NEW.playlist_scope_id IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id_snapshot AND ((s.kind='shared' AND s.account_id IS NULL) OR (s.kind='account' AND s.account_id=NEW.account_id))))) OR (NEW.membership_ref_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.membership_ref_id AND m.playlist_scope_id IS NEW.playlist_scope_id AND m.account_id IS NEW.account_id)) BEGIN SELECT RAISE(ABORT,'Action target disagrees with its account, scope or membership'); END;

CREATE TRIGGER action_target_immutable BEFORE UPDATE ON action_targets BEGIN SELECT RAISE(ABORT,'Committed action targets are immutable'); END;

CREATE TRIGGER action_history_delete BEFORE DELETE ON actions WHEN OLD.kind<>'merge_draft' BEGIN SELECT RAISE(ABORT,'Action history is retained for recovery and links'); END;

CREATE TRIGGER action_step_identity BEFORE UPDATE ON action_steps WHEN NEW.action_id<>OLD.action_id OR NEW.target_id IS NOT OLD.target_id OR NEW.position<>OLD.position OR NEW.operation<>OLD.operation BEGIN SELECT RAISE(ABORT,'Committed action step identity cannot change'); END;

CREATE TRIGGER action_step_completion BEFORE UPDATE ON action_steps WHEN OLD.phase='complete' AND NEW.phase<>'complete' BEGIN SELECT RAISE(ABORT,'A completed recovery step cannot reopen'); END;

CREATE TRIGGER action_step_creation BEFORE UPDATE ON action_steps WHEN (OLD.creation_marker IS NOT NULL AND NEW.creation_marker IS NOT OLD.creation_marker) OR (OLD.created_provider_id_snapshot IS NOT NULL AND NEW.created_provider_id_snapshot IS NOT OLD.created_provider_id_snapshot) BEGIN SELECT RAISE(ABORT,'A committed recovery creation cannot change its marker or destination'); END;

CREATE TRIGGER action_step_transition BEFORE UPDATE ON action_steps WHEN NEW.phase<>OLD.phase AND NOT ((OLD.phase='prepared' AND NEW.phase IN ('pending','cancelled')) OR (OLD.phase='pending' AND NEW.phase IN ('uncertain','failed','creating','created','restoring','deleting','remote_complete','complete','cancelled')) OR (OLD.phase='uncertain' AND NEW.phase IN ('failed','remote_complete','complete','restoring')) OR (OLD.phase='failed' AND NEW.phase IN ('pending','uncertain','deleting','restoring','creating','created','remote_complete','complete','cancelled')) OR (OLD.phase='creating' AND NEW.phase IN ('pending','created','failed','remote_complete')) OR (OLD.phase='created' AND NEW.phase IN ('restoring','remote_complete','complete')) OR (OLD.phase='restoring' AND NEW.phase IN ('remote_complete','failed','complete')) OR (OLD.phase='deleting' AND NEW.phase IN ('failed','remote_complete','complete')) OR (OLD.phase='remote_complete' AND NEW.phase IN ('complete'))) BEGIN SELECT RAISE(ABORT,'Invalid action step transition'); END;

CREATE TRIGGER action_step_backup BEFORE UPDATE ON action_steps WHEN OLD.backup_status='verified' AND (NEW.backup_status<>OLD.backup_status OR NEW.backup_digest IS NOT OLD.backup_digest OR NEW.backup_bytes IS NOT OLD.backup_bytes) BEGIN SELECT RAISE(ABORT,'Committed backup content cannot change'); END;

CREATE TRIGGER action_created_scope_insert BEFORE INSERT ON action_steps WHEN NEW.created_playlist_scope_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_scopes s JOIN action_targets t ON t.id=NEW.target_id WHERE s.id=NEW.created_playlist_scope_id AND s.provider_playlist_id=NEW.created_provider_id_snapshot AND (s.kind='shared' OR (s.kind='account' AND s.account_id=t.account_id))) BEGIN SELECT RAISE(ABORT,'Recovery creation scope disagrees with its target'); END;

CREATE TRIGGER retired_workflow_settings_insert BEFORE INSERT ON settings WHEN substr(NEW.key,1,18)='playlist_gc_retry:' OR NEW.key IN ('spotify_library_imported_playlists','spotify_library_imported_albums') OR substr(NEW.key,1,35)='spotify_library_imported_playlists:' OR substr(NEW.key,1,32)='spotify_library_imported_albums:' BEGIN SELECT RAISE(ABORT,'Workflow settings require their explicit owner'); END;

CREATE TRIGGER playlist_gc_attempts_scope_insert BEFORE INSERT ON playlist_gc_attempts WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id_snapshot AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id))) BEGIN SELECT RAISE(ABORT,'Workflow receipt disagrees with its account and playlist scope'); END;

CREATE TRIGGER spotify_transfer_receipts_scope_insert BEFORE INSERT ON spotify_transfer_receipts WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id_snapshot AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id))) BEGIN SELECT RAISE(ABORT,'Workflow receipt disagrees with its account and playlist scope'); END;

CREATE TRIGGER action_created_scope_update BEFORE UPDATE ON action_steps WHEN NEW.created_playlist_scope_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_scopes s JOIN action_targets t ON t.id=NEW.target_id WHERE s.id=NEW.created_playlist_scope_id AND s.provider_playlist_id=NEW.created_provider_id_snapshot AND (s.kind='shared' OR (s.kind='account' AND s.account_id=t.account_id))) BEGIN SELECT RAISE(ABORT,'Recovery creation scope disagrees with its target'); END;

CREATE TRIGGER retired_workflow_settings_update BEFORE UPDATE ON settings WHEN substr(NEW.key,1,18)='playlist_gc_retry:' OR NEW.key IN ('spotify_library_imported_playlists','spotify_library_imported_albums') OR substr(NEW.key,1,35)='spotify_library_imported_playlists:' OR substr(NEW.key,1,32)='spotify_library_imported_albums:' BEGIN SELECT RAISE(ABORT,'Workflow settings require their explicit owner'); END;

CREATE TRIGGER playlist_gc_attempts_scope_update BEFORE UPDATE ON playlist_gc_attempts WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id_snapshot AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id))) BEGIN SELECT RAISE(ABORT,'Workflow receipt disagrees with its account and playlist scope'); END;

CREATE TRIGGER spotify_transfer_receipts_scope_update BEFORE UPDATE ON spotify_transfer_receipts WHEN NEW.playlist_scope_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM playlist_scopes s WHERE s.id=NEW.playlist_scope_id AND s.provider_playlist_id=NEW.provider_playlist_id_snapshot AND (s.kind='shared' OR (s.kind='account' AND s.account_id=NEW.account_id))) BEGIN SELECT RAISE(ABORT,'Workflow receipt disagrees with its account and playlist scope'); END;

CREATE TRIGGER spotify_transfer_destination BEFORE UPDATE ON spotify_transfer_receipts WHEN NEW.captured_account_id IS NOT OLD.captured_account_id OR NEW.account_id IS NOT OLD.account_id OR NEW.source_kind<>OLD.source_kind OR NEW.fingerprint<>OLD.fingerprint OR (OLD.marker IS NOT NULL AND NEW.marker IS NOT OLD.marker) OR (OLD.provider_playlist_id_snapshot IS NOT NULL AND NEW.provider_playlist_id_snapshot IS NOT OLD.provider_playlist_id_snapshot) BEGIN SELECT RAISE(ABORT,'Committed Spotify transfer ownership cannot change'); END;

CREATE TRIGGER tv_append_completed BEFORE UPDATE ON tv_append_intents WHEN OLD.state='complete' AND NEW.state<>'complete' BEGIN SELECT RAISE(ABORT,'Completed TV append cannot reopen'); END;

CREATE TRIGGER tv_append_recipe_insert BEFORE INSERT ON tv_append_intents WHEN NEW.recipe_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rec_recipes r WHERE r.id=NEW.recipe_id AND r.playlist_scope_id=NEW.playlist_scope_id) BEGIN SELECT RAISE(ABORT,'TV append belongs to another recipe scope'); END;

CREATE TRIGGER radio_operation_revision_insert BEFORE INSERT ON radio_operations WHEN NOT EXISTS(SELECT 1 FROM radio_sessions s WHERE s.id=NEW.session_id AND s.revision=NEW.session_revision) BEGIN SELECT RAISE(ABORT,'Radio operation belongs to another session revision'); END;

CREATE TRIGGER tv_append_recipe_update BEFORE UPDATE ON tv_append_intents WHEN NEW.recipe_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rec_recipes r WHERE r.id=NEW.recipe_id AND r.playlist_scope_id=NEW.playlist_scope_id) BEGIN SELECT RAISE(ABORT,'TV append belongs to another recipe scope'); END;

CREATE TRIGGER radio_operation_revision_update BEFORE UPDATE ON radio_operations WHEN NOT EXISTS(SELECT 1 FROM radio_sessions s WHERE s.id=NEW.session_id AND s.revision=NEW.session_revision) BEGIN SELECT RAISE(ABORT,'Radio operation belongs to another session revision'); END;

CREATE TRIGGER playlist_revision_action_targets_insert AFTER INSERT ON action_targets WHEN NEW.role='placement' BEGIN INSERT INTO playlist_library_revisions SELECT NEW.playlist_scope_id,NEW.account_id,1 FROM actions a WHERE a.id=NEW.action_id AND a.kind='add_tracks' AND a.status='pending' AND NEW.playlist_scope_id IS NOT NULL AND NEW.account_id IS NOT NULL ON CONFLICT(playlist_scope_id,account_id) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER playlist_revision_action_targets_delete AFTER DELETE ON action_targets WHEN OLD.role='placement' BEGIN INSERT INTO playlist_library_revisions SELECT OLD.playlist_scope_id,OLD.account_id,1 FROM actions a WHERE a.id=OLD.action_id AND a.kind='add_tracks' AND a.status='pending' AND OLD.playlist_scope_id IS NOT NULL AND OLD.account_id IS NOT NULL ON CONFLICT(playlist_scope_id,account_id) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER playlist_revision_actions_update AFTER UPDATE ON actions WHEN NEW.kind='add_tracks' AND (OLD.status='pending' OR NEW.status='pending') BEGIN INSERT INTO playlist_library_revisions SELECT playlist_scope_id,account_id,1 FROM action_targets WHERE action_id=NEW.id AND role='placement' AND playlist_scope_id IS NOT NULL AND account_id IS NOT NULL ON CONFLICT(playlist_scope_id,account_id) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER album_current_tracklist_insert BEFORE INSERT ON albums WHEN NEW.current_tracklist_id IS NOT NULL AND NOT (EXISTS(SELECT 1 FROM album_tracklists t WHERE t.id=NEW.current_tracklist_id AND t.album_id=NEW.id AND t.status='complete' AND t.expected_count>0 AND t.expected_count=(SELECT count(*) FROM album_track_occurrences o WHERE o.tracklist_id=t.id))) BEGIN SELECT RAISE(ABORT,'Album current tracklist is not a complete owned publication'); END;

CREATE TRIGGER album_source_agreement_insert BEFORE INSERT ON album_occurrence_sources WHEN NOT EXISTS(SELECT 1 FROM album_track_occurrences o JOIN catalog_entries e ON e.id=NEW.entry_id WHERE o.id=NEW.occurrence_id AND o.recording_id=e.recording_id AND ((NEW.provider='youtube' AND e.video_id IS NOT NULL) OR (NEW.provider='local' AND e.source_ref LIKE 'local:%') OR (NEW.provider='unresolved' AND e.source_ref IS NOT NULL AND e.source_ref NOT LIKE 'local:%'))) BEGIN SELECT RAISE(ABORT,'Album occurrence source disagrees with its subject or provider'); END;

CREATE TRIGGER album_tracklist_provider_insert BEFORE INSERT ON album_tracklists WHEN NOT EXISTS(SELECT 1 FROM album_provider_ids p WHERE p.provider=NEW.provider AND p.provider_id=NEW.provider_id AND p.album_id=NEW.album_id) BEGIN SELECT RAISE(ABORT,'Album tracklist belongs to another provider representation'); END;

CREATE TRIGGER album_share_source_insert BEFORE INSERT ON album_share_items WHEN NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM album_occurrence_sources s WHERE s.occurrence_id=NEW.occurrence_id AND s.entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'Frozen album source does not belong to its occurrence'); END;

CREATE TRIGGER album_current_tracklist_update BEFORE UPDATE ON albums WHEN NEW.current_tracklist_id IS NOT NULL AND NOT (EXISTS(SELECT 1 FROM album_tracklists t WHERE t.id=NEW.current_tracklist_id AND t.album_id=NEW.id AND t.status='complete' AND t.expected_count>0 AND t.expected_count=(SELECT count(*) FROM album_track_occurrences o WHERE o.tracklist_id=t.id))) BEGIN SELECT RAISE(ABORT,'Album current tracklist is not a complete owned publication'); END;

CREATE TRIGGER album_source_agreement_update BEFORE UPDATE ON album_occurrence_sources WHEN NOT EXISTS(SELECT 1 FROM album_track_occurrences o JOIN catalog_entries e ON e.id=NEW.entry_id WHERE o.id=NEW.occurrence_id AND o.recording_id=e.recording_id AND ((NEW.provider='youtube' AND e.video_id IS NOT NULL) OR (NEW.provider='local' AND e.source_ref LIKE 'local:%') OR (NEW.provider='unresolved' AND e.source_ref IS NOT NULL AND e.source_ref NOT LIKE 'local:%'))) BEGIN SELECT RAISE(ABORT,'Album occurrence source disagrees with its subject or provider'); END;

CREATE TRIGGER album_tracklist_provider_update BEFORE UPDATE ON album_tracklists WHEN NOT EXISTS(SELECT 1 FROM album_provider_ids p WHERE p.provider=NEW.provider AND p.provider_id=NEW.provider_id AND p.album_id=NEW.album_id) BEGIN SELECT RAISE(ABORT,'Album tracklist belongs to another provider representation'); END;

CREATE TRIGGER album_share_source_update BEFORE UPDATE ON album_share_items WHEN NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM album_occurrence_sources s WHERE s.occurrence_id=NEW.occurrence_id AND s.entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'Frozen album source does not belong to its occurrence'); END;

CREATE TRIGGER album_tracklist_finish BEFORE UPDATE ON album_tracklists WHEN NEW.status IN ('complete','snapshot') AND (NEW.expected_count IS NULL OR NEW.expected_count<>(SELECT count(*) FROM album_track_occurrences WHERE tracklist_id=NEW.id) OR (NEW.status='complete' AND NEW.expected_count=0) OR (NEW.order_status='known' AND EXISTS(SELECT 1 FROM album_track_occurrences WHERE tracklist_id=NEW.id AND position IS NULL)) OR (NEW.order_status='unknown' AND EXISTS(SELECT 1 FROM album_track_occurrences WHERE tracklist_id=NEW.id AND position IS NOT NULL)) OR (NEW.order_status='known' AND NEW.expected_count>0 AND ((SELECT min(position) FROM album_track_occurrences WHERE tracklist_id=NEW.id)<>0 OR (SELECT max(position) FROM album_track_occurrences WHERE tracklist_id=NEW.id)<>NEW.expected_count-1))) BEGIN SELECT RAISE(ABORT,'Album tracklist count or captured order is incomplete'); END;

CREATE TRIGGER album_tracklist_initial BEFORE INSERT ON album_tracklists WHEN NEW.status<>'building' BEGIN SELECT RAISE(ABORT,'Album tracklists must be built before publication'); END;

CREATE TRIGGER album_tracklist_frozen BEFORE UPDATE ON album_tracklists WHEN OLD.status<>'building' AND (NEW.id<>OLD.id OR NEW.provider<>OLD.provider OR NEW.provider_id<>OLD.provider_id OR NEW.revision<>OLD.revision OR NEW.capture_kind<>OLD.capture_kind OR NEW.status<>OLD.status OR NEW.order_status<>OLD.order_status OR NEW.expected_count IS NOT OLD.expected_count OR NEW.fetched_at IS NOT OLD.fetched_at) BEGIN SELECT RAISE(ABORT,'Published album capture cannot change'); END;

CREATE TRIGGER album_occurrence_frozen_insert BEFORE INSERT ON album_track_occurrences WHEN EXISTS(SELECT 1 FROM album_tracklists WHERE id=NEW.tracklist_id AND status<>'building') BEGIN SELECT RAISE(ABORT,'Published album occurrences are retained'); END;

CREATE TRIGGER album_occurrence_frozen_delete BEFORE DELETE ON album_track_occurrences WHEN EXISTS(SELECT 1 FROM album_tracklists WHERE id=OLD.tracklist_id AND status<>'building' AND (capture_kind<>'provider' OR EXISTS(SELECT 1 FROM albums a WHERE a.current_tracklist_id=album_tracklists.id) OR EXISTS(SELECT 1 FROM album_share_snapshots s WHERE s.tracklist_id=album_tracklists.id))) BEGIN SELECT RAISE(ABORT,'Published album occurrences are retained'); END;

CREATE TRIGGER album_occurrence_frozen_update BEFORE UPDATE ON album_track_occurrences WHEN EXISTS(SELECT 1 FROM album_tracklists WHERE id=OLD.tracklist_id AND status<>'building') AND (NEW.id<>OLD.id OR NEW.tracklist_id<>OLD.tracklist_id OR NEW.position IS NOT OLD.position OR NEW.disc_number IS NOT OLD.disc_number OR NEW.track_number IS NOT OLD.track_number OR NEW.captured_title IS NOT OLD.captured_title OR NEW.captured_credit IS NOT OLD.captured_credit OR NEW.raw_identity_key IS NOT OLD.raw_identity_key OR NEW.raw_source_ref IS NOT OLD.raw_source_ref OR NEW.captured_source IS NOT OLD.captured_source OR NEW.legacy_row_id IS NOT OLD.legacy_row_id) BEGIN SELECT RAISE(ABORT,'Published album occurrence capture cannot change'); END;

CREATE TRIGGER album_occurrence_resolution BEFORE UPDATE ON album_track_occurrences WHEN EXISTS(SELECT 1 FROM album_occurrence_sources s JOIN catalog_entries e ON e.id=s.entry_id WHERE s.occurrence_id=NEW.id AND e.recording_id IS NOT NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Album occurrence resolution disagrees with its sources'); END;

CREATE TRIGGER album_source_reassociation AFTER UPDATE OF recording_id ON catalog_entries WHEN NEW.recording_id<>OLD.recording_id BEGIN UPDATE album_track_occurrences SET recording_id=NEW.recording_id WHERE id IN (SELECT occurrence_id FROM album_occurrence_sources WHERE entry_id=NEW.id); END;

CREATE TRIGGER album_source_frozen_update BEFORE UPDATE ON album_occurrence_sources WHEN EXISTS(SELECT 1 FROM album_track_occurrences o JOIN album_tracklists t ON t.id=o.tracklist_id WHERE o.id=OLD.occurrence_id AND t.status<>'building') BEGIN SELECT RAISE(ABORT,'Published album source evidence is retained'); END;

CREATE TRIGGER album_source_frozen_delete BEFORE DELETE ON album_occurrence_sources WHEN EXISTS(SELECT 1 FROM album_track_occurrences o JOIN album_tracklists t ON t.id=o.tracklist_id WHERE o.id=OLD.occurrence_id AND t.status<>'building' AND (t.capture_kind<>'provider' OR EXISTS(SELECT 1 FROM albums a WHERE a.current_tracklist_id=t.id) OR EXISTS(SELECT 1 FROM album_share_snapshots s WHERE s.tracklist_id=t.id))) BEGIN SELECT RAISE(ABORT,'Published album source evidence is retained'); END;

CREATE TRIGGER album_share_snapshots_frozen BEFORE UPDATE ON album_share_snapshots WHEN NEW.id<>OLD.id OR NEW.tracklist_id<>OLD.tracklist_id OR NEW.captured_provider_id<>OLD.captured_provider_id OR NEW.title<>OLD.title OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'Frozen album share cannot change'); END;

CREATE TRIGGER album_share_snapshots_retained BEFORE DELETE ON album_share_snapshots BEGIN SELECT RAISE(ABORT,'Frozen album share is retained'); END;

CREATE TRIGGER album_share_items_frozen BEFORE UPDATE ON album_share_items BEGIN SELECT RAISE(ABORT,'Frozen album share cannot change'); END;

CREATE TRIGGER album_share_items_retained BEFORE DELETE ON album_share_items BEGIN SELECT RAISE(ABORT,'Frozen album share is retained'); END;

CREATE TRIGGER rec_capture_album_item_observations_insert AFTER INSERT ON album_item_observations BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_item_observations_update AFTER UPDATE ON album_item_observations BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_item_observations_delete AFTER DELETE ON album_item_observations BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_track_occurrences_insert AFTER INSERT ON album_track_occurrences BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_track_occurrences_update AFTER UPDATE ON album_track_occurrences BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_track_occurrences_delete AFTER DELETE ON album_track_occurrences BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_occurrence_sources_insert AFTER INSERT ON album_occurrence_sources BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_occurrence_sources_update AFTER UPDATE ON album_occurrence_sources BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_occurrence_sources_delete AFTER DELETE ON album_occurrence_sources BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER rec_capture_album_publication AFTER UPDATE OF current_tracklist_id ON albums WHEN OLD.current_tracklist_id IS NOT NEW.current_tracklist_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; UPDATE rec_preparation SET evidence_changes=evidence_changes+1 WHERE id=1; END;

CREATE TRIGGER play_event_membership_insert BEFORE INSERT ON play_events WHEN NEW.membership_ref_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_membership_refs m JOIN playlist_scopes s ON s.id=m.playlist_scope_id WHERE m.id=NEW.membership_ref_id AND m.account_id=NEW.account_id AND (NEW.playlist_ytm_id=s.provider_playlist_id OR NEW.playlist_ytm_id='RDAMPL'||s.provider_playlist_id)) BEGIN SELECT RAISE(ABORT,'Listening membership disagrees with captured account or playlist'); END;

CREATE TRIGGER play_event_membership_update BEFORE UPDATE ON play_events WHEN NEW.membership_ref_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM playlist_membership_refs m JOIN playlist_scopes s ON s.id=m.playlist_scope_id WHERE m.id=NEW.membership_ref_id AND m.account_id=NEW.account_id AND (NEW.playlist_ytm_id=s.provider_playlist_id OR NEW.playlist_ytm_id='RDAMPL'||s.provider_playlist_id)) BEGIN SELECT RAISE(ABORT,'Listening membership disagrees with captured account or playlist'); END;

CREATE TRIGGER listening_summary_play_events_insert AFTER INSERT ON play_events BEGIN INSERT INTO listening_summary_state(id,input_revision) VALUES (1,1) ON CONFLICT(id) DO UPDATE SET input_revision=input_revision+1; END;

CREATE TRIGGER listening_summary_play_events_update AFTER UPDATE ON play_events BEGIN INSERT INTO listening_summary_state(id,input_revision) VALUES (1,1) ON CONFLICT(id) DO UPDATE SET input_revision=input_revision+1; END;

